/// What a Dart value can be *asked*.
///
/// `x is Foo` wants to know what a value really is, and a Rust trait object
/// cannot be asked unless the trait says it can. `Any` is the mechanism; this
/// is the one line of it that every translated trait inherits, so every trait
/// object can answer.
///
/// Not a blanket impl. `Box<dyn Widget>` would then implement it *itself*, and
/// `.as_any()` would answer about the box rather than about what is in it --
/// a downcast that is always false and never says so. Each translated struct
/// gets its own one-line impl instead, so the only way to reach `as_any` from
/// a box is through the trait inside it.
/// `Object` above it: an `Rc<dyn Widget>` then unsizes to an `Rc<dyn
/// Object>` (trait upcasting), which no `impl Object for dyn Widget` could
/// give -- a coercion needs the supertrait. `as_any` is `Object`'s.
/// Dart's `T?` for a `T` that may be nullable already. `T?` with `T` bound
/// to `Color?` is `Color?` -- one layer, Dart collapses them -- where Rust's
/// `Option<Option<Color>>` is two. Generic code spells a `T?` in its
/// signature and its fields as `<T as DartNullable>::Or`, which is `Option<T>`
/// for a plain `T` and `Option<X>` again for `T = Option<X>`, and converts
/// at its edges: a parameter or a field read comes in through `option`, a
/// result or a field write goes out through `from_option`. Every type a
/// type parameter can be bound to implements it; the backend writes the
/// impl for each translated struct and enum.
pub trait DartNullable: Sized {
    /// Not `Clone` by itself -- `Vec<T>` is one only for `T: Clone` --
    /// so a declaration that clones a `T?` asks `DartNullable<Or: Clone>`.
    /// Its own `Or` again: `T?` with `T` bound to `U?` is `U?`, and this
    /// is what lets rustc read `<<U as DartNullable>::Or as DartNullable>
    /// ::Or` as `<U as DartNullable>::Or`.
    type Or: DartNullable<Or = Self::Or>;
    /// The `Option<Self>` a body works with, from the spelled `T?`.
    fn option(or: Self::Or) -> Option<Self>;
    /// The spelled `T?` from a body's `Option<Self>`.
    fn from_option(option: Option<Self>) -> Self::Or;
    /// Whether a value of this type is Dart's null: only an `Option`'s
    /// `None` is (`x == null` on a `T` bound to a nullable type, ws525).
    fn is_dart_null(_value: &Self) -> bool {
        false
    }
    /// The `null` of this type, when it has one: growing a `List<T?>` by
    /// `length =` fills with it; a `List<T>` has none to fill with.
    fn dart_null() -> Option<Self> {
        None
    }
}

impl<X> DartNullable for Option<X> {
    type Or = Option<X>;
    fn is_dart_null(value: &Self) -> bool {
        value.is_none()
    }
    fn option(or: Option<X>) -> Option<Option<X>> {
        or.map(Some)
    }
    fn from_option(option: Option<Option<X>>) -> Option<X> {
        option.flatten()
    }
    fn dart_null() -> Option<Self> {
        Some(None)
    }
}

/// `DartNullable` for a type that is not an `Option`: `T?` is `Option<T>`.
#[macro_export]
macro_rules! dart_nullable {
    ($($t:tt)*) => {
        impl DartNullable for $($t)* {
            type Or = Option<Self>;
            fn option(or: Option<Self>) -> Option<Self> {
                or
            }
            fn from_option(option: Option<Self>) -> Option<Self> {
                option
            }
        }
        impl FromDynamic for $($t)* {
            fn from_dynamic(value: &std::rc::Rc<dyn Object>) -> Option<Self> {
                let object: &dyn Object = value.as_ref();
                object.as_any().downcast_ref::<Self>().cloned()
            }
            fn from_same(value: &Self) -> Option<Self> {
                Some(value.clone())
            }
        }
    };
}

