pub trait DartAny: Object + 'static {
    /// `runtimeType` reachable through a `&__Self: Trait + ?Sized` -- a super
    /// function's `this_` -- where `Object::runtime_type` would resolve on
    /// the *reference* and demand it be `'static` (E0521).
    fn dart_runtime_type(&self) -> Type;

    /// The object as one of the traits it implements, boxed as the
    /// `Rc<dyn Trait>` the caller asked for by `TypeId` (see `dart_cast_to`).
    /// Every translated struct answers for its own type and for every trait
    /// it has an `impl` for; the closed world is what makes that a list.
    /// Dart's `toString()`: the class's own override where it has one
    /// (the backend writes each struct's), else `Instance of 'X'` as
    /// `Object.toString` says. `dart_object_str` reaches it through a
    /// `dyn Object` by the registry.
    fn dart_to_string(&self) -> String {
        format!("Instance of '{}'", self.dart_runtime_type().name)
    }

    /// The value itself as `Any`, for `dart_cast_any`'s fallback: a
    /// handle answers with what it holds, an absent value with itself.
    fn dart_any_ref(&self) -> &dyn std::any::Any {
        self.as_any()
    }

    /// Dart's `==` against a value whose class only the object knows
    /// (`dyn Object` on either side): a class's own `==` (the backend
    /// writes each struct's through its `DartEq`), the core values by
    /// value, anything else by identity. A `Type` key looked up in
    /// `_inheritedElements` compared by address and never matched (run556).
    fn dart_eq_any(&self, other: &dyn std::any::Any) -> bool {
        std::ptr::addr_eq(
            self.dart_any_ref() as *const dyn std::any::Any as *const u8,
            other as *const dyn std::any::Any as *const u8,
        )
    }

    /// Dart's `hashCode` through the object: what `DartEq::dart_hash_code`
    /// answers for the concrete type (the backend writes each struct's),
    /// so a key hashed as its `K` and re-hashed as the `Object` a trie
    /// holds agree (`_resolveCollision` recursed forever on two hashes of
    /// one key, ws557). `0` -- one bucket -- is consistent with anything.
    fn dart_hash_any(&self) -> i64 {
        0
    }

    fn dart_cast(&self, _target: std::any::TypeId) -> Option<Box<dyn std::any::Any>> {
        None
    }
}

/// No impl for `Rc<T>`: a method call on a handle auto-derefs to the
/// object, and a blanket impl beside `Object`'s made `as_any` ambiguous
/// (5136 E0034s the first time).
/// `x.dart_cast_to::<dyn Widget>()`: Dart's `x as Widget` and `x is Widget`
/// where `Widget` is a trait, which `Any` cannot answer (a `dyn Any` knows
/// one concrete type). A method on everything, so the receiver may be a
/// handle, a reference or a value alike.
pub trait DartCastExt {
    fn dart_cast_to<T: ?Sized + 'static>(&self) -> Option<std::rc::Rc<T>>;
    /// `x is T` and `x as T` where `T` is a *type parameter*: what the
    /// caller passed for it is a whole type -- `Rc<ScaffoldState>`, `Rc<dyn
    /// State>`, an `i64` -- so the object is asked for that type by id
    /// (its `dart_cast` answers for its handles as well as for the traits),
    /// and a value type is asked of `Any`. Without this, `findAncestorState
    /// OfType` and `Provider.of` were refused ("`is` against `T`").
    fn dart_cast_any<T: Clone + 'static>(&self) -> Option<T>;
}

impl<S: DartAny + ?Sized> DartCastExt for S {
    fn dart_cast_to<T: ?Sized + 'static>(&self) -> Option<std::rc::Rc<T>> {
        self.dart_cast(std::any::TypeId::of::<T>())
            .and_then(|b| b.downcast::<std::rc::Rc<T>>().ok())
            .map(|b| *b)
    }
    /// The object as a `T`: what `dart_cast` answers for `T`'s id -- the
    /// value, or the handle `Rc<T>` a struct answers with for its own type
    /// (a value struct behind a trait handle, `found as T` in the
    /// gentrait fixture) -- else the object's `Any`.
    fn dart_cast_any<T: Clone + 'static>(&self) -> Option<T> {
        if let Some(b) = self.dart_cast(std::any::TypeId::of::<T>()) {
            match b.downcast::<T>() {
                Ok(v) => return Some(*v),
                Err(b) => {
                    if let Ok(rc) = b.downcast::<std::rc::Rc<T>>() {
                        return Some((**rc).clone());
                    }
                }
            }
        }
        self.dart_any_ref().downcast_ref::<T>().cloned()
    }
}

// A handle, an absent-or-not value and a `dyn Object` are `DartAny` below
// (the Object protocol), so the one blanket above casts through them:
// `x is Foo` where `x` is a `Foo?` asks the value inside, and `null is
// Foo` is false.

/// The cast table for objects reached through `dyn Object`, whose blanket
/// impl cannot know their type: `TypeId` of the struct to the function that
/// asks it `dart_cast`. Filled as objects are made -- `dart_rc`,
/// `dart_object`, and every constructor that is not `const` -- which in a
/// closed world is every object an `is Trait` can ever meet.
type DartCastFn = fn(&dyn std::any::Any, std::any::TypeId) -> Option<Box<dyn std::any::Any>>;

thread_local! {
    static DART_CASTS: std::cell::RefCell<std::collections::HashMap<std::any::TypeId, DartCastFn>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
}

/// `toString` for objects reached through `dyn Object`, by the same key.
type DartStrFn = fn(&dyn std::any::Any) -> Option<String>;

thread_local! {
    static DART_STRINGS: std::cell::RefCell<std::collections::HashMap<std::any::TypeId, DartStrFn>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
}

/// `==` for objects reached through `dyn Object`, by the same key.
type DartEqFn = fn(&dyn std::any::Any, &dyn std::any::Any) -> Option<bool>;

thread_local! {
    static DART_EQS: std::cell::RefCell<std::collections::HashMap<std::any::TypeId, DartEqFn>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
}

/// `hashCode` for objects reached through `dyn Object`, by the same key.
type DartHashFn = fn(&dyn std::any::Any) -> Option<i64>;

thread_local! {
    static DART_HASHES: std::cell::RefCell<std::collections::HashMap<std::any::TypeId, DartHashFn>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
}

pub fn dart_register<T: DartAny>() {
    DART_CASTS.with(|c| {
        c.borrow_mut()
            .entry(std::any::TypeId::of::<T>())
            .or_insert(|any, t| any.downcast_ref::<T>().and_then(|v| v.dart_cast(t)));
    });
    DART_STRINGS.with(|c| {
        c.borrow_mut()
            .entry(std::any::TypeId::of::<T>())
            .or_insert(|any| any.downcast_ref::<T>().map(|v| v.dart_to_string()));
    });
    DART_EQS.with(|c| {
        c.borrow_mut()
            .entry(std::any::TypeId::of::<T>())
            .or_insert(|a, b| a.downcast_ref::<T>().map(|v| v.dart_eq_any(b)));
    });
    DART_HASHES.with(|c| {
        c.borrow_mut()
            .entry(std::any::TypeId::of::<T>())
            .or_insert(|a| a.downcast_ref::<T>().map(|v| v.dart_hash_any()));
    });
}

/// `hashCode` of an object reached through `dyn Object`: its own, by the
/// registry; identity of the box for what was never registered.
pub fn dart_object_hash(value: &dyn Object) -> i64 {
    let any = value.as_any();
    let id = std::any::Any::type_id(any);
    let f = DART_HASHES.with(|c| c.borrow().get(&id).copied());
    match f.and_then(|f| f(any)) {
        Some(hash) => hash,
        None => {
            if let Some(s) = any.downcast_ref::<String>() {
                return dart_std_hash(s);
            }
            if let Some(i) = any.downcast_ref::<i64>() {
                return dart_std_hash(i);
            }
            if let Some(d) = any.downcast_ref::<f64>() {
                return dart_std_hash(&d.to_bits());
            }
            if let Some(b) = any.downcast_ref::<bool>() {
                return dart_std_hash(b);
            }
            if let Some(t) = any.downcast_ref::<Type>() {
                return dart_std_hash(t);
            }
            (any as *const dyn std::any::Any as *const u8 as usize as i64) & 0x3fff_ffff
        }
    }
}

/// Dart's `toString()` of a value whose type only the object knows: a
/// `dynamic`, an `Object?`, a type parameter. The core values print as
/// Dart prints them, a translated object by its own `toString` (the
/// registry, filled as objects are made), anything else as `Instance of`.
pub fn dart_object_str<T: DartAny>(value: T) -> String {
    value.dart_to_string()
}

/// The same as a method, so that a reference to a value -- the `&Rc<dyn
/// Object>` a null-aware `as_ref().map(|it| ..)` binds -- reaches it by
/// auto-deref (`&Rc<..>: DartAny` is not a thing, ws545).
pub trait DartObjectStr {
    fn dart_object_str(&self) -> String;
}

impl<T: ?Sized + DartAny> DartObjectStr for T {
    fn dart_object_str(&self) -> String {
        self.dart_to_string()
    }
}

pub fn dart_object_str_ref(value: &dyn Object) -> String {
    let any = value.as_any();
    if let Some(s) = any.downcast_ref::<String>() {
        return s.clone();
    }
    if let Some(s) = any.downcast_ref::<&'static str>() {
        return s.to_string();
    }
    if let Some(i) = any.downcast_ref::<i64>() {
        return i.to_string();
    }
    if let Some(d) = any.downcast_ref::<f64>() {
        return dart_double_str(*d);
    }
    if let Some(b) = any.downcast_ref::<bool>() {
        return b.to_string();
    }
    if any.downcast_ref::<Null>().is_some() || any.downcast_ref::<()>().is_some() {
        return "null".to_string();
    }
    if let Some(t) = any.downcast_ref::<Type>() {
        return t.name.to_string();
    }
    if let Some(s) = any.downcast_ref::<Option<String>>() {
        return s.clone().unwrap_or_else(|| "null".to_string());
    }
    if let Some(i) = any.downcast_ref::<Option<i64>>() {
        return i
            .map(|i| i.to_string())
            .unwrap_or_else(|| "null".to_string());
    }
    if let Some(d) = any.downcast_ref::<Option<f64>>() {
        return d.map(dart_double_str).unwrap_or_else(|| "null".to_string());
    }
    if let Some(b) = any.downcast_ref::<Option<bool>>() {
        return b
            .map(|b| b.to_string())
            .unwrap_or_else(|| "null".to_string());
    }
    if let Some(o) = any.downcast_ref::<Option<std::rc::Rc<dyn Object>>>() {
        return match o {
            Some(o) => dart_object_str_ref(&**o),
            None => "null".to_string(),
        };
    }
    let id = std::any::Any::type_id(any);
    let f = DART_STRINGS.with(|c| c.borrow().get(&id).copied());
    if let Some(text) = f.and_then(|f| f(any)) {
        return text;
    }
    format!("Instance of '{}'", value.runtime_type().name)
}

/// `Rc::new` for a value shared as an object: registered on the way.
pub fn dart_object<T: DartAny>(value: T) -> std::rc::Rc<T> {
    dart_register::<T>();
    std::rc::Rc::new(value)
}

/// A value of a type only known as a parameter (`K`, `V`) on its way into
/// an `Object` slot: the object it *is* -- a handle (`Rc<dyn
/// InheritedElement>`) becomes the object it holds, not a box around the
/// handle, so what comes back out casts to the handle again (`_inheritedElements[T]`
/// stored `Rc<Rc<dyn InheritedElement>>` and `from_dynamic` never found
/// the element, run558) -- and a core value behind a fresh handle.
/// An absent-or-not value as a `dynamic`: the object it is, or Dart's
/// null (a dynamic slot's `map[k]`, whose consumer casts the result).
pub fn dart_option_object<T: DartAny>(value: Option<T>) -> std::rc::Rc<dyn Object> {
    match value {
        Some(v) => dart_boxed(v),
        None => dart_null_object(),
    }
}

pub fn dart_boxed<T: DartAny>(value: T) -> std::rc::Rc<dyn Object> {
    dart_register::<T>();
    match value.dart_cast_to::<dyn Object>() {
        Some(object) => object,
        None => std::rc::Rc::new(value),
    }
}

/// The Object protocol of a `dyn Object`: what the object behind it
/// answers, found by the registry (`DART_CASTS`, `DART_STRINGS`).
impl DartAny for dyn Object {
    fn dart_runtime_type(&self) -> Type {
        self.runtime_type()
    }
    fn dart_to_string(&self) -> String {
        dart_object_str_ref(self)
    }
    fn dart_eq_any(&self, other: &dyn std::any::Any) -> bool {
        let any = self.as_any();
        let id = std::any::Any::type_id(any);
        let f = DART_EQS.with(|c| c.borrow().get(&id).copied());
        match f.and_then(|f| f(any, other)) {
            Some(answer) => answer,
            None => std::ptr::addr_eq(
                any as *const dyn std::any::Any as *const u8,
                other as *const dyn std::any::Any as *const u8,
            ),
        }
    }
    fn dart_hash_any(&self) -> i64 {
        dart_object_hash(self)
    }
    fn dart_any_ref(&self) -> &dyn std::any::Any {
        self.as_any()
    }
    fn dart_cast(&self, target: std::any::TypeId) -> Option<Box<dyn std::any::Any>> {
        let any = self.as_any();
        let id = std::any::Any::type_id(any);
        let f = DART_CASTS.with(|c| c.borrow().get(&id).copied());
        f.and_then(|f| f(any, target))
    }
}

/// A handle is the object it holds, for the whole protocol.
impl<T: ?Sized + DartAny> DartAny for std::rc::Rc<T> {
    fn dart_runtime_type(&self) -> Type {
        (**self).dart_runtime_type()
    }
    fn dart_to_string(&self) -> String {
        (**self).dart_to_string()
    }
    fn dart_eq_any(&self, other: &dyn std::any::Any) -> bool {
        (**self).dart_eq_any(other)
    }
    fn dart_hash_any(&self) -> i64 {
        (**self).dart_hash_any()
    }
    fn dart_any_ref(&self) -> &dyn std::any::Any {
        (**self).dart_any_ref()
    }
    fn dart_cast(&self, target: std::any::TypeId) -> Option<Box<dyn std::any::Any>> {
        (**self).dart_cast(target)
    }
}

