/// The rest of what a type parameter can hold: named, nothing more.
macro_rules! dart_any_named {
    ($($t:ty => $name:literal),* $(,)?) => {
        $(
            impl DartAny for $t {
                fn dart_runtime_type(&self) -> Type {
                    Type::of($name)
                }
                fn dart_eq_any(&self, other: &dyn std::any::Any) -> bool {
                    match other.downcast_ref::<Self>() {
                        Some(o) => self.dart_eq(o),
                        None => false,
                    }
                }
                fn dart_hash_any(&self) -> i64 {
                    self.dart_hash_code()
                }
            }
        )*
    };
}

/// As `dart_any_named!`, for a type whose `Display` is its Dart
/// `toString()`: `Uri`, `Duration`, the error classes. Through the
/// named macro they printed `Instance of 'Uri'` (the uripath fixture).
macro_rules! dart_any_display {
    ($($t:ty => $name:literal),* $(,)?) => {
        $(
            impl DartAny for $t {
                fn dart_runtime_type(&self) -> Type {
                    Type::of($name)
                }
                fn dart_to_string(&self) -> String {
                    format!("{}", self)
                }
                fn dart_eq_any(&self, other: &dyn std::any::Any) -> bool {
                    match other.downcast_ref::<Self>() {
                        Some(o) => self.dart_eq(o),
                        None => false,
                    }
                }
                fn dart_hash_any(&self) -> i64 {
                    self.dart_hash_code()
                }
            }
        )*
    };
}

macro_rules! dart_any_generic {
    ($($t:ident<$($p:ident),*> => $name:literal),* $(,)?) => {
        $(
            impl<$($p: 'static),*> DartAny for $t<$($p),*> {
                fn dart_runtime_type(&self) -> Type {
                    Type::of($name)
                }
            }
        )*
    };
}

impl DartAny for i64 {
    fn dart_eq_any(&self, other: &dyn std::any::Any) -> bool {
        match other.downcast_ref::<Self>() {
            Some(o) => self == o,
            None => false,
        }
    }
    fn dart_hash_any(&self) -> i64 {
        self.dart_hash_code()
    }
    fn dart_runtime_type(&self) -> Type {
        Type::of("int")
    }
    fn dart_to_string(&self) -> String {
        self.to_string()
    }
    /// As an `Object`: a fresh handle around a copy, so that an
    /// `Option` of one boxes to the value and not to the `Option`
    /// (`Map<String, Object?>.cast<String, int>()`, the listcast fixture).
    fn dart_cast(&self, __t: std::any::TypeId) -> Option<Box<dyn std::any::Any>> {
        if __t == std::any::TypeId::of::<dyn Object>()
            || __t == std::any::TypeId::of::<std::rc::Rc<dyn Object>>()
        {
            Some(Box::new(
                std::rc::Rc::new(self.clone()) as std::rc::Rc<dyn Object>
            ))
        } else {
            None
        }
    }
}

impl DartAny for f64 {
    fn dart_eq_any(&self, other: &dyn std::any::Any) -> bool {
        match other.downcast_ref::<Self>() {
            Some(o) => self == o,
            None => false,
        }
    }
    fn dart_hash_any(&self) -> i64 {
        self.dart_hash_code()
    }
    fn dart_runtime_type(&self) -> Type {
        Type::of("double")
    }
    fn dart_to_string(&self) -> String {
        dart_double_str(*self)
    }
    /// As an `Object`: a fresh handle around a copy, so that an
    /// `Option` of one boxes to the value and not to the `Option`
    /// (`Map<String, Object?>.cast<String, int>()`, the listcast fixture).
    fn dart_cast(&self, __t: std::any::TypeId) -> Option<Box<dyn std::any::Any>> {
        if __t == std::any::TypeId::of::<dyn Object>()
            || __t == std::any::TypeId::of::<std::rc::Rc<dyn Object>>()
        {
            Some(Box::new(
                std::rc::Rc::new(self.clone()) as std::rc::Rc<dyn Object>
            ))
        } else {
            None
        }
    }
}

