/// Dart's `DateTime`: an instant, counted in microseconds from the epoch.
///
/// `now()` is the one thing here that needs the outside world, and it uses the
/// system clock. Dart's is the same clock. `isUtc` is carried because upstream
/// compares on it, and the arithmetic ignores it exactly as Dart's does --
/// a `Duration` is a span, not a calendar step.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Default, Hash)]
pub struct DateTime {
    pub microseconds_since_epoch: i64,
    pub is_utc: bool,
}

impl DateTime {
    /// `isUtc`, the field, as the method every other getter here is (a
    /// Dart field of a `dart:` class is read as a call, see the front end).
    pub fn is_utc(&self) -> bool {
        self.is_utc
    }

    /// Days since the epoch and the microseconds into that day, UTC.
    fn civil(&self) -> (i64, i64) {
        let day = 86_400_000_000i64;
        let days = self.microseconds_since_epoch.div_euclid(day);
        let rest = self.microseconds_since_epoch.rem_euclid(day);
        (days, rest)
    }

    /// Howard Hinnant's civil-from-days: (year, month, day).
    fn ymd(&self) -> (i64, i64, i64) {
        let (z, _) = self.civil();
        let z = z + 719_468;
        let era = z.div_euclid(146_097);
        let doe = z - era * 146_097;
        let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
        let y = yoe + era * 400;
        let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
        let mp = (5 * doy + 2) / 153;
        let d = doy - (153 * mp + 2) / 5 + 1;
        let m = if mp < 10 { mp + 3 } else { mp - 9 };
        (if m <= 2 { y + 1 } else { y }, m, d)
    }

    /// `DateTime(year, [month, day, hour, minute, second, millisecond,
    /// microsecond])`: local time is UTC here (no zone database yet).
    pub fn new(
        year: i64,
        month: i64,
        day: i64,
        hour: i64,
        minute: i64,
        second: i64,
        millisecond: i64,
        microsecond: i64,
    ) -> Self {
        // Hinnant's days-from-civil.
        let y = if month <= 2 { year - 1 } else { year };
        let era = y.div_euclid(400);
        let yoe = y - era * 400;
        let mp = if month > 2 { month - 3 } else { month + 9 };
        let doy = (153 * mp + 2) / 5 + day - 1;
        let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
        let days = era * 146_097 + doe - 719_468;
        let micros = ((((days * 24 + hour) * 60 + minute) * 60 + second) * 1000 + millisecond)
            * 1000
            + microsecond;
        DateTime {
            microseconds_since_epoch: micros,
            is_utc: false,
        }
    }

    /// `DateTime.utc(..)`: the same arithmetic, marked UTC.
    pub fn utc(
        year: i64,
        month: i64,
        day: i64,
        hour: i64,
        minute: i64,
        second: i64,
        millisecond: i64,
        microsecond: i64,
    ) -> Self {
        let mut t = DateTime::new(
            year,
            month,
            day,
            hour,
            minute,
            second,
            millisecond,
            microsecond,
        );
        t.is_utc = true;
        t
    }

    pub fn year(&self) -> i64 {
        self.ymd().0
    }
    pub fn month(&self) -> i64 {
        self.ymd().1
    }
    pub fn day(&self) -> i64 {
        self.ymd().2
    }
    pub fn hour(&self) -> i64 {
        self.civil().1 / 3_600_000_000
    }
    pub fn minute(&self) -> i64 {
        self.civil().1 / 60_000_000 % 60
    }
    pub fn second(&self) -> i64 {
        self.civil().1 / 1_000_000 % 60
    }
    pub fn millisecond(&self) -> i64 {
        self.civil().1 / 1_000 % 1_000
    }
    pub fn microsecond(&self) -> i64 {
        self.civil().1 % 1_000
    }
    /// `compareTo(other)`: by the instant.
    pub fn compare_to(&self, other: DateTime) -> i64 {
        self.microseconds_since_epoch
            .cmp(&other.microseconds_since_epoch) as i64
    }

    /// `timeZoneOffset`: local time is UTC here, so zero.
    pub fn time_zone_offset(&self) -> Duration {
        Duration { microseconds: 0 }
    }

    /// `weekday`: Monday is 1, Sunday 7, as `DateTime.monday..sunday`.
    pub fn weekday(&self) -> i64 {
        let (days, _) = self.civil();
        (days + 3).rem_euclid(7) + 1
    }

    pub fn now() -> Self {
        let since = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_micros() as i64)
            .unwrap_or(0);
        DateTime {
            microseconds_since_epoch: since,
            is_utc: false,
        }
    }

    pub fn from_microseconds_since_epoch(microseconds: i64) -> Self {
        DateTime {
            microseconds_since_epoch: microseconds,
            is_utc: false,
        }
    }

    pub fn from_milliseconds_since_epoch(milliseconds: i64) -> Self {
        DateTime {
            microseconds_since_epoch: milliseconds * 1000,
            is_utc: false,
        }
    }

    pub fn milliseconds_since_epoch(&self) -> i64 {
        self.microseconds_since_epoch / 1000
    }

    pub fn difference(&self, other: DateTime) -> Duration {
        Duration {
            microseconds: self.microseconds_since_epoch - other.microseconds_since_epoch,
        }
    }

    pub fn add(&self, span: Duration) -> DateTime {
        DateTime {
            microseconds_since_epoch: self.microseconds_since_epoch + span.microseconds,
            is_utc: self.is_utc,
        }
    }

    pub fn subtract(&self, span: Duration) -> DateTime {
        DateTime {
            microseconds_since_epoch: self.microseconds_since_epoch - span.microseconds,
            is_utc: self.is_utc,
        }
    }

    pub fn is_before(&self, other: DateTime) -> bool {
        self.microseconds_since_epoch < other.microseconds_since_epoch
    }

    pub fn is_after(&self, other: DateTime) -> bool {
        self.microseconds_since_epoch > other.microseconds_since_epoch
    }
}

/// A value that belongs to one isolate, standing in a Rust `static`.
///
/// Dart's `static` is one **per isolate**, and an isolate is a thread. Rust's
/// `static` is one per *process*, so what it holds must be `Sync` -- and a
/// `Box<dyn Fn(..)>`, which is what half of Flutter's statics hold, is not and
/// never will be.
///
/// `thread_local!` says the same thing safely, and would be the right answer if
/// its value could be reached without a closure; it cannot, and
/// `Box<dyn Fn(..)>` is not `Clone`, so every read would have to be
/// restructured. This says it instead, and the `unsafe` is carrying exactly
/// one claim:
///
/// **the translated program runs on one thread.**
///
/// That is true of a Dart isolate by construction, and it is the thing to
/// check before running anything translated here: the moment this program
/// spawns a thread that touches a static, this is unsound. Nothing translated
/// so far can spawn one -- `Isolate.spawn` and `compute` are not translated --
/// and if that changes, this is where it breaks.
pub struct Isolate<T>(pub T);

unsafe impl<T> Sync for Isolate<T> {}
unsafe impl<T> Send for Isolate<T> {}

impl<T> std::ops::Deref for Isolate<T> {
    type Target = T;
    fn deref(&self) -> &T {
        &self.0
    }
}

impl<T> std::ops::DerefMut for Isolate<T> {
    fn deref_mut(&mut self) -> &mut T {
        &mut self.0
    }
}

/// `dart:core`'s "no argument was passed" marker.
///
/// Upstream's `copyWith` methods take a sentinel as the default so that
/// passing `null` and passing nothing can be told apart. What is done with it
/// is compare identities, so an empty struct says everything it says -- and it
/// is `Copy`, which is what makes the comparison free.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct SentinelValue;

/// An object's own handle, from inside.
///
/// A trait's default body has `&self` and no `Rc`; Dart's `this` there is a
/// value that can be stored and returned (`return this` in `TextScaler.clamp`).
/// Every counted struct keeps a weak back-reference to its own `Rc`, set the
/// moment the `Rc` is made (`dart_rc`), and a trait reaches it through
/// `dart_self_<trait>()`. A clone starts empty: a new handle around a copy is
/// a new object.
pub struct DartSelf<T: ?Sized>(std::cell::OnceCell<std::rc::Weak<T>>);

impl<T: ?Sized> DartSelf<T> {
    pub const fn new() -> Self {
        DartSelf(std::cell::OnceCell::new())
    }

    pub fn set(&self, rc: &std::rc::Rc<T>) {
        let _ = self.0.set(std::rc::Rc::downgrade(rc));
    }

    pub fn get(&self) -> std::rc::Rc<T> {
        self.0
            .get()
            .and_then(|w| w.upgrade())
            .expect("dart2rust: `this` taken before the object had a handle")
    }
}

impl<T: ?Sized> Clone for DartSelf<T> {
    fn clone(&self) -> Self {
        DartSelf::new()
    }
}

impl<T: ?Sized> Default for DartSelf<T> {
    fn default() -> Self {
        DartSelf::new()
    }
}

impl<T: ?Sized> std::fmt::Debug for DartSelf<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("DartSelf")
    }
}

impl<T: ?Sized> PartialEq for DartSelf<T> {
    fn eq(&self, _: &Self) -> bool {
        true
    }
}

/// The struct's back-reference, for `dart_rc`.
pub trait DartSelfRef {
    fn dart_self_ref(&self) -> &DartSelf<Self>;
}

/// `std::rc::Rc::new` for a counted object: the handle is made and remembered.
pub fn dart_rc<T: DartSelfRef + DartAny>(value: T) -> std::rc::Rc<T> {
    dart_register::<T>();
    let rc = std::rc::Rc::new(value);
    rc.dart_self_ref().set(&rc);
    rc
}

/// Dart's `MapEntry`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct MapEntry<K, V> {
    pub key: K,
    pub value: V,
}

impl<K, V> MapEntry<K, V> {
    pub fn new(key: K, value: V) -> Self {
        MapEntry { key, value }
    }
}

/// Dart's `Map`: a lookup that **keeps insertion order**.
///
/// A Dart map literal is a `LinkedHashMap`, and `keys`, `values`, `entries`
/// and `forEach` walk it in the order things were put in. A
/// `std::collections::HashMap` does not, so those five members were refused --
/// 97 of them -- rather than reorder anything quietly.
///
/// A `Vec` of pairs keeps the order and costs a linear lookup. That is the
/// same trade `Set<T>` next door has always made, and taking it here too
/// makes one decision instead of two: whatever these containers cost, they
/// cost it the same way.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Map<K, V> {
    entries: Vec<(K, V)>,
}

/// What needs no key equality: a `Map<Rc<dyn Fn()>, i64>` -- Dart's
/// `ObserverList` -- can be made and sized, and only the lookups on it
/// want the keys comparable (43 holders' constructors at ws298).
impl<K: DartEq, V> Map<K, V> {
    /// Entries converted one by one (`cast_to`, `dart_cast_map`): a later
    /// duplicate of a key replaces the earlier, as `insert` does, without
    /// asking `Clone` of either type.
    fn from_converted(pairs: Vec<(K, V)>) -> Self {
        let mut entries: Vec<(K, V)> = Vec::new();
        for (k, v) in pairs {
            if let Some(slot) = entries.iter_mut().find(|(k0, _)| k0.dart_eq(&k)) {
                slot.1 = v;
            } else {
                entries.push((k, v));
            }
        }
        Map { entries }
    }
}

impl<T: DartEq> Set<T> {
    /// Elements converted one by one (`cast_to`, `dart_cast_set`): a later
    /// duplicate is dropped, as `add` does.
    fn from_converted(elements: Vec<T>) -> Self {
        let mut items: Vec<T> = Vec::new();
        for e in elements {
            if !items.iter().any(|e0| e0.dart_eq(&e)) {
                items.push(e);
            }
        }
        Set { items }
    }
}

impl<K, V> Map<K, V> {
    /// A written map literal: its entries as an array *of the spelled
    /// types*, so that every entry's value is coerced to them where
    /// `From<impl IntoIterator>` typed the array by its first entry
    /// alone (`{'a': null, 'b': 2}` into `Map<Object?, Object?>`, ws495).
    pub fn from_pairs<const N: usize>(entries: [(K, V); N]) -> Self
    where
        K: DartEq + Clone,
        V: Clone,
    {
        let mut out = Map::new();
        for (k, v) in entries {
            out.insert(k, v);
        }
        out
    }
}

impl<K: Clone, V: Clone> Map<K, V> {
    /// `Map.of(other)`: a copy with the same entries, in the same order.
    /// `Map.unmodifiable(other)`: a copy; the immutability is not modeled
    /// (`ThemeData._themeExtensionIterableToMap`, ws523).
    pub fn unmodifiable(other: Map<K, V>) -> Map<K, V>
    where
        K: DartEq + Clone,
        V: Clone,
    {
        Map::of(other)
    }

    pub fn of(other: Map<K, V>) -> Map<K, V> {
        other
    }
    pub fn new() -> Self {
        Map {
            entries: Vec::new(),
        }
    }

    pub fn clear(&mut self) {
        self.entries.clear();
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// In insertion order, which is the whole reason for this type.
    pub fn keys(&self) -> Vec<K> {
        self.entries.iter().map(|(k, _)| k.clone()).collect()
    }

    pub fn values(&self) -> Vec<V> {
        self.entries.iter().map(|(_, v)| v.clone()).collect()
    }

    pub fn entries(&self) -> Vec<MapEntry<K, V>> {
        self.entries
            .iter()
            .map(|(k, v)| MapEntry {
                key: k.clone(),
                value: v.clone(),
            })
            .collect()
    }

    pub fn for_each(
        &self,
        mut f: impl FnMut(K, V) -> Result<(), DartError>,
    ) -> Result<(), DartError> {
        for (key, value) in &self.entries {
            f(key.clone(), value.clone())?;
        }
        Ok(())
    }
}

impl<K: DartEq + Clone, V: Clone> Map<K, V> {
    /// `Map.from(other)` / a literal: an array or a `Vec` of entries.
    pub fn from<I: IntoIterator<Item = (K, V)>>(items: I) -> Self {
        let mut map = Map::new();
        for (key, value) in items {
            map.insert(key, value);
        }
        map
    }

    fn at(&self, key: &K) -> Option<usize> {
        self.entries.iter().position(|(k, _)| k.dart_eq(key))
    }

    pub fn get(&self, key: &K) -> Option<&V> {
        self.at(key).map(|i| &self.entries[i].1)
    }

    /// Dart gives back what was there; so does Rust's `HashMap::insert`.
    /// Replacing a value keeps the key where it was, which is what insertion
    /// order means once a key is written twice.
    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
        match self.at(&key) {
            Some(i) => Some(std::mem::replace(&mut self.entries[i].1, value)),
            None => {
                self.entries.push((key, value));
                None
            }
        }
    }

    pub fn contains_key(&self, key: &K) -> bool {
        self.at(key).is_some()
    }

    pub fn remove(&mut self, key: &K) -> Option<V> {
        self.at(key).map(|i| self.entries.remove(i).1)
    }

    /// Dart's `putIfAbsent`: the value that is there afterwards, either way.
    pub fn put_if_absent(
        &mut self,
        key: K,
        make: impl FnOnce() -> Result<V, DartError>,
    ) -> Result<V, DartError> {
        if let Some(i) = self.at(&key) {
            return Ok(self.entries[i].1.clone());
        }
        let value = make()?;
        self.entries.push((key, value.clone()));
        Ok(value)
    }

    pub fn extend(&mut self, other: Map<K, V>) {
        for (key, value) in other.entries {
            self.insert(key, value);
        }
    }
}

impl<K, V> IntoIterator for Map<K, V> {
    type Item = (K, V);
    type IntoIter = std::vec::IntoIter<(K, V)>;
    fn into_iter(self) -> Self::IntoIter {
        self.entries.into_iter()
    }
}

/// `dart:collection`'s public map and set classes.
///
/// Dart's `LinkedHashMap` keeps insertion order and `HashMap` does not. Both
/// are the ordered `Map` here: keeping an order nothing asked for is a
/// promise too strong, never one too weak. `SplayTreeMap` is sorted, and
/// `BTreeMap` would be the same promise -- it is not translated.
pub type LinkedHashMap<K, V> = Map<K, V>;
pub type HashMap<K, V> = Map<K, V>;
pub type LinkedHashSet<T> = Set<T>;
pub type HashSet<T> = Set<T>;

/// Dart's `Queue` and its two concrete kinds, backed by a `VecDeque`.
///
/// `LinkedList` in Dart is an intrusive list -- its elements carry their own
/// links -- and a `VecDeque` is not that. Nothing translated so far uses the
/// intrusive part, and this is where to look if something does.
pub type Queue<T> = std::collections::VecDeque<T>;

/// Equality by identity for what is shared: what Dart's `Object.==` does,
/// and what a derived `PartialEq` over an `Rc<dyn X>` field cannot say
/// (see `_emitStruct`).
/// Dart's `==`, as collections ask it of their keys and elements: a
/// value by its `PartialEq`, a shared object (`Rc<..>`) by what it holds,
/// a trait object or a function by identity. `Map`, `Set` and the `List`
/// operations that compare (`contains`, `remove`, `indexOf`) all go
/// through this, so a `Set<VoidCallback>` or a `Map<PointerRoute, ..>` is
/// as ordinary as a `Set<int>` (run437: `PointerRouter`, and every
/// listener list before it).
///
/// ..and Dart's `hashCode` beside it, the other half of the `Object`
/// protocol: what a value typed by a type parameter (`K` in
/// `PersistentHashMap`) can ask of itself. The default, `0`, is consistent
/// with any equality -- a hash structure degrades to one bucket, and is
/// still right; the scalars, strings, `Type` and the shared objects hash
/// for real. A translated class that overrides `hashCode` keeps that as
/// its own method; this protocol does not reach it (a key of that class
/// in a hashed structure lands in the one bucket).
pub trait DartEq {
    fn dart_eq(&self, other: &Self) -> bool;
    fn dart_hash_code(&self) -> i64 {
        0
    }
}

/// A hash by `std::hash::Hash`, folded into Dart's non-negative range.
pub fn dart_std_hash<T: std::hash::Hash + ?Sized>(value: &T) -> i64 {
    use std::hash::Hasher;
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    value.hash(&mut hasher);
    (hasher.finish() as i64) & 0x3fff_ffff
}

/// A shared object compares as what it holds: a value struct by value, a
/// trait object or a function by identity (their own impls).
impl<T: ?Sized + DartEq> DartEq for std::rc::Rc<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        (**self).dart_eq(&**other)
    }
    fn dart_hash_code(&self) -> i64 {
        (**self).dart_hash_code()
    }
}

impl<T: ?Sized> DartEq for std::rc::Weak<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        self.ptr_eq(other)
    }
}

impl DartEq for dyn Object {
    fn dart_eq(&self, other: &Self) -> bool {
        self == other
    }
    fn dart_hash_code(&self) -> i64 {
        dart_object_hash(self)
    }
}

impl<T: DartEq> DartEq for Option<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Some(a), Some(b)) => a.dart_eq(b),
            (None, None) => true,
            _ => false,
        }
    }
    fn dart_hash_code(&self) -> i64 {
        match self {
            Some(a) => a.dart_hash_code(),
            None => 0,
        }
    }
}

impl<T: DartEq> DartEq for Vec<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        self.len() == other.len() && self.iter().zip(other.iter()).all(|(a, b)| a.dart_eq(b))
    }
}

impl<T: DartEq> DartEq for std::collections::VecDeque<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        self.len() == other.len() && self.iter().zip(other.iter()).all(|(a, b)| a.dart_eq(b))
    }
}

