/// A value type with `PartialEq`: by it.
macro_rules! dart_eq {
    ($($t:ty),* $(,)?) => {
        $(
            impl DartEq for $t {
                fn dart_eq(&self, other: &Self) -> bool {
                    self == other
                }
            }
        )*
    };
}

/// `==` by `PartialEq` and `hashCode` by `Hash`, for the values Dart
/// hashes by content.
macro_rules! dart_eq_hashed {
    ($($t:ty),* $(,)?) => {
        $(
            impl DartEq for $t {
                fn dart_eq(&self, other: &Self) -> bool {
                    self == other
                }
                fn dart_hash_code(&self) -> i64 {
                    dart_std_hash(self)
                }
            }
        )*
    };
}

