/// `dart:io`'s files, on `std::fs`: what `get_storage`'s IO backend
/// asks of them (ws479). The sync members panic with Dart's
/// `FileSystemException` text, as the prelude's other primitives do; the
/// async ones hand the exception back in the future, where a `try` can
/// catch it. `readInto` cannot fill the caller's buffer: a list is a
/// value here, so it reads and reports the count only.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum FileMode {
    #[default]
    Read,
    Write,
    Append,
    WriteOnly,
    WriteOnlyAppend,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum FileLock {
    Shared,
    #[default]
    Exclusive,
    BlockingShared,
    BlockingExclusive,
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct FileSystemException {
    pub message: String,
    pub path: Option<String>,
    pub os_error: Option<OSError>,
}

impl FileSystemException {
    pub fn new(message: String, path: Option<String>, os_error: Option<OSError>) -> Self {
        FileSystemException {
            message,
            path,
            os_error,
        }
    }

    fn of(what: &str, path: &str, error: std::io::Error) -> Self {
        FileSystemException {
            message: what.to_string(),
            path: Some(path.to_string()),
            os_error: Some(OSError {
                message: error.to_string(),
                error_code: error.raw_os_error().unwrap_or(0) as i64,
            }),
        }
    }

    fn raise(self) -> ! {
        panic!("uncaught Dart exception: {}", self)
    }

    fn failed(self) -> DartError {
        std::rc::Rc::new(self) as DartError
    }
}

impl fmt::Display for FileSystemException {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "FileSystemException: {}", self.message)?;
        if let Some(path) = &self.path {
            write!(f, ", path = '{}'", path)?;
        }
        if let Some(os) = &self.os_error {
            write!(f, " (OS Error: {}, errno = {})", os.message, os.error_code)?;
        }
        Ok(())
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct FileSystemEntity {
    pub path: String,
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct File {
    pub path: String,
}

fn io_ready<T: 'static>(result: Result<T, FileSystemException>) -> DartFuture<T> {
    DartFuture::ready(result.map_err(|e| e.failed()))
}

/// A list a prelude call writes bytes into: a `Uint8List` (`Vec<u8>`) or a
/// `List<int>` (`Vec<i64>`), through the `&mut` the front end hands out.
pub trait DartByteSink {
    fn sink_len(&self) -> usize;
    fn put_byte(&mut self, at: usize, byte: u8);
}

impl DartByteSink for Vec<u8> {
    fn sink_len(&self) -> usize {
        self.len()
    }
    fn put_byte(&mut self, at: usize, byte: u8) {
        if at < self.len() {
            self[at] = byte;
        }
    }
}

impl DartByteSink for Vec<i64> {
    fn sink_len(&self) -> usize {
        self.len()
    }
    fn put_byte(&mut self, at: usize, byte: u8) {
        if at < self.len() {
            self[at] = byte as i64;
        }
    }
}

fn bytes_of(list: &[i64], start: i64, end: Option<i64>) -> Vec<u8> {
    let start = start.max(0) as usize;
    let end = end
        .map(|e| e.max(0) as usize)
        .unwrap_or(list.len())
        .min(list.len());
    list[start.min(end)..end].iter().map(|b| *b as u8).collect()
}

impl File {
    pub fn new(path: String) -> Self {
        File { path }
    }

    pub fn path(&self) -> String {
        self.path.clone()
    }

    pub fn parent(&self) -> Directory {
        Directory::new(
            std::path::Path::new(&self.path)
                .parent()
                .map(|p| p.to_string_lossy().into_owned())
                .unwrap_or_else(|| ".".to_string()),
        )
    }

    pub fn exists_sync(&self) -> bool {
        std::path::Path::new(&self.path).is_file()
    }

    pub fn exists(&self) -> DartFuture<bool> {
        DartFuture::ready(Ok(self.exists_sync()))
    }

    fn try_create(&self, recursive: bool, exclusive: bool) -> Result<(), FileSystemException> {
        if recursive {
            if let Some(parent) = std::path::Path::new(&self.path).parent() {
                std::fs::create_dir_all(parent)
                    .map_err(|e| FileSystemException::of("Cannot create file", &self.path, e))?;
            }
        }
        std::fs::OpenOptions::new()
            .write(true)
            .create(true)
            .create_new(exclusive)
            .open(&self.path)
            .map(|_| ())
            .map_err(|e| FileSystemException::of("Cannot create file", &self.path, e))
    }

    pub fn create_sync(&self, recursive: bool, exclusive: bool) {
        if let Err(e) = self.try_create(recursive, exclusive) {
            e.raise()
        }
    }

    pub fn create(&self, recursive: bool, exclusive: bool) -> DartFuture<File> {
        io_ready(self.try_create(recursive, exclusive).map(|_| self.clone()))
    }

    fn try_open(&self, mode: FileMode) -> Result<RandomAccessFile, FileSystemException> {
        let mut options = std::fs::OpenOptions::new();
        match mode {
            FileMode::Read => {
                options.read(true);
            }
            FileMode::Write => {
                options.read(true).write(true).create(true);
            }
            FileMode::Append => {
                options.read(true).append(true).create(true);
            }
            FileMode::WriteOnly => {
                options.write(true).create(true);
            }
            FileMode::WriteOnlyAppend => {
                options.append(true).create(true);
            }
        }
        let file = options
            .open(&self.path)
            .map_err(|e| FileSystemException::of("Cannot open file", &self.path, e))?;
        Ok(RandomAccessFile {
            path: self.path.clone(),
            file: std::rc::Rc::new(std::cell::RefCell::new(file)),
        })
    }

    pub fn open_sync(&self, mode: FileMode) -> RandomAccessFile {
        match self.try_open(mode) {
            Ok(file) => file,
            Err(e) => e.raise(),
        }
    }

    pub fn open(&self, mode: FileMode) -> DartFuture<RandomAccessFile> {
        io_ready(self.try_open(mode))
    }

    fn try_length(&self) -> Result<i64, FileSystemException> {
        std::fs::metadata(&self.path)
            .map(|m| m.len() as i64)
            .map_err(|e| FileSystemException::of("Cannot retrieve length of file", &self.path, e))
    }

    pub fn length_sync(&self) -> i64 {
        match self.try_length() {
            Ok(n) => n,
            Err(e) => e.raise(),
        }
    }

    pub fn length(&self) -> DartFuture<i64> {
        io_ready(self.try_length())
    }

    fn try_read(&self) -> Result<Vec<u8>, FileSystemException> {
        std::fs::read(&self.path)
            .map_err(|e| FileSystemException::of("Cannot open file", &self.path, e))
    }

    pub fn read_as_bytes_sync(&self) -> Vec<i64> {
        match self.try_read() {
            Ok(bytes) => bytes.into_iter().map(|b| b as i64).collect(),
            Err(e) => e.raise(),
        }
    }

    pub fn read_as_bytes(&self) -> DartFuture<Vec<i64>> {
        io_ready(
            self.try_read()
                .map(|bytes| bytes.into_iter().map(|b| b as i64).collect()),
        )
    }

    pub fn read_as_string_sync(&self, _encoding: Utf8Codec) -> String {
        match self.try_read() {
            Ok(bytes) => String::from_utf8_lossy(&bytes).into_owned(),
            Err(e) => e.raise(),
        }
    }

    pub fn read_as_string(&self, _encoding: Utf8Codec) -> DartFuture<String> {
        io_ready(
            self.try_read()
                .map(|bytes| String::from_utf8_lossy(&bytes).into_owned()),
        )
    }

    fn try_write(
        &self,
        bytes: &[u8],
        mode: FileMode,
        flush: bool,
    ) -> Result<(), FileSystemException> {
        use std::io::Write;
        let file = self.try_open(
            if matches!(mode, FileMode::Append | FileMode::WriteOnlyAppend) {
                FileMode::WriteOnlyAppend
            } else {
                FileMode::WriteOnly
            },
        )?;
        let mut handle = file.file.borrow_mut();
        if !matches!(mode, FileMode::Append | FileMode::WriteOnlyAppend) {
            handle
                .set_len(0)
                .map_err(|e| FileSystemException::of("Cannot truncate file", &self.path, e))?;
        }
        handle
            .write_all(bytes)
            .map_err(|e| FileSystemException::of("Cannot write file", &self.path, e))?;
        if flush {
            handle
                .flush()
                .map_err(|e| FileSystemException::of("Cannot flush file", &self.path, e))?;
        }
        Ok(())
    }

    pub fn write_as_string_sync(
        &self,
        contents: String,
        mode: FileMode,
        _encoding: Utf8Codec,
        flush: bool,
    ) {
        if let Err(e) = self.try_write(contents.as_bytes(), mode, flush) {
            e.raise()
        }
    }

    pub fn write_as_string(
        &self,
        contents: String,
        mode: FileMode,
        _encoding: Utf8Codec,
        flush: bool,
    ) -> DartFuture<File> {
        io_ready(
            self.try_write(contents.as_bytes(), mode, flush)
                .map(|_| self.clone()),
        )
    }

    pub fn write_as_bytes_sync(&self, bytes: Vec<i64>, mode: FileMode, flush: bool) {
        if let Err(e) = self.try_write(&bytes_of(&bytes, 0, None), mode, flush) {
            e.raise()
        }
    }

    pub fn write_as_bytes(&self, bytes: Vec<i64>, mode: FileMode, flush: bool) -> DartFuture<File> {
        io_ready(
            self.try_write(&bytes_of(&bytes, 0, None), mode, flush)
                .map(|_| self.clone()),
        )
    }

    fn try_delete(&self) -> Result<FileSystemEntity, FileSystemException> {
        std::fs::remove_file(&self.path)
            .map(|_| FileSystemEntity {
                path: self.path.clone(),
            })
            .map_err(|e| FileSystemException::of("Cannot delete file", &self.path, e))
    }

    pub fn delete_sync(&self, _recursive: bool) {
        if let Err(e) = self.try_delete() {
            e.raise()
        }
    }

    pub fn delete(&self, _recursive: bool) -> DartFuture<FileSystemEntity> {
        io_ready(self.try_delete())
    }
}

#[derive(Clone, Debug)]
pub struct RandomAccessFile {
    pub path: String,
    file: std::rc::Rc<std::cell::RefCell<std::fs::File>>,
}

impl PartialEq for RandomAccessFile {
    fn eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(&self.file, &other.file)
    }
}

impl RandomAccessFile {
    fn io<T>(&self, what: &str, result: std::io::Result<T>) -> Result<T, FileSystemException> {
        result.map_err(|e| FileSystemException::of(what, &self.path, e))
    }

    pub fn path(&self) -> String {
        self.path.clone()
    }

    pub fn length_sync(&self) -> i64 {
        match self.io(
            "Cannot retrieve length of file",
            self.file.borrow().metadata(),
        ) {
            Ok(m) => m.len() as i64,
            Err(e) => e.raise(),
        }
    }

    pub fn length(&self) -> DartFuture<i64> {
        io_ready(
            self.io(
                "Cannot retrieve length of file",
                self.file.borrow().metadata(),
            )
            .map(|m| m.len() as i64),
        )
    }

    pub fn position_sync(&self) -> i64 {
        use std::io::Seek;
        match self.io(
            "Cannot retrieve position",
            self.file.borrow_mut().stream_position(),
        ) {
            Ok(p) => p as i64,
            Err(e) => e.raise(),
        }
    }

    pub fn position(&self) -> DartFuture<i64> {
        DartFuture::ready(Ok(self.position_sync()))
    }

    fn try_set_position(&self, position: i64) -> Result<(), FileSystemException> {
        use std::io::Seek;
        self.io(
            "Cannot set position",
            self.file
                .borrow_mut()
                .seek(std::io::SeekFrom::Start(position.max(0) as u64)),
        )
        .map(|_| ())
    }

    pub fn set_position_sync(&self, position: i64) {
        if let Err(e) = self.try_set_position(position) {
            e.raise()
        }
    }

    pub fn set_position(&self, position: i64) -> DartFuture<RandomAccessFile> {
        io_ready(self.try_set_position(position).map(|_| self.clone()))
    }

    fn try_read(&self, count: usize) -> Result<Vec<u8>, FileSystemException> {
        use std::io::Read;
        let mut out = vec![0u8; count];
        let mut filled = 0;
        let mut handle = self.file.borrow_mut();
        while filled < count {
            let n = self.io("Cannot read file", handle.read(&mut out[filled..]))?;
            if n == 0 {
                break;
            }
            filled += n;
        }
        out.truncate(filled);
        Ok(out)
    }

    pub fn read_sync(&self, count: i64) -> Vec<i64> {
        match self.try_read(count.max(0) as usize) {
            Ok(bytes) => bytes.into_iter().map(|b| b as i64).collect(),
            Err(e) => e.raise(),
        }
    }

    pub fn read(&self, count: i64) -> DartFuture<Vec<i64>> {
        io_ready(
            self.try_read(count.max(0) as usize)
                .map(|bytes| bytes.into_iter().map(|b| b as i64).collect()),
        )
    }

    /// `readInto(buffer, [start, end])`: the bytes read into the caller's
    /// buffer -- handed in as `&mut` (`IrMutRef`), a `Uint8List` or a
    /// `List<int>` alike (`DartByteSink`) -- and their count.
    pub fn read_into_sync<B: DartByteSink + ?Sized>(
        &self,
        buffer: &mut B,
        start: i64,
        end: Option<i64>,
    ) -> i64 {
        match self.try_read_into(buffer, start, end) {
            Ok(n) => n,
            Err(e) => e.raise(),
        }
    }

    fn try_read_into<B: DartByteSink + ?Sized>(
        &self,
        buffer: &mut B,
        start: i64,
        end: Option<i64>,
    ) -> Result<i64, FileSystemException> {
        let len = buffer.sink_len();
        let start = (start.max(0) as usize).min(len);
        let end = end
            .map(|e| (e.max(0) as usize).min(len))
            .unwrap_or(len)
            .max(start);
        let bytes = self.try_read(end - start)?;
        for (i, b) in bytes.iter().enumerate() {
            buffer.put_byte(start + i, *b);
        }
        Ok(bytes.len() as i64)
    }

    pub fn read_into<B: DartByteSink + ?Sized>(
        &self,
        buffer: &mut B,
        start: i64,
        end: Option<i64>,
    ) -> DartFuture<i64> {
        io_ready(self.try_read_into(buffer, start, end))
    }

    fn try_write(&self, bytes: &[u8]) -> Result<(), FileSystemException> {
        use std::io::Write;
        self.io("Cannot write file", self.file.borrow_mut().write_all(bytes))
    }

    pub fn write_from_sync(&self, buffer: Vec<i64>, start: i64, end: Option<i64>) {
        if let Err(e) = self.try_write(&bytes_of(&buffer, start, end)) {
            e.raise()
        }
    }

    pub fn write_from(
        &self,
        buffer: Vec<i64>,
        start: i64,
        end: Option<i64>,
    ) -> DartFuture<RandomAccessFile> {
        io_ready(
            self.try_write(&bytes_of(&buffer, start, end))
                .map(|_| self.clone()),
        )
    }

    pub fn write_string_sync(&self, string: String, _encoding: Utf8Codec) {
        if let Err(e) = self.try_write(string.as_bytes()) {
            e.raise()
        }
    }

    pub fn write_string(
        &self,
        string: String,
        _encoding: Utf8Codec,
    ) -> DartFuture<RandomAccessFile> {
        io_ready(self.try_write(string.as_bytes()).map(|_| self.clone()))
    }

    pub fn write_byte_sync(&self, value: i64) -> i64 {
        if let Err(e) = self.try_write(&[value as u8]) {
            e.raise()
        }
        1
    }

    fn try_truncate(&self, length: i64) -> Result<(), FileSystemException> {
        self.io(
            "Cannot truncate file",
            self.file.borrow_mut().set_len(length.max(0) as u64),
        )
    }

    pub fn truncate_sync(&self, length: i64) {
        if let Err(e) = self.try_truncate(length) {
            e.raise()
        }
    }

    pub fn truncate(&self, length: i64) -> DartFuture<RandomAccessFile> {
        io_ready(self.try_truncate(length).map(|_| self.clone()))
    }

    fn try_flush(&self) -> Result<(), FileSystemException> {
        use std::io::Write;
        self.io("Cannot flush file", self.file.borrow_mut().flush())
    }

    pub fn flush_sync(&self) {
        if let Err(e) = self.try_flush() {
            e.raise()
        }
    }

    pub fn flush(&self) -> DartFuture<RandomAccessFile> {
        io_ready(self.try_flush().map(|_| self.clone()))
    }

    pub fn close_sync(&self) {
        self.flush_sync()
    }

    pub fn close(&self) -> DartFuture<()> {
        io_ready(self.try_flush())
    }

    /// `lock`/`unlock`: one process here, no other holder to keep out.
    pub fn lock_sync(&self, _mode: FileLock, _start: i64, _end: i64) {}

    pub fn lock(&self, _mode: FileLock, _start: i64, _end: i64) -> DartFuture<RandomAccessFile> {
        DartFuture::ready(Ok(self.clone()))
    }

    pub fn unlock_sync(&self, _start: i64, _end: i64) {}

    pub fn unlock(&self, _start: i64, _end: i64) -> DartFuture<RandomAccessFile> {
        DartFuture::ready(Ok(self.clone()))
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct Directory {
    pub path: String,
}

impl Directory {
    pub fn new(path: String) -> Self {
        Directory { path }
    }

    pub fn path(&self) -> String {
        self.path.clone()
    }

    /// `Directory.systemTemp`.
    pub fn system_temp() -> Directory {
        Directory::new(std::env::temp_dir().to_string_lossy().into_owned())
    }

    pub fn parent(&self) -> Directory {
        Directory::new(
            std::path::Path::new(&self.path)
                .parent()
                .map(|p| p.to_string_lossy().into_owned())
                .unwrap_or_else(|| ".".to_string()),
        )
    }

    pub fn exists_sync(&self) -> bool {
        std::path::Path::new(&self.path).is_dir()
    }

    pub fn exists(&self) -> DartFuture<bool> {
        DartFuture::ready(Ok(self.exists_sync()))
    }

    fn try_create(&self, recursive: bool) -> Result<(), FileSystemException> {
        let made = if recursive {
            std::fs::create_dir_all(&self.path)
        } else {
            std::fs::create_dir(&self.path)
        };
        match made {
            Ok(()) => Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => Ok(()),
            Err(e) => Err(FileSystemException::of("Creation failed", &self.path, e)),
        }
    }

    pub fn create_sync(&self, recursive: bool) {
        if let Err(e) = self.try_create(recursive) {
            e.raise()
        }
    }

    pub fn create(&self, recursive: bool) -> DartFuture<Directory> {
        io_ready(self.try_create(recursive).map(|_| self.clone()))
    }

    fn try_delete(&self, recursive: bool) -> Result<FileSystemEntity, FileSystemException> {
        let removed = if recursive {
            std::fs::remove_dir_all(&self.path)
        } else {
            std::fs::remove_dir(&self.path)
        };
        removed
            .map(|_| FileSystemEntity {
                path: self.path.clone(),
            })
            .map_err(|e| FileSystemException::of("Deletion failed", &self.path, e))
    }

    pub fn delete_sync(&self, recursive: bool) {
        if let Err(e) = self.try_delete(recursive) {
            e.raise()
        }
    }

    pub fn delete(&self, recursive: bool) -> DartFuture<FileSystemEntity> {
        io_ready(self.try_delete(recursive))
    }
}

/// Dart's `Null` as a *type*: `Option<Null>` is a value that is always
/// `None`, which is what a `List<Null>` or an `Expando<Null>` holds.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct Null;

/// A struct holding one derives `Debug` (`RenderTapRegionSurface._cachedResults`).
impl<T> fmt::Debug for Expando<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Instance of 'Expando'")
    }
}

/// `dart:core`'s `Expando<T>`: a value attached to an object by identity.
///
/// Keyed by the address behind the handle, since identity here is the `Rc`.
/// Dart's is weak -- the entry goes when the object does -- and this one is
/// not: an object that is expando-tagged and then dropped leaves its entry
/// behind. The gallery tags a handful of long-lived messengers, which is why
/// that is a note and not a bug.
#[derive(Clone)]
pub struct Expando<T> {
    entries: std::cell::RefCell<Vec<(usize, T)>>,
}

impl<T: Clone> Expando<T> {
    /// `Expando([name])`: the name is for debugging only.
    pub fn new(_name: Option<String>) -> Self {
        Expando {
            entries: std::cell::RefCell::new(Vec::new()),
        }
    }

    fn key<O: ?Sized>(object: &std::rc::Rc<O>) -> usize {
        std::rc::Rc::as_ptr(object) as *const u8 as usize
    }

    /// Keyed by the object's identity, whatever handle it arrives as
    /// (`_profiledBinaryMessengers[this]` with `this` an `Rc<dyn
    /// MethodChannel>`, run459).
    pub fn get<O: ?Sized>(&self, object: &std::rc::Rc<O>) -> Option<T> {
        let key = Self::key(object);
        self.entries
            .borrow()
            .iter()
            .find(|(k, _)| *k == key)
            .map(|(_, v)| v.clone())
    }

    pub fn set<O: ?Sized>(&self, object: std::rc::Rc<O>, value: Option<T>) {
        let key = Self::key(&object);
        let mut entries = self.entries.borrow_mut();
        entries.retain(|(k, _)| *k != key);
        if let Some(value) = value {
            entries.push((key, value));
        }
    }
}

/// The engine's side of `dart:ui`. Every `external` member the compiler
/// translates becomes a call through here, by the symbol its `@Native`
/// annotation registers it under, with its arguments as objects and a
/// flag saying whether a value comes back. The *native host* -- the
/// runtime crate, forwarding to the engine -- answers; installed with
/// `set_native_host`. Without one, a native that returns nothing does
/// nothing (counted, so a headless run can say how many it skipped), and
/// one that returns a value has nothing to return and panics naming
/// itself: that is where the headless ruler ends and the runtime begins.
/// `Ok(None)` from a host means "not mine": the absent engine's answer
/// stands, recorded as without a host.
pub type NativeHost = dyn Fn(
    &str,
    Vec<std::rc::Rc<dyn Object>>,
) -> Result<Option<std::rc::Rc<dyn Object>>, std::rc::Rc<dyn Object>>;

thread_local! {
    static NATIVE_HOST: std::cell::RefCell<Option<Box<NativeHost>>> = std::cell::RefCell::new(None);
    static NATIVES_SKIPPED: std::cell::RefCell<Vec<String>> = std::cell::RefCell::new(Vec::new());
    static NATIVES_UNANSWERED: std::cell::RefCell<Vec<String>> = std::cell::RefCell::new(Vec::new());
}

pub fn set_native_host(host: Box<NativeHost>) {
    NATIVE_HOST.with(|h| *h.borrow_mut() = Some(host));
}

/// The void natives a run without a host skipped, in order, each once.
pub fn natives_skipped() -> Vec<String> {
    NATIVES_SKIPPED.with(|s| s.borrow().clone())
}

pub fn dart_native(
    symbol: String,
    args: Vec<std::rc::Rc<dyn Object>>,
    returns: bool,
) -> Result<std::rc::Rc<dyn Object>, std::rc::Rc<dyn Object>> {
    let answered = NATIVE_HOST.with(|h| h.borrow().as_ref().map(|host| host(&symbol, args)));
    match answered {
        Some(Ok(Some(answer))) => return Ok(answer),
        Some(Err(error)) => return Err(error),
        _ => {}
    }
    // No host: a void native is skipped, and one that returns a value is
    // answered with Dart's null -- what an engine that is not there
    // answers. A nullable result (`RootIsolateToken?`, run462) takes it
    // as null; a non-nullable one fails at its own cast, naming the
    // symbol here. Both lists are reported at the end of the run.
    let list = if returns {
        &NATIVES_UNANSWERED
    } else {
        &NATIVES_SKIPPED
    };
    list.with(|s| {
        let mut s = s.borrow_mut();
        if !s.contains(&symbol) {
            s.push(symbol);
        }
    });
    Ok(std::rc::Rc::new(Null) as std::rc::Rc<dyn Object>)
}

/// What a native's answer is read as, by the declared return type: the
/// host's object downcast to it, or -- with no host -- the value an
/// engine that is not there gives: zero, false, the empty string, null.
/// `RootIsolateToken.instance` reads a `0` token as "none" itself.
pub trait NativeAnswer: Sized {
    fn from_answer(answer: std::rc::Rc<dyn Object>, symbol: &str) -> Self;
    fn absent() -> Self;
}

macro_rules! native_answer_scalar {
    ($t:ty, $absent:expr) => {
        impl NativeAnswer for $t {
            fn from_answer(answer: std::rc::Rc<dyn Object>, symbol: &str) -> Self {
                let object: &dyn Object = answer.as_ref();
                match object.as_any().downcast_ref::<$t>() {
                    Some(value) => value.clone(),
                    None => panic!(
                        "native `{}` answered {:?} where {} was declared",
                        symbol,
                        answer,
                        stringify!($t)
                    ),
                }
            }
            fn absent() -> Self {
                $absent
            }
        }
    };
}

native_answer_scalar!(i64, 0);
native_answer_scalar!(f64, 0.0);
native_answer_scalar!(bool, false);
native_answer_scalar!(String, String::new());

impl NativeAnswer for () {
    fn from_answer(_answer: std::rc::Rc<dyn Object>, _symbol: &str) -> Self {}
    fn absent() -> Self {}
}

impl NativeAnswer for std::rc::Rc<dyn Object> {
    fn from_answer(answer: std::rc::Rc<dyn Object>, _symbol: &str) -> Self {
        answer
    }
    fn absent() -> Self {
        std::rc::Rc::new(Null) as std::rc::Rc<dyn Object>
    }
}

/// A list out of a native (`Paragraph.getBoxesForRange`, a `Float32List`):
/// the host's list converted (`FromDynamic`), or the empty one.
impl<T: FromDynamic> NativeAnswer for Vec<T> {
    fn from_answer(answer: std::rc::Rc<dyn Object>, symbol: &str) -> Self {
        match dart_cast_list::<T>(&answer) {
            Some(list) => list,
            None => panic!(
                "native `{}` answered {:?} where a list was declared",
                symbol, answer
            ),
        }
    }
    fn absent() -> Self {
        Vec::new()
    }
}

impl<T: NativeAnswer> NativeAnswer for Option<T> {
    fn from_answer(answer: std::rc::Rc<dyn Object>, symbol: &str) -> Self {
        dart_nullable(answer).map(|value| T::from_answer(value, symbol))
    }
    fn absent() -> Self {
        None
    }
}

/// A native that returns a value, read as its declared type
/// (`NativeAnswer`); without a host the absent engine's value, recorded.
pub fn dart_native_as<T: NativeAnswer>(
    symbol: String,
    args: Vec<std::rc::Rc<dyn Object>>,
) -> Result<T, std::rc::Rc<dyn Object>> {
    let answered = NATIVE_HOST.with(|h| h.borrow().as_ref().map(|host| host(&symbol, args)));
    match answered {
        Some(Ok(Some(answer))) => return Ok(T::from_answer(answer, &symbol)),
        Some(Err(error)) => return Err(error),
        _ => {}
    }
    NATIVES_UNANSWERED.with(|s| {
        let mut s = s.borrow_mut();
        if !s.contains(&symbol) {
            s.push(symbol);
        }
    });
    Ok(T::absent())
}

/// The valued natives a run without a host answered with null, in order.
pub fn natives_unanswered() -> Vec<String> {
    NATIVES_UNANSWERED.with(|s| s.borrow().clone())
}

/// `identical(a, b)` on two nullable handles: both null, or one object.
pub fn dart_identical_opt<T: ?Sized>(
    a: &Option<std::rc::Rc<T>>,
    b: &Option<std::rc::Rc<T>>,
) -> bool {
    match (a, b) {
        (None, None) => true,
        (Some(x), Some(y)) => std::rc::Rc::ptr_eq(x, y),
        _ => false,
    }
}

/// A `dynamic` as the `Option` a `T?` is: `None` for the `Null` object.
pub fn dart_nullable(value: std::rc::Rc<dyn Object>) -> Option<std::rc::Rc<dyn Object>> {
    let object: &dyn Object = value.as_ref();
    if object.as_any().is::<Null>() {
        None
    } else {
        Some(value)
    }
}

/// `dart:ffi`, as far as the gallery's dill reaches it: the Windows plugins
/// (`win32`, `url_launcher_windows`) that the tree shaker keeps because a
/// platform check is not a constant. None of it runs on the host this
/// targets, and none of it can: these are the names, with no behaviour, so
/// that the code around them compiles and the refusal is at the call.
pub struct Pointer<T>(pub usize, std::marker::PhantomData<T>);

impl<T> Pointer<T> {
    pub fn from_address(address: i64) -> Self {
        Pointer(address as usize, std::marker::PhantomData)
    }

    pub fn address(&self) -> i64 {
        self.0 as i64
    }
}

impl<T> Clone for Pointer<T> {
    fn clone(&self) -> Self {
        Pointer(self.0, std::marker::PhantomData)
    }
}

/// A marker, not a trait: `Pointer<NativeType>` is written as a *type*
/// upstream, and a trait there wants `dyn` (4 `E0782`).
pub struct NativeType;
pub struct Void;
pub struct NativeFunction<T>(std::marker::PhantomData<T>);
#[derive(Clone, Copy, Debug)]
pub struct DynamicLibrary;
impl fmt::Debug for Allocator {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Instance of 'Allocator'")
    }
}

#[derive(Clone, Copy)]
pub struct Allocator;

/// `dart:core`'s `WeakReference<T>`, with `T` the Dart type as spelled
/// here (a handle `Rc<dyn X>`, or a value). Held *strongly*: nothing here
/// collects, so a reference that never clears is what a weak one is in
/// this runtime; what is kept is the `WeakReference` surface (`target`)
/// the translated code reads (the navigator's `_RouteEntry`, ws505).
#[derive(Clone)]
pub struct WeakReference<T>(T);

impl<T: Clone> WeakReference<T> {
    pub fn new(target: T) -> Self {
        WeakReference(target)
    }

    pub fn target(&self) -> Option<T> {
        Some(self.0.clone())
    }
}

impl<T> fmt::Debug for WeakReference<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("WeakReference")
    }
}

impl<T: DartEq> PartialEq for WeakReference<T> {
    fn eq(&self, other: &Self) -> bool {
        self.0.dart_eq(&other.0)
    }
}

/// `dart:async`'s `Stream<T>` as a type only. There is no event loop here
/// to drive one, so this is a name for signatures to agree on (the license
/// registry's collectors return them); anything that listens will not
/// compile, and says so.
pub struct Stream<T> {
    /// The events, all of them already known: without an event loop a
    /// stream here is a *ready* stream, and `listen` delivers everything it
    /// holds and then `onDone`, synchronously.
    events: std::rc::Rc<std::cell::RefCell<Vec<T>>>,
}

/// `StreamView<T>` is a stream that forwards to another; with nothing
/// asynchronous in between it is the same thing.
pub type StreamView<T> = Stream<T>;

/// `StreamSubscription<T>`: what `listen` hands back. Everything was
/// delivered before it was returned, so `cancel` has nothing left to stop.
#[derive(Clone, Debug, PartialEq)]
pub struct StreamSubscription<T> {
    _phantom: std::marker::PhantomData<T>,
}

impl<T> StreamSubscription<T> {
    pub fn cancel(&self) -> DartFuture<()> {
        DartFuture::ready(Ok(()))
    }

    pub fn pause(&self, _resume_signal: Option<std::rc::Rc<dyn Object>>) {}

    pub fn resume(&self) {}
}

impl<T: Clone + 'static> Stream<T> {
    /// `Stream.value(v)`: a single-element stream.
    pub fn value(value: T) -> Stream<T> {
        Stream {
            events: std::rc::Rc::new(std::cell::RefCell::new(vec![value])),
        }
    }

    /// `Stream.empty()`.
    pub fn empty() -> Stream<T> {
        Stream {
            events: std::rc::Rc::new(std::cell::RefCell::new(Vec::new())),
        }
    }

    /// `Stream.fromIterable(xs)`.
    pub fn from_iterable(elements: Vec<T>) -> Stream<T> {
        Stream {
            events: std::rc::Rc::new(std::cell::RefCell::new(elements)),
        }
    }

    /// `listen(onData, {onError, onDone, cancelOnError})`: every event, then
    /// done. `onError` never fires -- a ready stream holds no errors.
    pub fn listen(
        &self,
        on_data: Option<std::rc::Rc<dyn Fn(T) -> ()>>,
        _on_error: Option<std::rc::Rc<dyn Fn(std::rc::Rc<dyn Object>, Option<StackTrace>) -> ()>>,
        on_done: Option<std::rc::Rc<dyn Fn() -> ()>>,
        _cancel_on_error: Option<bool>,
    ) -> StreamSubscription<T> {
        let events: Vec<T> = self.events.borrow().clone();
        if let Some(f) = &on_data {
            for e in events {
                f(e);
            }
        }
        if let Some(d) = &on_done {
            d();
        }
        StreamSubscription {
            _phantom: std::marker::PhantomData,
        }
    }

    /// `toList()`.
    pub fn to_list(&self) -> DartFuture<Vec<T>> {
        DartFuture::ready(Ok(self.events.borrow().clone()))
    }

    /// `first`.
    pub fn first(&self) -> DartFuture<T> {
        let first = self
            .events
            .borrow()
            .first()
            .cloned()
            .expect("Bad state: No element");
        DartFuture::ready(Ok(first))
    }

    /// `isBroadcast`: a ready stream can be listened to any number of times.
    pub fn is_broadcast(&self) -> bool {
        true
    }
}

impl<T> Clone for Stream<T> {
    fn clone(&self) -> Self {
        Stream {
            events: self.events.clone(),
        }
    }
}

impl<T: std::fmt::Debug> std::fmt::Debug for Stream<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Stream({:?})", self.events.borrow())
    }
}

impl<T> PartialEq for Stream<T> {
    fn eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(&self.events, &other.events)
    }
}

/// `dart:convert`'s `ByteConversionSink.withCallback(callback)`: collects
/// every chunk and hands the whole to the callback on `close`.
pub struct _ByteCallbackSink {
    accumulated: std::cell::RefCell<Vec<i64>>,
    callback: std::rc::Rc<dyn Fn(Vec<i64>) -> Result<(), DartError>>,
}

impl _ByteCallbackSink {
    pub fn new(
        callback: std::rc::Rc<dyn Fn(Vec<i64>) -> Result<(), DartError>>,
    ) -> ByteConversionSink {
        std::rc::Rc::new(_ByteCallbackSink {
            accumulated: std::cell::RefCell::new(Vec::new()),
            callback,
        })
    }
}

impl DartSink<Vec<i64>> for _ByteCallbackSink {
    fn add(&self, data: Vec<i64>) {
        self.accumulated.borrow_mut().extend(data);
    }

    fn close(&self) {
        let all = self.accumulated.borrow().clone();
        // A `Sink::close` cannot fail here; the callback's error is loud.
        (self.callback)(all).unwrap();
    }
}

impl Error {
    /// `Error.throwWithStackTrace(error, stackTrace)`: a throw, which on
    /// this side is a panic (see the backend's `_thrown`).
    pub fn throw_with_stack_trace<E: std::fmt::Debug>(error: E, _stack: StackTrace) -> ! {
        panic!("uncaught Dart exception: {:?}", error)
    }
}

