/// Dart's `String` methods, under their Dart names, on Rust's `String`.
///
/// The backend spells a Dart call `s.codeUnitAt(i)` as `s.code_unit_at(i)`
/// and stops there; this trait is where those names land. Only names `str`
/// does not already have: a trait method on `String` shadows a `str` one,
/// and `split`/`contains`/`trim` here broke the fixtures that used them. Lengths and
/// indices are in UTF-16 code units, as Dart's are -- `len()` would have
/// counted bytes, and "length" is the commonest String member in the
/// gallery (19 sites in the leaf crates alone).
pub trait DartString {
    fn length(&self) -> i64;
    fn code_unit_at(&self, index: i64) -> i64;
    fn substring(&self, start: i64, end: Option<i64>) -> String;
    fn to_lower_case(&self) -> String;
    fn to_upper_case(&self) -> String;
    /// `indexOf(pattern, [start = 0])`: the default is filled in by the
    /// front end, so `start` is never absent here.
    fn index_of(&self, other: String, start: i64) -> i64;
    fn replace_all(&self, from: String, to: String) -> String;
    /// `replaceFirst(from, to)`: the first occurrence replaced. Named apart
    /// from std's unstable inherent `replace_first`, which outranks a trait's.
    /// `replaceFirst(from, to, [startIndex = 0])`: the first occurrence at
    /// or after `start_index` (Dart's optional third parameter, which the
    /// front end fills in; `GoogleFontsVariant.toString`, ws563).
    fn dart_replace_first(&self, from: String, to: String, start_index: i64) -> String;
    /// `startsWith(other)` / `endsWith(other)` with a `String`, which is
    /// no `Pattern` for `str`'s own (the backend routes the Dart names
    /// here, see `_stdShadowed`).
    fn dart_starts_with(&self, other: String) -> bool;
    fn dart_ends_with(&self, other: String) -> bool;
    fn is_not_empty(&self) -> bool;
    fn pad_left(&self, width: i64, padding: String) -> String;
    fn pad_right(&self, width: i64, padding: String) -> String;
    fn code_units(&self) -> Vec<i64>;
    /// `replaceRange(start, end, replacement)`: a new string.
    fn replace_range_dart(&self, start: i64, end: Option<i64>, replacement: String) -> String;
    /// `startsWith(pattern, index)`.
    fn starts_with_at(&self, pattern: String, index: i64) -> bool;
    /// `contains(other, [startIndex])`: Rust's `contains` wants a `&str`
    /// and has no start.
    fn contains_dart(&self, pattern: String, start: i64) -> bool;
    /// `'0' * n`.
    fn repeat_dart(&self, times: i64) -> String;
    /// `split(pattern)`, into owned pieces.
    fn split_dart(&self, pattern: String) -> Vec<String>;
    /// `s[i]`: the one-code-unit String at `i`.
    fn char_at(&self, index: i64) -> String;
    /// `trim()`/`trimLeft()`/`trimRight()`, owned.
    fn trim_dart(&self) -> String;
    fn trim_left_dart(&self) -> String;
    fn trim_right_dart(&self) -> String;
    /// `hashCode`: stable within a process, not Dart's numbers.
    fn hash_code(&self) -> i64;
}

impl DartString for String {
    fn length(&self) -> i64 {
        self.encode_utf16().count() as i64
    }

    fn code_unit_at(&self, index: i64) -> i64 {
        self.encode_utf16()
            .nth(index as usize)
            .map(|u| u as i64)
            .unwrap_or(0)
    }

    fn substring(&self, start: i64, end: Option<i64>) -> String {
        let units: Vec<u16> = self.encode_utf16().collect();
        let end = end
            .map(|e| e as usize)
            .unwrap_or(units.len())
            .min(units.len());
        let start = (start.max(0) as usize).min(end);
        String::from_utf16_lossy(&units[start..end])
    }

    fn to_lower_case(&self) -> String {
        self.to_lowercase()
    }

    fn to_upper_case(&self) -> String {
        self.to_uppercase()
    }

    fn index_of(&self, other: String, start: i64) -> i64 {
        let units: Vec<u16> = self.encode_utf16().collect();
        let needle: Vec<u16> = other.encode_utf16().collect();
        let from = start.max(0) as usize;
        if needle.is_empty() {
            return from.min(units.len()) as i64;
        }
        (from..units.len().saturating_sub(needle.len() - 1))
            .find(|&i| units[i..i + needle.len()] == needle[..])
            .map(|i| i as i64)
            .unwrap_or(-1)
    }

    fn dart_starts_with(&self, other: String) -> bool {
        str::starts_with(self, other.as_str())
    }

    fn dart_ends_with(&self, other: String) -> bool {
        str::ends_with(self, other.as_str())
    }

    fn dart_replace_first(&self, from: String, to: String, start_index: i64) -> String {
        let at = self
            .char_indices()
            .nth(start_index.max(0) as usize)
            .map(|(i, _)| i)
            .unwrap_or(self.len());
        let (head, tail) = self.split_at(at);
        format!("{}{}", head, tail.replacen(&from, &to, 1))
    }

    fn replace_all(&self, from: String, to: String) -> String {
        str::replace(self, from.as_str(), to.as_str())
    }

    fn is_not_empty(&self) -> bool {
        !str::is_empty(self)
    }

    fn pad_left(&self, width: i64, padding: String) -> String {
        let mut out = String::new();
        let mut n = DartString::length(self);
        while n < width {
            out.push_str(&padding);
            n += DartString::length(&padding).max(1);
        }
        out.push_str(self);
        out
    }

    fn pad_right(&self, width: i64, padding: String) -> String {
        let mut out = self.clone();
        let mut n = DartString::length(self);
        while n < width {
            out.push_str(&padding);
            n += DartString::length(&padding).max(1);
        }
        out
    }

    fn code_units(&self) -> Vec<i64> {
        self.encode_utf16().map(|u| u as i64).collect()
    }

    fn hash_code(&self) -> i64 {
        use std::hash::{Hash, Hasher};
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        self.hash(&mut hasher);
        (hasher.finish() & 0x3fff_ffff) as i64
    }

    fn trim_dart(&self) -> String {
        self.trim().to_string()
    }
    fn trim_left_dart(&self) -> String {
        self.trim_start().to_string()
    }
    fn trim_right_dart(&self) -> String {
        self.trim_end().to_string()
    }

    fn char_at(&self, index: i64) -> String {
        let units: Vec<u16> = self.encode_utf16().collect();
        String::from_utf16_lossy(&units[index as usize..index as usize + 1])
    }

    fn split_dart(&self, pattern: String) -> Vec<String> {
        let s: &str = self.as_ref();
        if pattern.is_empty() {
            return s.chars().map(|c| c.to_string()).collect();
        }
        s.split(pattern.as_str()).map(|p| p.to_string()).collect()
    }
    fn repeat_dart(&self, times: i64) -> String {
        let s: &str = self.as_ref();
        s.repeat(times.max(0) as usize)
    }
    fn contains_dart(&self, pattern: String, start: i64) -> bool {
        let s: &str = self.as_ref();
        let from = s
            .char_indices()
            .nth(start.max(0) as usize)
            .map(|(i, _)| i)
            .unwrap_or(s.len());
        s[from..].contains(pattern.as_str())
    }
    fn starts_with_at(&self, pattern: String, index: i64) -> bool {
        let units: Vec<u16> = self.encode_utf16().collect();
        let needle: Vec<u16> = pattern.encode_utf16().collect();
        let from = index.max(0) as usize;
        from + needle.len() <= units.len() && units[from..from + needle.len()] == needle[..]
    }

    fn replace_range_dart(&self, start: i64, end: Option<i64>, replacement: String) -> String {
        let end = end.unwrap_or(self.length());
        let units: Vec<u16> = self.encode_utf16().collect();
        let end = (end.max(0) as usize).min(units.len());
        let start = (start.max(0) as usize).min(end);
        let mut out = String::from_utf16_lossy(&units[..start]);
        out.push_str(&replacement);
        out.push_str(&String::from_utf16_lossy(&units[end..]));
        out
    }
}

/// `dart:ui`'s native hooks, which upstream implements in C++ behind
/// `external` declarations. `_print` is stdout; `_scheduleMicrotask` runs
/// the callback *now* -- there is no event loop here to run it after the
/// current turn, and "now" is the ordering a single-threaded program can
/// observe least. This is where to look when something depended on the
/// delay.
pub fn _print(arg: String) {
    println!("{}", arg);
}

pub fn _print_debug(arg: String) {
    eprintln!("{}", arg);
}

/// `dart:core`'s `print(Object? object)`: the object's `toString()` to
/// stdout.
pub fn dart_print(object: std::rc::Rc<dyn Object>) {
    println!("{}", dart_object_str_ref(&*object));
}

pub fn _schedule_microtask(callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>) {
    run_callback("a microtask", || callback());
}

thread_local! {
    /// Callbacks the event loop ran that threw or panicked (`run_callback`).
    static UNCAUGHT: std::cell::RefCell<i64> = std::cell::RefCell::new(0);
}

/// How many event-loop callbacks threw or panicked so far.
pub fn uncaught_count() -> i64 {
    UNCAUGHT.with(|u| *u.borrow())
}

/// An event-loop callback -- a timer's, a microtask's -- run as Dart's loop
/// runs it: an error it throws is uncaught, reported, and the loop goes
/// on to the next callback (the isolate does not die). A *panic* in it --
/// a stub, an `unwrap` -- is reported the same way and the loop goes on
/// too, so that what the program built before it can still be looked at
/// (the render tree dump behind a stub on the compositing path, run553).
/// The unwinding drops every `RefMut` the callback held.
pub fn run_callback<F: FnOnce() -> Result<(), DartError>>(what: &str, callback: F) {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(callback)) {
        Ok(Ok(())) => {}
        Ok(Err(error)) => {
            UNCAUGHT.with(|u| *u.borrow_mut() += 1);
            eprintln!(
                "dart2rust: uncaught Dart exception in {}: {}",
                what,
                dart_error_text(&error)
            );
        }
        Err(payload) => {
            UNCAUGHT.with(|u| *u.borrow_mut() += 1);
            let text = payload
                .downcast_ref::<String>()
                .cloned()
                .or_else(|| payload.downcast_ref::<&str>().map(|s| s.to_string()))
                .unwrap_or_else(|| "(no message)".to_string());
            eprintln!("dart2rust: {} panicked: {}", what, text);
        }
    }
}

/// `dart:core`'s `_StringStackTrace`, a stack trace that is just text: the
/// same type, so it goes where a `StackTrace` is wanted.
pub type _StringStackTrace = StackTrace;

/// `dart:io`'s `InternetAddress`, as far as `dart:ui` asks of it: whether a
/// host is the loopback.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct InternetAddress {
    pub host: String,
}

impl InternetAddress {
    /// `InternetAddress(address, {type})`: the type is a hint this stub
    /// does not need.
    pub fn new(host: String, _type: Option<i64>) -> Self {
        InternetAddress { host }
    }

    pub fn is_loopback(&self) -> bool {
        self.host == "localhost" || self.host.starts_with("127.") || self.host == "::1"
    }
}

/// `dart:core`'s `_Uri`: the class `Uri(..)` constructs behind the
/// interface. Nine optional parts, assembled into the one string this
/// prelude's `Uri` keeps.
pub struct _Uri;

impl _Uri {
    pub fn new(
        scheme: Option<String>,
        user_info: Option<String>,
        host: Option<String>,
        port: Option<i64>,
        path: Option<String>,
        path_segments: Option<Vec<String>>,
        query: Option<String>,
        query_parameters: Option<Map<String, std::rc::Rc<dyn Object>>>,
        fragment: Option<String>,
    ) -> Uri {
        let _ = query_parameters;
        let mut text = String::new();
        if let Some(s) = scheme {
            text.push_str(&s);
            text.push(':');
        }
        if host.is_some() || user_info.is_some() {
            text.push_str("//");
            if let Some(u) = user_info {
                text.push_str(&u);
                text.push('@');
            }
            if let Some(h) = host {
                text.push_str(&h);
            }
            if let Some(p) = port {
                text.push_str(&format!(":{}", p));
            }
        }
        match (path, path_segments) {
            (Some(p), _) => text.push_str(&p),
            (None, Some(segments)) => text.push_str(&segments.join("/")),
            (None, None) => {}
        }
        if let Some(q) = query {
            text.push('?');
            text.push_str(&q);
        }
        if let Some(f) = fragment {
            text.push('#');
            text.push_str(&f);
        }
        Uri { text }
    }
}
/// `Object.hash(a, b, ..)`: up to twenty parts, the unused ones arriving
/// as `SentinelValue` (skipped). Each part's `hashCode` through the Object
/// protocol (`dart_hash_any`), combined -- consistent with `==` there, as
/// Dart's is; the debug text it hashed before was not (a closure has none,
/// and two handles to one object printed alike or not by their fields).
pub fn object_hash<
    A: DartAny,
    B: DartAny,
    C: DartAny,
    D: DartAny,
    E: DartAny,
    F: DartAny,
    G: DartAny,
    H: DartAny,
    I: DartAny,
    J: DartAny,
    K: DartAny,
    L: DartAny,
    M: DartAny,
    N: DartAny,
    O: DartAny,
    P: DartAny,
    Q: DartAny,
    R: DartAny,
    S: DartAny,
    T: DartAny,
>(
    a: A,
    b: B,
    c: C,
    d: D,
    e: E,
    f: F,
    g: G,
    h: H,
    i: I,
    j: J,
    k: K,
    l: L,
    m: M,
    n: N,
    o: O,
    p: P,
    q: Q,
    r: R,
    s: S,
    t: T,
) -> i64 {
    let mut hash: i64 = 0;
    dart_hash_part(&mut hash, &a);
    dart_hash_part(&mut hash, &b);
    dart_hash_part(&mut hash, &c);
    dart_hash_part(&mut hash, &d);
    dart_hash_part(&mut hash, &e);
    dart_hash_part(&mut hash, &f);
    dart_hash_part(&mut hash, &g);
    dart_hash_part(&mut hash, &h);
    dart_hash_part(&mut hash, &i);
    dart_hash_part(&mut hash, &j);
    dart_hash_part(&mut hash, &k);
    dart_hash_part(&mut hash, &l);
    dart_hash_part(&mut hash, &m);
    dart_hash_part(&mut hash, &n);
    dart_hash_part(&mut hash, &o);
    dart_hash_part(&mut hash, &p);
    dart_hash_part(&mut hash, &q);
    dart_hash_part(&mut hash, &r);
    dart_hash_part(&mut hash, &s);
    dart_hash_part(&mut hash, &t);
    hash & 0x3fff_ffff
}

fn dart_hash_part<T: DartAny>(hash: &mut i64, part: &T) {
    if part
        .dart_any_ref()
        .downcast_ref::<SentinelValue>()
        .is_some()
    {
        return;
    }
    let h = part.dart_hash_any();
    *hash = (hash.wrapping_mul(31)).wrapping_add(h) & 0x3fff_ffff;
}
/// `Object.hashAll(xs)`: a hash of the elements' `hashCode`s in order.
pub fn object_hash_all<T: DartAny>(items: Vec<T>) -> i64 {
    let mut hash: i64 = 0;
    for item in &items {
        dart_hash_part(&mut hash, item);
    }
    hash & 0x3fff_ffff
}

/// More of `dart:ui`'s hooks: the callback-handle registry, which nothing
/// here uses across an isolate boundary, so there are no handles.
/// `_invoke1WithReturn<A, R>(R Function(A)? callback, Zone? zone, A arg)`:
/// `R?`, null when there is no callback.
pub fn _invoke1_with_return<A, R>(
    callback: Option<std::rc::Rc<dyn Fn(A) -> Result<R, DartError>>>,
    _zone: Zone,
    arg: A,
) -> Result<Option<R>, DartError> {
    callback.map(|f| f(arg)).transpose()
}

#[allow(dead_code)]
fn _invoke1_with_return_unused<A, R>(
    callback: std::rc::Rc<dyn Fn(A) -> Result<R, DartError>>,
    _zone: Zone,
    arg: A,
) -> Result<R, DartError> {
    callback(arg)
}

pub fn _get_callback_handle(_callback: std::rc::Rc<dyn Object>) -> Option<i64> {
    None
}

pub fn _get_callback_from_handle(_handle: i64) -> std::rc::Rc<dyn Object> {
    dart_null_object()
}

/// A value in a string interpolation, when it is not a string or a number:
/// Dart calls `toString()`, and the translated classes carry theirs as
/// `Debug`. Not the same text -- `Offset { dx: 1.0, dy: 2.0 }` where Dart
/// prints `Offset(1.0, 2.0)` -- and nothing here reads it back. 57 parts
/// `cannot be formatted with the default formatter`.
pub fn dart_str<T: std::fmt::Debug>(value: T) -> String {
    format!("{:?}", value)
}

/// Dart's `double.toString()`: an integral value keeps its `.0`
/// (`3.0`, where Rust's `{}` says `3`), the infinities are spelled out,
/// and the rest is the shortest round-trip text both agree on. The
/// render tree's `Size(800.0, 600.0)` is compared against Flutter's own
/// dump (ws541).
pub fn dart_double_str(value: f64) -> String {
    if value.is_nan() {
        return "NaN".to_string();
    }
    if value.is_infinite() {
        return if value > 0.0 { "Infinity" } else { "-Infinity" }.to_string();
    }
    if value == value.trunc() && value.abs() < 1e21 {
        return format!("{:.1}", value);
    }
    format!("{}", value)
}

/// Dart's `identical` on two values typed `Object`: the same object, or
/// two of the core values Dart canonicalises -- numbers, strings, `Type`s,
/// `null` -- that are equal (`identical(value, keyValuePairs[i])` in
/// `_HashCollisionNode.put`, ws557).
pub fn dart_identical(a: &std::rc::Rc<dyn Object>, b: &std::rc::Rc<dyn Object>) -> bool {
    if std::rc::Rc::ptr_eq(a, b) {
        return true;
    }
    let any = a.as_any();
    let canonical = any.is::<i64>()
        || any.is::<f64>()
        || any.is::<bool>()
        || any.is::<String>()
        || any.is::<&'static str>()
        || any.is::<Type>()
        || any.is::<Null>()
        || any.is::<()>();
    canonical && object_eq(&**a, &**b)
}

/// Dart's shifts on a 64-bit `int`: a count of 64 or more shifts every
/// bit out (`<<` and `>>>` give 0, `>>` the sign), where Rust's operators
/// panic in a debug build (`_TrieNode._trieIndex` at bit index 65, the
/// sixth level of a `PersistentHashMap`, ws557). A negative count is an
/// `ArgumentError` in Dart; it panics here.
pub fn dart_shl(value: i64, count: i64) -> i64 {
    if count < 0 {
        panic!(
            "uncaught Dart exception: ArgumentError: negative shift count {}",
            count
        );
    }
    if count >= 64 {
        0
    } else {
        value.wrapping_shl(count as u32)
    }
}

pub fn dart_shr(value: i64, count: i64) -> i64 {
    if count < 0 {
        panic!(
            "uncaught Dart exception: ArgumentError: negative shift count {}",
            count
        );
    }
    if count >= 64 {
        if value < 0 {
            -1
        } else {
            0
        }
    } else {
        value >> count
    }
}

pub fn dart_ushr(value: i64, count: i64) -> i64 {
    if count < 0 {
        panic!(
            "uncaught Dart exception: ArgumentError: negative shift count {}",
            count
        );
    }
    if count >= 64 {
        0
    } else {
        ((value as u64) >> count) as i64
    }
}

/// A type parameter's type literal (`T` where a value goes): the class the
/// Rust type stands for, from its name -- `Rc<dyn X>` is `X`, a struct is
/// itself, the core values by their Dart names (see `Object::runtime_type`).
pub fn dart_type_of<T: ?Sized + 'static>() -> Type {
    let full = std::any::type_name::<T>();
    let inner = match full.rfind("dyn ") {
        Some(at) => {
            let rest = &full[at + 4..];
            let end = rest
                .find(|c: char| c == '+' || c == '>' || c == ' ' || c == ')')
                .unwrap_or(rest.len());
            &rest[..end]
        }
        None => full.split('<').next().unwrap_or(full),
    };
    let bare = inner.rsplit("::").next().unwrap_or(inner).trim();
    let name: &'static str = match bare {
        "i64" => "int",
        "f64" => "double",
        "bool" => "bool",
        "String" => "String",
        "Null" | "()" => "Null",
        other => Box::leak(other.to_string().into_boxed_str()),
    };
    Type { name }
}

/// Dart's `Symbol`: a member name as a value.
///
/// `#foo` in source, and what `Invocation.memberName` carries. Compared and
/// printed, nothing else -- there is no `dart:mirrors` here to look a name up
/// with. Prints as Dart prints it, `Symbol("foo")`, because the one reader of
/// it in this program interpolates it into an error message.
///
/// A private symbol (`#_start`) is private *to a library* in Dart, and two
/// libraries' `#_start` are different symbols. The library is dropped here: a
/// name is all a `Symbol` holds. Nothing in this program compares symbols
/// across libraries, and this is where to look when something does.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Symbol {
    pub name: &'static str,
}

impl Symbol {
    pub const fn of(name: &'static str) -> Self {
        Symbol { name }
    }
}

impl fmt::Display for Symbol {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Symbol(\"{}\")", self.name)
    }
}

/// A `Never` value, turned into whatever the caller needed.
///
/// Dart's `Never` is spelled `std::convert::Infallible` here (see the
/// backend's type map), and an `Infallible` does not coerce the way `!`
/// would: a getter declared `-> bool` cannot return one. `match x {}` on an
/// empty enum has every type at once, which is what `!` meant. The
/// `noSuchMethod` forwarders are where this is called.
pub fn never<T>(x: std::convert::Infallible) -> T {
    match x {}
}

/// Dart's `Invocation`: what `noSuchMethod` is handed.
///
/// The CFE writes one *forwarder* per interface member of a class that
/// declares `noSuchMethod` -- `_WidgetTextStyleMapper` gets thirty-four -- and
/// each builds one of these and passes it on. Measured across `package:` on
/// 2026-09-03: every `noSuchMethod` in the program reads exactly one thing off
/// it, `memberName`. So that is what it carries, with the kind beside it. The
/// positional, named and type arguments are **not** here: a `noSuchMethod`
/// that reads them would get nothing, and this struct is where to add them.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Invocation {
    pub member_name: Symbol,
    pub kind: InvocationKind,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum InvocationKind {
    Method,
    Getter,
    Setter,
}

impl Invocation {
    pub const fn getter(member_name: Symbol) -> Self {
        Invocation {
            member_name,
            kind: InvocationKind::Getter,
        }
    }

    pub const fn setter(member_name: Symbol) -> Self {
        Invocation {
            member_name,
            kind: InvocationKind::Setter,
        }
    }

    pub const fn method(member_name: Symbol) -> Self {
        Invocation {
            member_name,
            kind: InvocationKind::Method,
        }
    }

    pub fn member_name(&self) -> Symbol {
        self.member_name
    }

    pub fn is_getter(&self) -> bool {
        matches!(self.kind, InvocationKind::Getter)
    }

    pub fn is_setter(&self) -> bool {
        matches!(self.kind, InvocationKind::Setter)
    }

    pub fn is_method(&self) -> bool {
        matches!(self.kind, InvocationKind::Method)
    }
}

/// Dart's `Zone`.
///
/// A zone is the async context a callback was registered in, so that running
/// it later runs it under the same error handling. Upstream stores one beside
/// each callback -- `dart:ui` keeps a `_zone` next to every platform handler --
/// and then runs the callback in it.
///
/// There is exactly one zone here, because there is no runtime to make a
/// second: `Zone::CURRENT` is it, and `run` calls the callback directly. That
/// is what the root zone does in Dart too. A program that installs a zone of
/// its own to catch errors would not get that behaviour, and this is where to
/// look when it does not.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Zone;

impl Zone {
    /// `Zone.current`, a static getter upstream and so a call here.
    /// `Zone.root`: the one zone there is here.
    pub fn root() -> Zone {
        Zone::current()
    }

    pub fn current() -> Zone {
        Zone
    }

    pub const CURRENT: Zone = Zone;

    pub fn run<T>(&self, body: impl FnOnce() -> Result<T, DartError>) -> Result<T, DartError> {
        body()
    }

    /// `Zone.current[key]`: a `dynamic`, which is never an `Option` here;
    /// the root zone holds no values, so this is Dart's `null` as an object.
    pub fn index_of<K>(&self, _key: K) -> std::rc::Rc<dyn Object> {
        std::rc::Rc::new(Null)
    }

    /// `runGuarded(f)`: the root zone has no error handler to guard with.
    pub fn run_guarded(
        &self,
        body: std::rc::Rc<dyn Fn() -> Result<(), DartError>>,
    ) -> Result<(), DartError> {
        body()
    }

    /// `runUnaryGuarded(f, arg)`.
    pub fn run_unary_guarded<A>(
        &self,
        body: std::rc::Rc<dyn Fn(A) -> Result<(), DartError>>,
        arg: A,
    ) -> Result<(), DartError> {
        body(arg)
    }

    pub fn run_unary<A, T>(
        &self,
        body: impl FnOnce(A) -> Result<T, DartError>,
        argument: A,
    ) -> Result<T, DartError> {
        body(argument)
    }

    pub fn register_callback<T>(
        &self,
        body: impl Fn() -> Result<T, DartError>,
    ) -> impl Fn() -> Result<T, DartError> {
        body
    }
}

/// The isolate's event loop: microtasks, then timers, the way Dart's runs.
///
/// This is the smallest thing that can honestly be called a scheduler. It is
/// here because the translated code *uses* `Timer` -- 37 places name it -- and
/// a type that records nothing would be a stub. What is not here is anybody
/// calling `run_until_idle`: a translated `main` would, and there is no
/// translated `main` yet. That gap is the loop's, not the timer's.
///
/// Dart's ordering is kept because programs depend on it: every microtask
/// drains before any timer runs, and a microtask queued by a microtask runs
/// before the timers too.
pub struct Scheduler {
    microtasks: std::collections::VecDeque<Box<dyn FnOnce() -> Result<(), DartError>>>,
    timers: Vec<Scheduled>,
    next_id: i64,
    /// Futures running on their own (`dart_spawn`): Dart's are eager, and
    /// a `Future(..)` nobody awaits still runs.
    /// Each spawned future with the name of what spawned it (`spawn_named`),
    /// so a run stuck on an await can say what it waits for.
    tasks: Vec<(
        &'static str,
        std::pin::Pin<std::boxed::Box<dyn std::future::Future<Output = ()>>>,
    )>,
}

/// Set by any waker the scheduler hands out: something a task or `main`
/// awaited has moved on, so another pass is worth making.
struct Woken(std::sync::atomic::AtomicBool);

impl std::task::Wake for Woken {
    fn wake(self: std::sync::Arc<Self>) {
        self.0.store(true, std::sync::atomic::Ordering::Relaxed);
    }
}

pub static WOKEN: std::sync::LazyLock<std::sync::Arc<Woken>> = std::sync::LazyLock::new(|| {
    std::sync::Arc::new(Woken(std::sync::atomic::AtomicBool::new(false)))
});

/// The scheduler's waker, and whether anything woke since it was last asked.
pub fn dart_waker() -> std::task::Waker {
    std::task::Waker::from(std::sync::Arc::clone(&*WOKEN))
}

pub fn dart_woken() -> bool {
    WOKEN.0.swap(false, std::sync::atomic::Ordering::Relaxed)
}

/// A Dart `Future<T>`: a shared handle on a result that arrives once, which
/// any number of holders may clone, store, and await (each awaiter gets a
/// clone of the result). A translated `async` function returns one, made
/// by `spawn`: its body runs on the scheduler from the next pass, whether
/// or not anything awaits it, as Dart's does.
pub struct DartFuture<T> {
    shared: std::rc::Rc<std::cell::RefCell<FutureState<T>>>,
}

struct FutureState<T> {
    result: Option<Result<T, DartError>>,
    wakers: Vec<std::task::Waker>,
    /// Where the future came from (`pending_labeled`), for a stuck run.
    label: &'static str,
}

thread_local! {
    /// Every future made, with a way to ask whether it is still pending
    /// (`None` once dropped): what a stuck run lists.
    static FUTURES: std::cell::RefCell<Vec<(&'static str, Box<dyn Fn() -> Option<bool>>)>> = std::cell::RefCell::new(Vec::new());
}

/// The futures still pending, by label; the dropped ones are forgotten.
pub fn pending_futures() -> Vec<String> {
    FUTURES.with(|f| {
        let mut f = f.borrow_mut();
        f.retain(|(_, probe)| probe().is_some());
        f.iter()
            .filter(|(_, probe)| probe() == Some(false))
            .map(|(label, _)| label.to_string())
            .collect()
    })
}

impl<T> Clone for DartFuture<T> {
    fn clone(&self) -> Self {
        DartFuture {
            shared: self.shared.clone(),
        }
    }
}

impl<T> std::fmt::Debug for DartFuture<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'Future'")
    }
}

/// By identity, as Dart's `==` on a future is.
impl<T> PartialEq for DartFuture<T> {
    fn eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(&self.shared, &other.shared)
    }
}

impl<T> DartNullable for DartFuture<T> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

impl<T: 'static> DartFuture<T> {
    /// A future nothing has resolved yet (a `Completer`'s).
    pub fn pending() -> Self {
        Self::pending_labeled("?")
    }

    /// `pending`, labeled with where it comes from, and registered so a
    /// run stuck on it can say so (`pending_futures`).
    pub fn pending_labeled(label: &'static str) -> Self
    where
        T: 'static,
    {
        let shared = std::rc::Rc::new(std::cell::RefCell::new(FutureState {
            result: None,
            wakers: Vec::new(),
            label,
        }));
        let weak = std::rc::Rc::downgrade(&shared);
        FUTURES.with(|f| {
            f.borrow_mut().push((
                label,
                Box::new(move || weak.upgrade().map(|s| s.borrow().result.is_some())),
            ))
        });
        DartFuture { shared }
    }

    /// `Future.value(v)` / `Future.error(e)`: already done.
    pub fn ready(result: Result<T, DartError>) -> Self {
        let future = DartFuture::pending();
        future.resolve(result);
        future
    }

    pub fn is_done(&self) -> bool {
        self.shared.borrow().result.is_some()
    }

    /// Resolves it, once, and wakes everything awaiting it.
    pub fn resolve(&self, result: Result<T, DartError>) {
        let wakers = {
            let mut state = self.shared.borrow_mut();
            if state.result.is_some() {
                panic!("a Future resolved twice");
            }
            state.result = Some(result);
            std::mem::take(&mut state.wakers)
        };
        for waker in wakers {
            waker.wake();
        }
    }

    /// Runs `future` on the scheduler and hands back the future of its
    /// result: Dart's futures are eager, and a `Future(..)` nobody awaits
    /// still runs.
    pub fn spawn(
        future: std::pin::Pin<
            std::boxed::Box<dyn std::future::Future<Output = Result<T, DartError>>>,
        >,
    ) -> Self
    where
        T: 'static,
    {
        Self::spawn_named("", future)
    }

    /// `spawn`, with the name of the function or closure whose body the
    /// future is: what `run_main` names when nothing will complete it.
    pub fn spawn_named(
        name: &'static str,
        future: std::pin::Pin<
            std::boxed::Box<dyn std::future::Future<Output = Result<T, DartError>>>,
        >,
    ) -> Self
    where
        T: 'static,
    {
        let out = DartFuture::pending_labeled(name);
        let done = out.clone();
        let mut future = future;
        (**SCHEDULER).borrow_mut().tasks.push((
            name,
            Box::pin(async move {
                let result = future.as_mut().await;
                done.resolve(result);
            }),
        ));
        out
    }

    /// The future of `f(value)`: a `Future<bool>` where a `Future<dynamic>`
    /// is expected, mapped by the coercion rule (`IrMapElements`).
    pub fn map<U: 'static>(&self, f: impl Fn(T) -> U + 'static) -> DartFuture<U>
    where
        T: Clone + 'static,
    {
        let me = self.clone();
        DartFuture::spawn_named("map", Box::pin(async move { Ok(f(me.await?)) }))
    }

    /// `future.whenComplete(action)`: the action runs when the future
    /// settles, and the settled value or error goes on unchanged. The
    /// action's own value is not awaited here (an `async` action is
    /// rare on the paths reached, `lockEvents`' is sync; run459).
    pub fn when_complete<R: 'static>(
        &self,
        action: std::rc::Rc<dyn Fn() -> Result<R, DartError>>,
    ) -> DartFuture<T>
    where
        T: Clone + 'static,
    {
        let me = self.clone();
        DartFuture::spawn_named(
            "whenComplete",
            Box::pin(async move {
                let settled = me.await;
                action()?;
                settled
            }),
        )
    }

    /// `future.catchError(onError, test: ..)`: the error goes to `onError`
    /// when `test` (absent means every error) admits it, with the stack
    /// the catch site has; the value goes on unchanged.
    pub fn catch_error(
        &self,
        on_error: std::rc::Rc<dyn Object>,
        test: Option<std::rc::Rc<dyn Fn(DartError) -> Result<bool, DartError>>>,
    ) -> DartFuture<T>
    where
        T: Clone + FromDynamic + 'static,
    {
        let me = self.clone();
        DartFuture::spawn_named(
            "catchError",
            Box::pin(async move {
                match me.await {
                    Ok(value) => Ok(value),
                    Err(error) => {
                        let admitted = match &test {
                            Some(test) => test(error.clone())?,
                            None => true,
                        };
                        if !admitted {
                            return Err(error);
                        }
                        match dart_call_error_handler::<T>(on_error, error)? {
                            FutureOr::Value(Some(value)) => Ok(value),
                            FutureOr::Value(None) => Err(std::rc::Rc::new(StateError::new(
                                "a FutureOr held no value".to_string(),
                            ))
                                as DartError),
                            FutureOr::Future(future) => future.await,
                        }
                    }
                }
            }),
        )
    }

    /// `future.then(onValue, onError: ..)`: the error goes to `onError` when
    /// there is one, and on through the returned future when there is not.
    /// `then(onValue, onError:)`: Dart's callback returns a `FutureOr<R>`,
    /// and a translated one returns that or an `R` outright
    /// (`IntoFutureOr`); a future it returns is awaited, as Dart chains
    /// it. The backend spells `R` at the call.
    pub fn then<R: Clone + FromDynamic + 'static, X: IntoFutureOr<R> + 'static>(
        &self,
        on_value: std::rc::Rc<dyn Fn(T) -> Result<X, DartError>>,
        on_error: Option<std::rc::Rc<dyn Object>>,
    ) -> DartFuture<R>
    where
        T: Clone + 'static,
    {
        let me = self.clone();
        DartFuture::spawn_named(
            "then",
            Box::pin(async move {
                let produced: Result<FutureOr<R>, DartError> = match me.await {
                    Ok(value) => on_value(value).map(|x| x.into_future_or()),
                    Err(error) => match on_error {
                        Some(handler) => dart_call_error_handler::<R>(handler, error),
                        None => Err(error),
                    },
                };
                match produced? {
                    FutureOr::Value(value) => match value {
                        Some(v) => Ok(v),
                        None => Err(std::rc::Rc::new(StateError::new(
                            "a FutureOr held no value".to_string(),
                        )) as DartError),
                    },
                    FutureOr::Future(future) => future.await,
                }
            }),
        )
    }
}

impl<T: Clone> std::future::Future for DartFuture<T> {
    type Output = Result<T, DartError>;

    fn poll(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Self::Output> {
        let mut state = self.shared.borrow_mut();
        match &state.result {
            Some(result) => std::task::Poll::Ready(result.clone()),
            None => {
                state.wakers.push(cx.waker().clone());
                std::task::Poll::Pending
            }
        }
    }
}

/// `x is Map` / `is List` / `is Set` on a value whose class is not known:
/// the prelude's collections are generic structs, told apart by the type
/// name their `runtime_type` carries (`Map`, `Vec`, `Set`, `VecDeque`).
pub fn dart_is_kind(value: &dyn Object, kinds: &[&str]) -> bool {
    let object: &dyn Object = match value.as_any().downcast_ref::<std::rc::Rc<dyn Object>>() {
        Some(handle) => handle.as_ref(),
        None => value,
    };
    let name = object.runtime_type().name;
    kinds.iter().any(|k| *k == name)
}

/// A future already done with `value`: what constructing a class that
/// implements `Future` (`SynchronousFuture(value)`) is here.
pub fn future_ready<T: 'static>(value: T) -> DartFuture<T> {
    DartFuture::ready(Ok(value))
}

/// `DartFuture::spawn`, as a function.
pub fn dart_spawn<T: 'static>(
    future: std::pin::Pin<std::boxed::Box<dyn std::future::Future<Output = Result<T, DartError>>>>,
) -> DartFuture<T> {
    DartFuture::spawn(future)
}

/// A future that completes when the timer fires.
pub fn timer_future(delay: Duration) -> DartFuture<()> {
    let future = DartFuture::pending();
    let done = future.clone();
    Timer::new(
        delay,
        std::rc::Rc::new(move || {
            done.resolve(Ok(()));
            Ok(())
        }),
    );
    future
}

/// `Future(computation)`: the computation runs on the scheduler's next pass.
pub fn future_new<T: Clone + 'static>(
    computation: std::rc::Rc<dyn Fn() -> Result<FutureOr<T>, DartError>>,
) -> DartFuture<T> {
    DartFuture::spawn(Box::pin(async move { computation()?.await }))
}

/// `Future.value([value])`: already done. The parameter is Dart's
/// `FutureOr<T>? value`, and what arrives is the `T` in an `Option` (the
/// front end coerces a plain value into the optional slot); no value is
/// the `null` of `T` -- `()` for a `Future<void>`.
/// The slot is Dart's `T?` as every declaration spells it -- the
/// projection `<T as DartNullable>::Or`, which a bare type parameter's
/// value reaches by `from_option` (`Future<T>.value(value)` in
/// `CachingAssetBundle.loadStructuredBinaryData<T>`, run569) and a
/// concrete type's is the plain `Option`.
pub fn future_value<T: DartNullable + 'static>(value: <T as DartNullable>::Or) -> DartFuture<T> {
    DartFuture::ready(Ok(T::option(value)
        .or_else(T::dart_null)
        .expect("Future.value() without a value on a non-nullable type")))
}

/// `Future<T>.value()` with no value: the `null` of `T` (`()` for a
/// `Future<void>`), with `T` inferred from where the future goes.
pub fn future_none<T: DartNullable + 'static>() -> DartFuture<T> {
    future_value::<T>(T::from_option(None))
}

/// `Future.microtask(computation)`: the same, one pass is a microtask here.
pub fn future_microtask<T: Clone + 'static>(
    computation: std::rc::Rc<dyn Fn() -> Result<FutureOr<T>, DartError>>,
) -> DartFuture<T> {
    future_new(computation)
}

/// `Future.sync(computation)`: the computation runs now; its value or its
/// future is the result.
pub fn future_sync<T: Clone + 'static>(
    computation: std::rc::Rc<dyn Fn() -> Result<FutureOr<T>, DartError>>,
) -> DartFuture<T> {
    match computation() {
        Ok(FutureOr::Value(value)) => DartFuture::ready(Ok(value.expect("FutureOr value"))),
        Ok(FutureOr::Future(future)) => future,
        Err(error) => DartFuture::ready(Err(error)),
    }
}

/// `Future.delayed(duration, [computation])`: after the timer, the
/// computation's result, or `null` when there is none.
pub fn future_delayed<T: DartNullable + Clone + 'static>(
    duration: Duration,
    computation: Option<std::rc::Rc<dyn Fn() -> Result<FutureOr<T>, DartError>>>,
) -> DartFuture<T> {
    DartFuture::spawn(Box::pin(async move {
        timer_future(duration).await?;
        match computation {
            Some(computation) => computation()?.await,
            None => Ok(T::dart_null()
                .expect("Future.delayed without a computation on a non-nullable type")),
        }
    }))
}

/// `Future.wait(futures)`: every result, in order.
pub fn future_wait<T: Clone + 'static>(futures: Vec<DartFuture<T>>) -> DartFuture<Vec<T>> {
    DartFuture::spawn(Box::pin(async move {
        let mut out = Vec::new();
        for future in futures {
            out.push(future.await?);
        }
        Ok(out)
    }))
}

/// Dart's `FutureOr<T>`: a `T`, or a `Future<T>`; awaitable either way.
#[derive(Clone)]
pub enum FutureOr<T> {
    Value(Option<T>),
    Future(DartFuture<T>),
}

/// What a `then` callback hands back: a `FutureOr<R>`, or the `R`
/// itself (the front end adapts a callback to the slot's `FutureOr` in
/// some shapes and not others).
pub trait IntoFutureOr<R> {
    fn into_future_or(self) -> FutureOr<R>;
}

impl<R> IntoFutureOr<R> for FutureOr<R> {
    fn into_future_or(self) -> FutureOr<R> {
        self
    }
}

impl<R> IntoFutureOr<R> for R {
    fn into_future_or(self) -> FutureOr<R> {
        FutureOr::Value(Some(self))
    }
}

/// The null a `FutureOr<R>?` callback hands back stands for: `R`'s own
/// null, which only a nullable, `void` or `dynamic` `R` has (the shapes
/// Dart admits a `FutureOr<R>?` for).
pub trait NullValue {
    fn null_value() -> Self;
}

impl NullValue for () {
    fn null_value() {}
}

impl<T> NullValue for Option<T> {
    fn null_value() -> Self {
        None
    }
}

impl NullValue for std::rc::Rc<dyn Object> {
    fn null_value() -> Self {
        std::rc::Rc::new(Null) as std::rc::Rc<dyn Object>
    }
}

/// `(_) { .. }` handed to `then`: a callback typed `FutureOr<void>?`
/// (`_initKeyboard`, ws484).
impl<R: NullValue> IntoFutureOr<R> for Option<FutureOr<R>> {
    fn into_future_or(self) -> FutureOr<R> {
        match self {
            Some(inner) => inner,
            None => FutureOr::Value(Some(R::null_value())),
        }
    }
}

impl<T> FutureOr<T> {
    pub fn value(value: T) -> Self {
        FutureOr::Value(Some(value))
    }
    pub fn future(future: DartFuture<T>) -> Self {
        FutureOr::Future(future)
    }
}

/// `FutureOr::value` / `FutureOr::future` with `T` spelled (a free
/// function takes the turbofish where an associated one would not): a
/// `then` callback's `FutureOr<Rc<dyn GalleryLocalizations>>` inferred as
/// the concrete `Rc<GalleryLocalizationsZu>` inside otherwise, and failed
/// the `IntoFutureOr<R>` bound (ws582).
pub fn future_or_value<T>(value: T) -> FutureOr<T> {
    FutureOr::Value(Some(value))
}

pub fn future_or_future<T>(future: DartFuture<T>) -> FutureOr<T> {
    FutureOr::Future(future)
}

impl<T> Unpin for FutureOr<T> {}

impl<T: Clone> std::future::Future for FutureOr<T> {
    type Output = Result<T, DartError>;
    fn poll(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Self::Output> {
        match self.get_mut() {
            FutureOr::Value(value) => {
                std::task::Poll::Ready(Ok(value.take().expect("FutureOr polled twice")))
            }
            FutureOr::Future(future) => std::pin::Pin::new(future).poll(cx),
        }
    }
}

impl<T> std::fmt::Debug for FutureOr<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'FutureOr'")
    }
}

impl<T> DartNullable for FutureOr<T> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

impl<T, E> DartNullable for Result<T, E> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

struct Scheduled {
    id: i64,
    due: std::time::Instant,
    period: Option<std::time::Duration>,
    callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>,
    active: bool,
}

pub static SCHEDULER: std::sync::LazyLock<Isolate<std::cell::RefCell<Scheduler>>> =
    std::sync::LazyLock::new(|| {
        Isolate(std::cell::RefCell::new(Scheduler {
            microtasks: std::collections::VecDeque::new(),
            tasks: Vec::new(),
            timers: Vec::new(),
            next_id: 1,
        }))
    });

/// Dart's `scheduleMicrotask`.
pub fn schedule_microtask(callback: Box<dyn FnOnce() -> Result<(), DartError>>) {
    (**SCHEDULER).borrow_mut().microtasks.push_back(callback);
}

/// Runs everything that is due, and returns when nothing is.
///
/// Does **not** sleep waiting for a timer that is not due yet: sleeping is a
/// policy the host decides, and a translated program has no host here.
/// `next_due` says when to come back.
/// Runs microtasks, spawned futures and due timers until none is ready;
/// whether anything ran at all (a caller polling a future of its own re-polls
/// it then, since the wake that resolving it sends is consumed in here).
pub fn run_until_idle() -> bool {
    let mut worked = false;
    loop {
        let task = (**SCHEDULER).borrow_mut().microtasks.pop_front();
        match task {
            Some(task) => {
                run_callback("a microtask", task);
                worked = true;
                continue;
            }
            None => {}
        }
        // The spawned futures, each polled once; another pass whenever one
        // of them woke something (a completer another awaits).
        let tasks = std::mem::take(&mut (**SCHEDULER).borrow_mut().tasks);
        if !tasks.is_empty() {
            dart_woken();
            let waker = dart_waker();
            let mut cx = std::task::Context::from_waker(&waker);
            let mut pending = Vec::new();
            let polled = tasks.len();
            for (name, mut task) in tasks {
                if task.as_mut().poll(&mut cx).is_pending() {
                    pending.push((name, task));
                }
            }
            // Polling is not progress: a task waiting on a completer no
            // one will complete stayed pending, this reported "worked",
            // and `run_main` spun on it for ever instead of reporting
            // what it was waiting on (run601's hang).
            if pending.len() < polled {
                worked = true;
            }
            // A task spawned *during* the pass (an `async` closure's body,
            // spawned when the closure ran) is polled in the next pass, not
            // left for a wake that nothing will send.
            let spawned = {
                let mut scheduler = (**SCHEDULER).borrow_mut();
                let spawned = !scheduler.tasks.is_empty();
                pending.append(&mut scheduler.tasks);
                scheduler.tasks = pending;
                spawned
            };
            if spawned || dart_woken() || !(**SCHEDULER).borrow().microtasks.is_empty() {
                continue;
            }
        }
        let now = std::time::Instant::now();
        let due: Vec<(i64, std::rc::Rc<dyn Fn() -> Result<(), DartError>>)> = {
            let scheduler = (**SCHEDULER).borrow();
            scheduler
                .timers
                .iter()
                .filter(|t| t.active && t.due <= now)
                .map(|t| (t.id, t.callback.clone()))
                .collect()
        };
        if due.is_empty() {
            return worked;
        }
        worked = true;
        for (id, callback) in due {
            // Rescheduled or dropped *before* the callback runs, so that a
            // callback cancelling its own timer wins over the reschedule.
            {
                let mut scheduler = (**SCHEDULER).borrow_mut();
                if let Some(timer) = scheduler.timers.iter_mut().find(|t| t.id == id) {
                    match timer.period {
                        Some(period) => timer.due = now + period,
                        None => timer.active = false,
                    }
                }
            }
            run_callback("a timer callback", || callback());
        }
    }
}

/// When the next timer comes due, for a host that wants to sleep until then.
/// Runs a translated `main` to completion: polls its future, runs the
/// microtasks and due timers between polls, and sleeps until the next
/// timer when nothing else can make progress. Returns when the future is
/// done and the scheduler is idle. A `main` that waits on something no
/// timer or microtask will ever complete -- the engine's frame callback,
/// with no engine here -- is reported and abandoned: that is the ruler's
/// reading, not an error.
pub fn run_main<F: std::future::Future<Output = Result<(), DartError>>>(main: F) {
    let mut main = std::pin::pin!(main);
    let waker = dart_waker();
    let mut cx = std::task::Context::from_waker(&waker);
    let mut done = false;
    // `DART2RUST_RUN_SECONDS=n`: a program that keeps a periodic timer
    // never becomes idle -- Flutter's does not exit either -- and the host
    // was killed from outside before it could report (run601). Past the
    // budget the loop stops and reports what kept it alive.
    let budget = std::env::var("DART2RUST_RUN_SECONDS")
        .ok()
        .and_then(|s| s.parse::<u64>().ok())
        .map(|s| std::time::Instant::now() + std::time::Duration::from_secs(s));
    loop {
        if let Some(deadline) = budget {
            if std::time::Instant::now() >= deadline {
                let timers = active_timers();
                eprintln!(
                    "dart2rust: run budget spent with main {}; {} timer(s) still active: {}",
                    if done { "done" } else { "pending" },
                    timers.len(),
                    timers.join(", ")
                );
                report_natives_skipped();
                return;
            }
        }
        if !done {
            match main.as_mut().poll(&mut cx) {
                std::task::Poll::Ready(Ok(())) => done = true,
                std::task::Poll::Ready(Err(error)) => {
                    eprintln!("dart2rust: main threw: {}", dart_error_text(&error));
                    return;
                }
                std::task::Poll::Pending => {}
            }
        }
        // Anything ran: `main` is polled again -- the wake that resolving
        // its future sent was consumed in there, and a `main` whose task
        // had just finished was reported as waiting (run470).
        if run_until_idle() || dart_woken() {
            continue;
        }
        match next_due() {
            Some(due) => {
                let now = std::time::Instant::now();
                let due = match budget {
                    Some(deadline) => due.min(deadline),
                    None => due,
                };
                if due > now {
                    std::thread::sleep(due - now);
                }
            }
            None => {
                if !done {
                    let waiting = pending_futures();
                    let completers = pending_completers();
                    eprintln!(
                        "dart2rust: main is waiting on something no timer or microtask will complete; {} future(s) still pending: {}; {} completer(s) never completed: {}",
                        waiting.len(),
                        waiting.join(", "),
                        completers.len(),
                        completers.join(", ")
                    );
                }
                report_natives_skipped();
                return;
            }
        }
    }
}

/// The timers still armed, each by its period (`every 16ms`) or its
/// remaining delay (`in 250ms`), for the budget report.
pub fn active_timers() -> Vec<String> {
    let now = std::time::Instant::now();
    (**SCHEDULER)
        .borrow()
        .timers
        .iter()
        .filter(|t| t.active)
        .map(|t| match t.period {
            Some(period) => format!("every {:?}", period),
            None => format!("in {:?}", t.due.saturating_duration_since(now)),
        })
        .collect()
}

/// The spawned futures not yet complete, by the name each was spawned
/// under (`DartFuture::spawn_named`); unnamed ones as `?`.
pub fn pending_tasks() -> Vec<String> {
    (**SCHEDULER)
        .borrow()
        .tasks
        .iter()
        .map(|(name, _)| {
            if name.is_empty() {
                "?".to_string()
            } else {
                name.to_string()
            }
        })
        .collect()
}

/// A thrown object as Dart's `toString` would print it: the prelude's
/// own error classes by their `Display` (`Bad state: ..`), a string as
/// itself, anything else as `Instance of 'X'`. `dyn Object`'s `Display`
/// cannot reach a concrete type's, so the prelude's errors are asked one
/// by one.
pub fn dart_error_text(error: &std::rc::Rc<dyn Object>) -> String {
    let object: &dyn Object = error.as_ref();
    let any = object.as_any();
    macro_rules! try_display {
        ($($t:ty),*) => {
            $(if let Some(e) = any.downcast_ref::<$t>() { return format!("{}", e); })*
        };
    }
    try_display!(
        StateError,
        ArgumentError,
        RangeError,
        AssertionError,
        UnsupportedError,
        UnimplementedError,
        ConcurrentModificationError,
        FormatException,
        Exception,
        Error,
        String
    );
    dart_message(error)
}

/// What a run without a native host left undone, for the ruler to read:
/// the void natives skipped, by symbol, each once.
fn report_natives_skipped() {
    let skipped = natives_skipped();
    if !skipped.is_empty() {
        eprintln!(
            "dart2rust: no native host; {} void native(s) skipped: {}",
            skipped.len(),
            skipped.join(", ")
        );
    }
    let unanswered = natives_unanswered();
    if !unanswered.is_empty() {
        eprintln!(
            "dart2rust: no native host; {} valued native(s) answered as absent: {}",
            unanswered.len(),
            unanswered.join(", ")
        );
    }
}

pub fn next_due() -> Option<std::time::Instant> {
    (**SCHEDULER)
        .borrow()
        .timers
        .iter()
        .filter(|t| t.active)
        .map(|t| t.due)
        .min()
}

/// Dart's `Timer`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Timer {
    id: i64,
}

impl Timer {
    pub fn new(delay: Duration, callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>) -> Self {
        Timer::schedule(delay, callback, None)
    }

    pub fn periodic(
        period: Duration,
        callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>,
    ) -> Self {
        Timer::schedule(period, callback, Some(period))
    }

    /// Dart's `Timer.run`: a callback on the next turn of the loop.
    pub fn run(callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>) -> Self {
        Timer::new(Duration::ZERO, callback)
    }

    fn schedule(
        delay: Duration,
        callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>,
        period: Option<Duration>,
    ) -> Self {
        let wait = std::time::Duration::from_micros(delay.microseconds.max(0) as u64);
        // `DART2RUST_TRACE_TIMERS=1`: every timer as it is armed.
        if std::env::var_os("DART2RUST_TRACE_TIMERS").is_some() {
            match period {
                Some(_) => eprintln!("dart2rust: timer every {:?}", wait),
                None => eprintln!("dart2rust: timer in {:?}", wait),
            }
        }
        let mut scheduler = (**SCHEDULER).borrow_mut();
        let id = scheduler.next_id;
        scheduler.next_id += 1;
        scheduler.timers.push(Scheduled {
            id,
            due: std::time::Instant::now() + wait,
            period: period.map(|p| std::time::Duration::from_micros(p.microseconds.max(0) as u64)),
            callback,
            active: true,
        });
        Timer { id }
    }

    pub fn cancel(&self) {
        let mut scheduler = (**SCHEDULER).borrow_mut();
        if let Some(timer) = scheduler.timers.iter_mut().find(|t| t.id == self.id) {
            timer.active = false;
        }
    }

    pub fn is_active(&self) -> bool {
        (**SCHEDULER)
            .borrow()
            .timers
            .iter()
            .any(|t| t.id == self.id && t.active)
    }
}

/// Dart's `Completer`: a future somebody else finishes.
///
/// Real, and correct against any executor. The value and the waker share one
/// cell; `complete` puts the value in and wakes whoever is waiting, and the
/// future takes the value when it is there. That is the whole of what a
/// completer is, and none of it needs a runtime -- which is why this one is
/// written out rather than left to the executor round.
///
/// `Rc`, not `Arc`: everything here belongs to one isolate. See `Isolate`.
pub struct Completer<T> {
    future: DartFuture<T>,
}

/// A completer prints as its kind and compares by identity: a struct holding
/// one (`SchedulerBinding._nextFrameCompleter`) derives both.
impl<T> std::fmt::Debug for Completer<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'Completer'")
    }
}

impl<T> PartialEq for Completer<T> {
    fn eq(&self, other: &Self) -> bool {
        self.future == other.future
    }
}

/// A `Completer` is a handle on its future: cloning shares.
impl<T> Clone for Completer<T> {
    fn clone(&self) -> Self {
        Completer {
            future: self.future.clone(),
        }
    }
}

impl<T: DartNullable + 'static> Default for Completer<T> {
    fn default() -> Self {
        Completer::new()
    }
}

thread_local! {
    /// Every completer made, by its maker's name, with a way to ask
    /// whether its future is done: what a stuck run reports.
    static COMPLETERS: std::cell::RefCell<Vec<(&'static str, Box<dyn Fn() -> bool>)>> = std::cell::RefCell::new(Vec::new());
}

/// The completers whose futures nobody completed, by maker.
pub fn pending_completers() -> Vec<String> {
    COMPLETERS.with(|c| {
        c.borrow()
            .iter()
            .filter(|(_, done)| !done())
            .map(|(name, _)| {
                if name.is_empty() {
                    "?".to_string()
                } else {
                    name.to_string()
                }
            })
            .collect()
    })
}

impl<T: DartNullable + 'static> Completer<T> {
    pub fn new() -> Self {
        Self::new_named("")
    }

    /// `Completer()`, recording who made it (`Class.member`).
    pub fn new_named(name: &'static str) -> Self {
        let future = DartFuture::pending_labeled(name);
        let probe = future.clone();
        COMPLETERS.with(|c| {
            c.borrow_mut()
                .push((name, Box::new(move || probe.is_done())))
        });
        Completer { future }
    }

    /// `completeError(error, [stackTrace])`: the future fails with it.
    pub fn complete_error(&self, error: std::rc::Rc<dyn Object>, _stack: Option<StackTrace>) {
        if self.future.is_done() {
            panic!("Completer completed twice");
        }
        self.future.resolve(Err(error));
    }

    /// Dart's `Completer.sync`, which completes its future synchronously
    /// rather than through a microtask; the same thing here.
    pub fn sync() -> Self {
        Completer::new()
    }

    /// `complete([value])`. The slot is Dart's `T?` as translated code
    /// spells it, `<T as DartNullable>::Or`: for a `Completer<ByteData?>`
    /// that is one `Option`, not two, and its `null` completes the future
    /// with `None`; a `Completer<void>` is completed with `Some(())`.
    pub fn complete(&self, value: <T as DartNullable>::Or) {
        if self.future.is_done() {
            panic!("Completer completed twice");
        }
        let value = T::option(value)
            .or_else(T::dart_null)
            .expect("Completer completed with null for a non-nullable type");
        self.future.resolve(Ok(value));
    }

    pub fn is_completed(&self) -> bool {
        self.future.is_done()
    }

    /// `future`: the same shared future every time.
    pub fn future(&self) -> DartFuture<T> {
        self.future.clone()
    }
}

/// A backtracking regular-expression engine for `RegExp`, written here
/// like everything else in this file: ECMAScript's common subset --
/// literals and escapes (`\d \w \s \b`, their negations), `.`, classes
/// with ranges and negation, `^`/`$` (multi-line aware), capturing,
/// non-capturing and named groups, alternation, and the quantifiers
/// `* + ? {m} {m,} {m,n}` greedy or lazy -- with `caseSensitive`,
/// `multiLine` and `dotAll` honoured. The gallery routes on
/// `^/demo/([\w-]+)$` (run631).
#[derive(Clone, Debug, PartialEq)]
enum ReNode {
    Char(char),
    Any,
    Class {
        items: Vec<ReClassItem>,
        negated: bool,
    },
    Start,
    End,
    WordBoundary(bool),
    Group {
        body: Box<ReNode>,
        index: Option<usize>,
    },
    Alt(Vec<Vec<ReNode>>),
    Repeat {
        body: Box<ReNode>,
        min: usize,
        max: Option<usize>,
        greedy: bool,
    },
}

#[derive(Clone, Debug, PartialEq)]
enum ReClassItem {
    Range(char, char),
    Digit(bool),
    Word(bool),
    Space(bool),
}

struct ReParser {
    chars: Vec<char>,
    pos: usize,
    groups: usize,
    names: Vec<(String, usize)>,
}

impl ReParser {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn parse_alt(&mut self) -> Result<ReNode, String> {
        let mut alternatives = vec![self.parse_seq()?];
        while self.peek() == Some('|') {
            self.pos += 1;
            alternatives.push(self.parse_seq()?);
        }
        Ok(ReNode::Alt(alternatives))
    }

    fn parse_seq(&mut self) -> Result<Vec<ReNode>, String> {
        let mut seq = Vec::new();
        while let Some(c) = self.peek() {
            if c == '|' || c == ')' {
                break;
            }
            let atom = self.parse_atom()?;
            let atom = self.parse_quantifier(atom)?;
            seq.push(atom);
        }
        Ok(seq)
    }

    fn parse_quantifier(&mut self, atom: ReNode) -> Result<ReNode, String> {
        let (min, max) = match self.peek() {
            Some('*') => {
                self.pos += 1;
                (0, None)
            }
            Some('+') => {
                self.pos += 1;
                (1, None)
            }
            Some('?') => {
                self.pos += 1;
                (0, Some(1))
            }
            Some('{') => {
                let save = self.pos;
                self.pos += 1;
                let mut min_text = String::new();
                while let Some(d) = self.peek().filter(|d| d.is_ascii_digit()) {
                    min_text.push(d);
                    self.pos += 1;
                }
                if min_text.is_empty() {
                    self.pos = save;
                    return Ok(atom);
                }
                let min: usize = min_text.parse().unwrap_or(0);
                let max = if self.peek() == Some(',') {
                    self.pos += 1;
                    let mut max_text = String::new();
                    while let Some(d) = self.peek().filter(|d| d.is_ascii_digit()) {
                        max_text.push(d);
                        self.pos += 1;
                    }
                    if max_text.is_empty() {
                        None
                    } else {
                        Some(max_text.parse().unwrap_or(0))
                    }
                } else {
                    Some(min)
                };
                if self.peek() != Some('}') {
                    self.pos = save;
                    return Ok(atom);
                }
                self.pos += 1;
                (min, max)
            }
            _ => return Ok(atom),
        };
        let greedy = if self.peek() == Some('?') {
            self.pos += 1;
            false
        } else {
            true
        };
        Ok(ReNode::Repeat {
            body: Box::new(atom),
            min,
            max,
            greedy,
        })
    }

    fn parse_atom(&mut self) -> Result<ReNode, String> {
        let c = self.peek().ok_or_else(|| "unexpected end".to_string())?;
        self.pos += 1;
        match c {
            '.' => Ok(ReNode::Any),
            '^' => Ok(ReNode::Start),
            '$' => Ok(ReNode::End),
            '(' => {
                let mut index = None;
                if self.peek() == Some('?') {
                    self.pos += 1;
                    match self.peek() {
                        Some(':') => {
                            self.pos += 1;
                        }
                        Some('<') => {
                            self.pos += 1;
                            let mut name = String::new();
                            while let Some(n) = self.peek() {
                                self.pos += 1;
                                if n == '>' {
                                    break;
                                }
                                name.push(n);
                            }
                            self.groups += 1;
                            index = Some(self.groups);
                            self.names.push((name, self.groups));
                        }
                        _ => return Err("unsupported group".to_string()),
                    }
                } else {
                    self.groups += 1;
                    index = Some(self.groups);
                }
                let body = self.parse_alt()?;
                if self.peek() != Some(')') {
                    return Err("missing )".to_string());
                }
                self.pos += 1;
                Ok(ReNode::Group {
                    body: Box::new(body),
                    index,
                })
            }
            '[' => self.parse_class(),
            '\\' => self.parse_escape(false),
            other => Ok(ReNode::Char(other)),
        }
    }

    fn parse_escape(&mut self, in_class: bool) -> Result<ReNode, String> {
        let e = self.peek().ok_or_else(|| "dangling escape".to_string())?;
        self.pos += 1;
        let item = match e {
            'd' => Some(ReClassItem::Digit(false)),
            'D' => Some(ReClassItem::Digit(true)),
            'w' => Some(ReClassItem::Word(false)),
            'W' => Some(ReClassItem::Word(true)),
            's' => Some(ReClassItem::Space(false)),
            'S' => Some(ReClassItem::Space(true)),
            _ => None,
        };
        if let Some(item) = item {
            return Ok(ReNode::Class {
                items: vec![item],
                negated: false,
            });
        }
        if !in_class {
            if e == 'b' {
                return Ok(ReNode::WordBoundary(false));
            }
            if e == 'B' {
                return Ok(ReNode::WordBoundary(true));
            }
        }
        Ok(ReNode::Char(match e {
            'n' => '\n',
            't' => '\t',
            'r' => '\r',
            'f' => '\u{c}',
            'v' => '\u{b}',
            '0' => '\0',
            'b' => '\u{8}',
            'u' => {
                let mut hex = String::new();
                for _ in 0..4 {
                    if let Some(h) = self.peek() {
                        hex.push(h);
                        self.pos += 1;
                    }
                }
                u32::from_str_radix(&hex, 16)
                    .ok()
                    .and_then(char::from_u32)
                    .unwrap_or('u')
            }
            'x' => {
                let mut hex = String::new();
                for _ in 0..2 {
                    if let Some(h) = self.peek() {
                        hex.push(h);
                        self.pos += 1;
                    }
                }
                u32::from_str_radix(&hex, 16)
                    .ok()
                    .and_then(char::from_u32)
                    .unwrap_or('x')
            }
            other => other,
        }))
    }

    fn parse_class(&mut self) -> Result<ReNode, String> {
        let mut negated = false;
        if self.peek() == Some('^') {
            negated = true;
            self.pos += 1;
        }
        let mut items = Vec::new();
        let mut first = true;
        loop {
            let c = self.peek().ok_or_else(|| "missing ]".to_string())?;
            if c == ']' && !first {
                self.pos += 1;
                break;
            }
            first = false;
            self.pos += 1;
            let low = if c == '\\' {
                match self.parse_escape(true)? {
                    ReNode::Class {
                        items: mut inner, ..
                    } => {
                        items.append(&mut inner);
                        continue;
                    }
                    ReNode::Char(ch) => ch,
                    _ => continue,
                }
            } else {
                c
            };
            if self.peek() == Some('-') && self.chars.get(self.pos + 1).map_or(false, |n| *n != ']')
            {
                self.pos += 1;
                let hc = self.peek().ok_or_else(|| "missing ]".to_string())?;
                self.pos += 1;
                let high = if hc == '\\' {
                    match self.parse_escape(true)? {
                        ReNode::Char(ch) => ch,
                        _ => hc,
                    }
                } else {
                    hc
                };
                items.push(ReClassItem::Range(low, high));
            } else {
                items.push(ReClassItem::Range(low, low));
            }
        }
        Ok(ReNode::Class { items, negated })
    }
}

fn re_is_word(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

struct ReMatcher<'a> {
    input: &'a [char],
    caps: Vec<Option<(usize, usize)>>,
    case_insensitive: bool,
    multi_line: bool,
    dot_all: bool,
}

impl<'a> ReMatcher<'a> {
    fn chars_equal(&self, a: char, b: char) -> bool {
        if a == b {
            return true;
        }
        self.case_insensitive && a.to_lowercase().eq(b.to_lowercase())
    }

    fn class_holds(&self, items: &[ReClassItem], negated: bool, c: char) -> bool {
        let mut hit = false;
        for item in items {
            let holds = match item {
                ReClassItem::Range(lo, hi) => {
                    (*lo <= c && c <= *hi)
                        || (self.case_insensitive && {
                            let l = c.to_lowercase().next().unwrap_or(c);
                            let u = c.to_uppercase().next().unwrap_or(c);
                            (*lo <= l && l <= *hi) || (*lo <= u && u <= *hi)
                        })
                }
                ReClassItem::Digit(neg) => c.is_ascii_digit() != *neg,
                ReClassItem::Word(neg) => re_is_word(c) != *neg,
                ReClassItem::Space(neg) => c.is_whitespace() != *neg,
            };
            if holds {
                hit = true;
                break;
            }
        }
        hit != negated
    }

    fn m_seq(
        &mut self,
        seq: &[ReNode],
        idx: usize,
        pos: usize,
        cont: &mut dyn FnMut(&mut Self, usize) -> bool,
    ) -> bool {
        if idx == seq.len() {
            return cont(self, pos);
        }
        let node = &seq[idx];
        self.m(node, pos, &mut |s: &mut Self, p: usize| {
            s.m_seq(seq, idx + 1, p, cont)
        })
    }

    fn m(
        &mut self,
        node: &ReNode,
        pos: usize,
        cont: &mut dyn FnMut(&mut Self, usize) -> bool,
    ) -> bool {
        match node {
            ReNode::Char(c) => {
                if pos < self.input.len() && self.chars_equal(self.input[pos], *c) {
                    cont(self, pos + 1)
                } else {
                    false
                }
            }
            ReNode::Any => {
                if pos < self.input.len() && (self.dot_all || self.input[pos] != '\n') {
                    cont(self, pos + 1)
                } else {
                    false
                }
            }
            ReNode::Class { items, negated } => {
                if pos < self.input.len() && self.class_holds(items, *negated, self.input[pos]) {
                    cont(self, pos + 1)
                } else {
                    false
                }
            }
            ReNode::Start => {
                if pos == 0 || (self.multi_line && self.input[pos - 1] == '\n') {
                    cont(self, pos)
                } else {
                    false
                }
            }
            ReNode::End => {
                if pos == self.input.len() || (self.multi_line && self.input[pos] == '\n') {
                    cont(self, pos)
                } else {
                    false
                }
            }
            ReNode::WordBoundary(negated) => {
                let before = pos > 0 && re_is_word(self.input[pos - 1]);
                let after = pos < self.input.len() && re_is_word(self.input[pos]);
                if (before != after) != *negated {
                    cont(self, pos)
                } else {
                    false
                }
            }
            ReNode::Group { body, index } => {
                let index = *index;
                self.m(body, pos, &mut |s: &mut Self, p: usize| match index {
                    Some(i) => {
                        let previous = s.caps[i];
                        s.caps[i] = Some((pos, p));
                        if cont(s, p) {
                            true
                        } else {
                            s.caps[i] = previous;
                            false
                        }
                    }
                    None => cont(s, p),
                })
            }
            ReNode::Alt(alternatives) => {
                for alternative in alternatives {
                    if self.m_seq(alternative, 0, pos, cont) {
                        return true;
                    }
                }
                false
            }
            ReNode::Repeat {
                body,
                min,
                max,
                greedy,
            } => self.m_rep(body, *min, *max, *greedy, 0, pos, cont),
        }
    }

    fn m_rep(
        &mut self,
        body: &ReNode,
        min: usize,
        max: Option<usize>,
        greedy: bool,
        count: usize,
        pos: usize,
        cont: &mut dyn FnMut(&mut Self, usize) -> bool,
    ) -> bool {
        if count < min {
            return self.m(body, pos, &mut |s: &mut Self, p: usize| {
                // An empty iteration satisfies the minimum without moving.
                if p == pos && count + 1 < min {
                    s.m_rep(body, min, max, greedy, min, p, cont)
                } else {
                    s.m_rep(body, min, max, greedy, count + 1, p, cont)
                }
            });
        }
        let can_more = max.map_or(true, |m| count < m);
        if greedy {
            if can_more
                && self.m(body, pos, &mut |s: &mut Self, p: usize| {
                    // An empty iteration past the minimum cannot repeat for ever.
                    p != pos && s.m_rep(body, min, max, greedy, count + 1, p, cont)
                })
            {
                return true;
            }
            cont(self, pos)
        } else {
            if cont(self, pos) {
                return true;
            }
            can_more
                && self.m(body, pos, &mut |s: &mut Self, p: usize| {
                    p != pos && s.m_rep(body, min, max, greedy, count + 1, p, cont)
                })
        }
    }
}

/// Dart's `RegExp`: the pattern, its flags, and the program parsed from
/// it (once, lazily; a pattern that does not parse matches nothing and
/// says so on `stderr` once).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct RegExp {
    pub pattern: String,
    pub is_multi_line: bool,
    pub is_case_sensitive: bool,
    pub is_dot_all: bool,
}

impl RegExp {
    /// `RegExp(source, {multiLine, caseSensitive, unicode, dotAll})`.
    pub fn new(
        pattern: String,
        multi_line: bool,
        case_sensitive: bool,
        _unicode: bool,
        dot_all: bool,
    ) -> Self {
        RegExp {
            pattern,
            is_multi_line: multi_line,
            is_case_sensitive: case_sensitive,
            is_dot_all: dot_all,
        }
    }

    fn program(&self) -> Option<Vec<ReNode>> {
        let mut parser = ReParser {
            chars: self.pattern.chars().collect(),
            pos: 0,
            groups: 0,
            names: Vec::new(),
        };
        match parser.parse_alt() {
            Ok(node) if parser.pos == parser.chars.len() => Some(vec![node]),
            Ok(_) => {
                eprintln!("dart2rust: RegExp `{}`: unexpected `)`", self.pattern);
                None
            }
            Err(e) => {
                eprintln!("dart2rust: RegExp `{}`: {}", self.pattern, e);
                None
            }
        }
    }

    fn group_names(&self) -> (usize, Vec<(String, usize)>) {
        let mut parser = ReParser {
            chars: self.pattern.chars().collect(),
            pos: 0,
            groups: 0,
            names: Vec::new(),
        };
        let _ = parser.parse_alt();
        (parser.groups, parser.names)
    }

    fn match_from(&self, chars: &[char], input: &str, from: usize) -> Option<RegExpMatch> {
        let program = self.program()?;
        let (groups, names) = self.group_names();
        let mut matcher = ReMatcher {
            input: chars,
            caps: vec![None; groups + 1],
            case_insensitive: !self.is_case_sensitive,
            multi_line: self.is_multi_line,
            dot_all: self.is_dot_all,
        };
        for start in from..=chars.len() {
            for c in matcher.caps.iter_mut() {
                *c = None;
            }
            let mut end = None;
            if matcher.m_seq(&program, 0, start, &mut |_, p| {
                end = Some(p);
                true
            }) {
                let end = end.unwrap_or(start);
                let mut caps = matcher.caps.clone();
                caps[0] = Some((start, end));
                return Some(RegExpMatch {
                    input: input.to_string(),
                    start: start as i64,
                    end: end as i64,
                    groups: caps
                        .into_iter()
                        .map(|c| c.map(|(s, e)| (s as i64, e as i64)))
                        .collect(),
                    names: names.clone(),
                });
            }
        }
        None
    }

    /// `firstMatch(input)`.
    pub fn first_match(&self, input: String) -> Option<RegExpMatch> {
        let chars: Vec<char> = input.chars().collect();
        self.match_from(&chars, &input, 0)
    }

    /// `matchAsPrefix(input, [start])`: a match that begins exactly at `start`.
    pub fn match_as_prefix(&self, input: String, start: i64) -> Option<RegExpMatch> {
        let chars: Vec<char> = input.chars().collect();
        let program = self.program()?;
        let (groups, names) = self.group_names();
        let mut matcher = ReMatcher {
            input: &chars,
            caps: vec![None; groups + 1],
            case_insensitive: !self.is_case_sensitive,
            multi_line: self.is_multi_line,
            dot_all: self.is_dot_all,
        };
        let from = start.max(0) as usize;
        if from > chars.len() {
            return None;
        }
        let mut end = None;
        if matcher.m_seq(&program, 0, from, &mut |_, p| {
            end = Some(p);
            true
        }) {
            let end = end.unwrap_or(from);
            let mut caps = matcher.caps.clone();
            caps[0] = Some((from, end));
            return Some(RegExpMatch {
                input,
                start: from as i64,
                end: end as i64,
                groups: caps
                    .into_iter()
                    .map(|c| c.map(|(s, e)| (s as i64, e as i64)))
                    .collect(),
                names,
            });
        }
        None
    }

    pub fn has_match(&self, input: String) -> bool {
        self.first_match(input).is_some()
    }

    /// `stringMatch(input)`: the first match's text.
    pub fn string_match(&self, input: String) -> Option<String> {
        self.first_match(input)
            .map(|m| m.group(0).unwrap_or_default())
    }

    /// `allMatches(input, [start])`: every non-overlapping match, an empty
    /// one stepping forward by one.
    pub fn all_matches(&self, input: String, start: i64) -> Vec<RegExpMatch> {
        let chars: Vec<char> = input.chars().collect();
        let mut out = Vec::new();
        let mut from = start.max(0) as usize;
        while from <= chars.len() {
            match self.match_from(&chars, &input, from) {
                Some(m) => {
                    let (s, e) = (m.start as usize, m.end as usize);
                    out.push(m);
                    from = if e == s { e + 1 } else { e };
                }
                None => break,
            }
        }
        out
    }

    /// `RegExp.escape(text)`: every metacharacter backslashed.
    pub fn escape(text: String) -> String {
        let mut out = String::new();
        for c in text.chars() {
            if "\\^$.|?*+()[]{}/".contains(c) {
                out.push('\\');
            }
            out.push(c);
        }
        out
    }
}

/// Dart's `RegExpMatch`: the input, the whole match's span, and each
/// group's, in *character* offsets (as the rest of this file counts).
#[derive(Clone, Debug, PartialEq)]
pub struct RegExpMatch {
    pub input: String,
    pub start: i64,
    pub end: i64,
    pub groups: Vec<Option<(i64, i64)>>,
    pub names: Vec<(String, usize)>,
}

impl RegExpMatch {
    fn slice(&self, span: Option<(i64, i64)>) -> Option<String> {
        let (s, e) = span?;
        Some(
            self.input
                .chars()
                .skip(s as usize)
                .take((e - s).max(0) as usize)
                .collect(),
        )
    }

    /// `group(index)` / `match[index]`: the group's text, null when it
    /// did not take part.
    pub fn group(&self, index: i64) -> Option<String> {
        self.slice(self.groups.get(index.max(0) as usize).copied().flatten())
    }

    pub fn index_get(&self, index: i64) -> Option<String> {
        self.group(index)
    }

    /// `match[index]`, as the backend spells `[]` on a translated class.
    pub fn index_of(&self, index: i64) -> Option<String> {
        self.group(index)
    }

    /// `groups(indices)`.
    pub fn groups(&self, indices: Vec<i64>) -> Vec<Option<String>> {
        indices.into_iter().map(|i| self.group(i)).collect()
    }

    /// `groupCount`: the capturing groups, not counting the whole.
    pub fn group_count(&self) -> i64 {
        (self.groups.len() as i64 - 1).max(0)
    }

    /// `namedGroup(name)`.
    pub fn named_group(&self, name: String) -> Option<String> {
        let index = self
            .names
            .iter()
            .find(|(n, _)| *n == name)
            .map(|(_, i)| *i)?;
        self.group(index as i64)
    }

    pub fn group_names(&self) -> Vec<String> {
        self.names.iter().map(|(n, _)| n.clone()).collect()
    }

    pub fn start(&self) -> i64 {
        self.start
    }

    pub fn end(&self) -> i64 {
        self.end
    }

    pub fn input(&self) -> String {
        self.input.clone()
    }
}

/// Dart's error and exception classes.
///
/// One shape for all of them: a message, and a `Display` that prints what Dart
/// prints. They are thrown and caught by *type* upstream, and the `Result<T,
/// E>` the backend emits carries the type, so nothing else about them is
/// reached.
macro_rules! dart_error {
    ($name:ident, $prefix:literal) => {
        #[derive(Clone, Debug, Default, PartialEq, Eq)]
        pub struct $name {
            pub message: String,
        }

        impl $name {
            pub fn new(message: String) -> Self {
                $name { message }
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                if self.message.is_empty() {
                    f.write_str($prefix)
                } else {
                    write!(f, "{}: {}", $prefix, self.message)
                }
            }
        }

        impl DartEq for $name {
            fn dart_eq(&self, other: &Self) -> bool {
                self == other
            }
        }
    };
}

/// `Exception([dynamic message])`: the message as translated code spells a
/// `dynamic`, printed as Dart's `toString` would.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Exception {
    pub message: String,
}

impl Exception {
    pub fn new(message: std::rc::Rc<dyn Object>) -> Self {
        Exception {
            message: dart_message(&message),
        }
    }
}

impl fmt::Display for Exception {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.message.is_empty() {
            f.write_str("Exception")
        } else {
            write!(f, "Exception: {}", self.message)
        }
    }
}

/// A `dynamic message` as `Exception.toString` prints it: nothing for null,
/// a string as itself, anything else by its own text.
pub fn dart_message(message: &std::rc::Rc<dyn Object>) -> String {
    let object: &dyn Object = message.as_ref();
    if object.as_any().is::<Null>() {
        return String::new();
    }
    match object.as_any().downcast_ref::<String>() {
        Some(text) => text.clone(),
        None => format!("{}", object),
    }
}
dart_error!(StateError, "Bad state");
dart_error!(Error, "Error");

/// `String.fromCharCodes(codes)`: UTF-16 code units to a String.
pub fn string_from_char_codes(codes: Vec<i64>) -> String {
    let units: Vec<u16> = codes.iter().map(|c| *c as u16).collect();
    String::from_utf16_lossy(&units)
}

/// `Object()`: a fresh object with nothing but an identity -- `final
/// _clockKey = Object();` uses one as a zone key.
pub fn new_object() -> std::rc::Rc<dyn Object> {
    std::rc::Rc::new(())
}

/// `dart:io`'s `Platform` statics, as functions: a static getter upstream is
/// a call here (see the backend's `_staticRead`).
/// `dart:developer`'s `log(message, {time, sequenceNumber, level, name,
/// zone, error, stackTrace})`, the named ones filled in by the front end in
/// declaration order. Printed to stderr, which is where a developer log
/// goes without an observatory.
pub fn log(
    message: String,
    _time: Option<DateTime>,
    _sequence_number: Option<i64>,
    _level: i64,
    name: String,
    _zone: Option<Zone>,
    error: Option<std::rc::Rc<dyn Object>>,
    _stack_trace: Option<StackTrace>,
) {
    if name.is_empty() {
        eprintln!("{}", message);
    } else {
        eprintln!("[{}] {}", name, message);
    }
    if let Some(e) = error {
        eprintln!("  error: {:?}", e);
    }
}

/// `Uint8List.view(buffer, [offsetInBytes, length])`: a window copied out
/// of the bytes (a buffer here is the bytes themselves).
pub fn uint8_list_view(buffer: Vec<u8>, offset: i64, length: Option<i64>) -> Vec<u8> {
    let start = (offset.max(0) as usize).min(buffer.len());
    let end = match length {
        Some(n) => (start + n.max(0) as usize).min(buffer.len()),
        None => buffer.len(),
    };
    buffer[start..end].to_vec()
}

/// `TypedData.buffer` and its sizes on a typed list, which is a `Vec` of
/// its element here: the bytes of the elements, little-endian, as the
/// platform's are (`WriteBuffer.putFloat64List`, run505). A `List<int>`
/// behind a `Uint8List` holds one byte per element.
pub trait DartTypedList {
    fn buffer(&self) -> Vec<u8>;
    fn element_size_in_bytes(&self) -> i64;
    fn offset_in_bytes(&self) -> i64 {
        0
    }
    fn length_in_bytes(&self) -> i64 {
        self.buffer().len() as i64
    }
}

impl DartTypedList for Vec<i64> {
    fn buffer(&self) -> Vec<u8> {
        self.iter().map(|v| *v as u8).collect()
    }
    fn element_size_in_bytes(&self) -> i64 {
        1
    }
}

impl DartTypedList for Vec<u8> {
    fn buffer(&self) -> Vec<u8> {
        self.clone()
    }
    fn element_size_in_bytes(&self) -> i64 {
        1
    }
}

macro_rules! dart_typed_list {
    ($($t:ty => $width:expr),* $(,)?) => {
        $(
            impl DartTypedList for Vec<$t> {
                fn buffer(&self) -> Vec<u8> {
                    self.iter().flat_map(|v| v.to_le_bytes()).collect()
                }
                fn element_size_in_bytes(&self) -> i64 {
                    $width
                }
            }
        )*
    };
}
dart_typed_list!(i8 => 1, i16 => 2, u16 => 2, i32 => 4, u32 => 4, u64 => 8, f32 => 4, f64 => 8);

/// `ByteBuffer.asUint8List(offset, length)` and its siblings on the bytes
/// a buffer is here: windows copied out, in the element width asked for.
pub trait DartByteBuffer {
    fn as_uint8_list(&self, offset: i64, length: Option<i64>) -> Vec<u8>;
    fn as_int8_list(&self, offset: i64, length: Option<i64>) -> Vec<i8>;
    fn as_byte_data(&self, offset: i64, length: Option<i64>) -> ByteData;
    fn as_int32_list(&self, offset: i64, length: Option<i64>) -> Vec<i32>;
    fn as_float32_list(&self, offset: i64, length: Option<i64>) -> Vec<f32>;
    fn as_float64_list(&self, offset: i64, length: Option<i64>) -> Vec<f64>;
    fn as_int64_list(&self, offset: i64, length: Option<i64>) -> Vec<i64>;
    fn as_uint64_list(&self, offset: i64, length: Option<i64>) -> Vec<u64>;
    fn as_int16_list(&self, offset: i64, length: Option<i64>) -> Vec<i16>;
    fn as_uint16_list(&self, offset: i64, length: Option<i64>) -> Vec<u16>;
    fn as_uint32_list(&self, offset: i64, length: Option<i64>) -> Vec<u32>;
}

fn byte_window(bytes: &[u8], offset: i64, length: Option<i64>, width: usize) -> &[u8] {
    let start = (offset.max(0) as usize).min(bytes.len());
    let end = match length {
        Some(n) => (start + n.max(0) as usize * width).min(bytes.len()),
        None => bytes.len(),
    };
    &bytes[start..end]
}

impl DartByteBuffer for Vec<u8> {
    fn as_uint8_list(&self, offset: i64, length: Option<i64>) -> Vec<u8> {
        byte_window(self, offset, length, 1).to_vec()
    }

    fn as_int8_list(&self, offset: i64, length: Option<i64>) -> Vec<i8> {
        byte_window(self, offset, length, 1)
            .iter()
            .map(|b| *b as i8)
            .collect()
    }

    fn as_byte_data(&self, offset: i64, length: Option<i64>) -> ByteData {
        ByteData {
            bytes: byte_window(self, offset, length, 1).to_vec(),
        }
    }

    fn as_int32_list(&self, offset: i64, length: Option<i64>) -> Vec<i32> {
        byte_window(self, offset, length, 4)
            .chunks_exact(4)
            .map(|c| i32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect()
    }

    fn as_float32_list(&self, offset: i64, length: Option<i64>) -> Vec<f32> {
        byte_window(self, offset, length, 4)
            .chunks_exact(4)
            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect()
    }

    fn as_float64_list(&self, offset: i64, length: Option<i64>) -> Vec<f64> {
        byte_window(self, offset, length, 8)
            .chunks_exact(8)
            .map(|c| f64::from_le_bytes([c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7]]))
            .collect()
    }
    fn as_int64_list(&self, offset: i64, length: Option<i64>) -> Vec<i64> {
        byte_window(self, offset, length, 8)
            .chunks_exact(8)
            .map(|c| i64::from_le_bytes([c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7]]))
            .collect()
    }
    fn as_uint64_list(&self, offset: i64, length: Option<i64>) -> Vec<u64> {
        byte_window(self, offset, length, 8)
            .chunks_exact(8)
            .map(|c| u64::from_le_bytes([c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7]]))
            .collect()
    }
    fn as_int16_list(&self, offset: i64, length: Option<i64>) -> Vec<i16> {
        byte_window(self, offset, length, 2)
            .chunks_exact(2)
            .map(|c| i16::from_le_bytes([c[0], c[1]]))
            .collect()
    }
    fn as_uint16_list(&self, offset: i64, length: Option<i64>) -> Vec<u16> {
        byte_window(self, offset, length, 2)
            .chunks_exact(2)
            .map(|c| u16::from_le_bytes([c[0], c[1]]))
            .collect()
    }
    fn as_uint32_list(&self, offset: i64, length: Option<i64>) -> Vec<u32> {
        byte_window(self, offset, length, 4)
            .chunks_exact(4)
            .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect()
    }
}

/// `utf8.decoder`.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Utf8Decoder;

impl Utf8Decoder {
    /// `convert(codeUnits, [start, end])`.
    pub fn convert(
        &self,
        code_units: Vec<i64>,
        start: i64,
        end: Option<i64>,
    ) -> Result<String, DartError> {
        let s = (start.max(0) as usize).min(code_units.len());
        let e = end
            .map(|n| (n.max(0) as usize).min(code_units.len()))
            .unwrap_or(code_units.len());
        Ok(Utf8Codec.decode(code_units[s..e].to_vec(), Some(true)))
    }

    /// `utf8.decoder.fuse(other)`: the two conversions in a row.
    pub fn fuse<U: 'static>(&self, next: Converter<String, U>) -> Converter<Vec<i64>, U> {
        Converter::new(std::rc::Rc::new(move |bytes: Vec<i64>| {
            next.convert(Utf8Decoder.convert(bytes, 0, None)?)
        }))
    }
}

/// `dart:convert`'s `Converter<S, T>`, as a value: what a `fuse` makes, and
/// what a codec's `encoder`/`decoder` are. It holds the conversion.
pub struct Converter<S, T> {
    convert: std::rc::Rc<dyn Fn(S) -> Result<T, DartError>>,
}

impl<S, T> Clone for Converter<S, T> {
    fn clone(&self) -> Self {
        Converter {
            convert: self.convert.clone(),
        }
    }
}

impl<S, T> std::fmt::Debug for Converter<S, T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'Converter'")
    }
}

impl<S, T> PartialEq for Converter<S, T> {
    fn eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(&self.convert, &other.convert)
    }
}

impl<S, T> DartNullable for Converter<S, T> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

impl<S: 'static, T: 'static> Converter<S, T> {
    pub fn new(convert: std::rc::Rc<dyn Fn(S) -> Result<T, DartError>>) -> Self {
        Converter { convert }
    }

    /// `convert(input)`.
    pub fn convert(&self, input: S) -> Result<T, DartError> {
        (self.convert)(input)
    }

    /// `fuse(other)`: this conversion, then the other's.
    pub fn fuse<U: 'static>(&self, next: Converter<T, U>) -> Converter<S, U> {
        let first = self.clone();
        Converter::new(std::rc::Rc::new(move |input: S| {
            next.convert(first.convert(input)?)
        }))
    }
}

