/// `dart:convert`'s `json`, a `const JsonCodec()`. `encode` writes the
/// JSON of what a translated `dynamic` holds -- a string, a number, a bool,
/// `null`, a `Map<String, dynamic>`, a `List<dynamic>` -- and refuses,
/// loudly, anything else; `decode` is not written yet.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct JsonCodec;

impl JsonCodec {
    /// `json.encode(value, toEncodable: ..)`: the callback for a value the
    /// encoder does not know is Dart's declaration, not used here.
    /// `json.encode(value, toEncodable: ..)`: the slot is `Object?`, and a
    /// prelude callee's arguments are not adapted by the front end, so it
    /// takes whatever value the caller has (a `Map<String, Rc<dyn Object>>`
    /// as itself, a `dynamic` as its handle: the blanket `Object`'s
    /// `as_any` looks through a handle, ws481).
    pub fn encode<V: 'static>(
        &self,
        value: V,
        _to_encodable: Option<
            std::rc::Rc<
                dyn Fn(
                    Option<std::rc::Rc<dyn Object>>,
                ) -> Result<Option<std::rc::Rc<dyn Object>>, DartError>,
            >,
        >,
    ) -> String {
        let value: std::rc::Rc<dyn Object> = std::rc::Rc::new(value);
        let mut out = String::new();
        json_write(&mut out, &value);
        out
    }

    /// `json.decode(source, reviver: ..)`: what a translated `dynamic`
    /// holds -- a `String`, an `i64` or `f64`, a `bool`, `Null`, a
    /// `Map<String, Rc<dyn Object>>`, a `Vec<Rc<dyn Object>>`. Malformed
    /// text is Dart's `FormatException`, which the signature (no
    /// `Result`: the call is not a failing one to the front end) can only
    /// panic with.
    pub fn decode(&self, source: String, reviver: Option<JsonReviver>) -> std::rc::Rc<dyn Object> {
        let mut parser = JsonParser {
            text: source.as_bytes(),
            at: 0,
            reviver,
        };
        parser.skip_space();
        let value = parser.value();
        parser.skip_space();
        if parser.at != parser.text.len() {
            parser.fail("Unexpected trailing text");
        }
        parser.revive(None, value)
    }

    /// `json.decoder`: a `Converter<String, Object?>` -- and `Object?` is a
    /// `dynamic` here, whose null is the `Null` object.
    pub fn decoder(&self) -> Converter<String, std::rc::Rc<dyn Object>> {
        Converter::new(std::rc::Rc::new(|source: String| {
            Ok(JsonCodec.decode(source, None))
        }))
    }

    /// `json.encoder`: a `Converter<Object?, String>`.
    pub fn encoder(&self) -> Converter<std::rc::Rc<dyn Object>, String> {
        Converter::new(std::rc::Rc::new(|value: std::rc::Rc<dyn Object>| {
            Ok(JsonCodec.encode(value, None))
        }))
    }
}

/// `Object? reviver(Object? key, Object? value)`, as translated code spells it.
/// `dart:convert`'s top-level `jsonDecode(source, {reviver})`: the codec's
/// (`flutter_localized_locales`' `_loadJSON`, run599).
pub fn json_decode(source: String, reviver: Option<JsonReviver>) -> std::rc::Rc<dyn Object> {
    JsonCodec.decode(source, reviver)
}

pub type JsonReviver = std::rc::Rc<
    dyn Fn(
        Option<std::rc::Rc<dyn Object>>,
        Option<std::rc::Rc<dyn Object>>,
    ) -> Result<Option<std::rc::Rc<dyn Object>>, DartError>,
>;

struct JsonParser<'a> {
    text: &'a [u8],
    at: usize,
    reviver: Option<JsonReviver>,
}

impl<'a> JsonParser<'a> {
    fn fail(&self, what: &str) -> ! {
        panic!(
            "uncaught Dart exception: FormatException: {} (at character {})",
            what,
            self.at + 1
        )
    }

    fn peek(&self) -> Option<u8> {
        self.text.get(self.at).copied()
    }

    fn skip_space(&mut self) {
        while matches!(self.peek(), Some(b' ' | b'\t' | b'\n' | b'\r')) {
            self.at += 1;
        }
    }

    fn expect(&mut self, literal: &str) {
        if self.text[self.at..].starts_with(literal.as_bytes()) {
            self.at += literal.len();
        } else {
            self.fail(&format!("Expected '{}'", literal));
        }
    }

    /// The reviver's say on one decoded value, if there is one.
    fn revive(
        &self,
        key: Option<std::rc::Rc<dyn Object>>,
        value: std::rc::Rc<dyn Object>,
    ) -> std::rc::Rc<dyn Object> {
        match &self.reviver {
            None => value,
            Some(reviver) => match reviver(key, dart_nullable(value)) {
                Ok(revived) => {
                    revived.unwrap_or_else(|| std::rc::Rc::new(Null) as std::rc::Rc<dyn Object>)
                }
                Err(error) => panic!(
                    "uncaught Dart exception in a JSON reviver: {}",
                    dart_error_text(&error)
                ),
            },
        }
    }

    fn value(&mut self) -> std::rc::Rc<dyn Object> {
        match self.peek() {
            Some(b'{') => self.object(),
            Some(b'[') => self.array(),
            Some(b'"') => std::rc::Rc::new(self.string()) as std::rc::Rc<dyn Object>,
            Some(b't') => {
                self.expect("true");
                std::rc::Rc::new(true) as std::rc::Rc<dyn Object>
            }
            Some(b'f') => {
                self.expect("false");
                std::rc::Rc::new(false) as std::rc::Rc<dyn Object>
            }
            Some(b'n') => {
                self.expect("null");
                std::rc::Rc::new(Null) as std::rc::Rc<dyn Object>
            }
            Some(b'-' | b'0'..=b'9') => self.number(),
            Some(_) => self.fail("Unexpected character"),
            None => self.fail("Unexpected end of input"),
        }
    }

    fn object(&mut self) -> std::rc::Rc<dyn Object> {
        self.at += 1;
        let mut map: Map<String, std::rc::Rc<dyn Object>> = Map::new();
        self.skip_space();
        if self.peek() == Some(b'}') {
            self.at += 1;
            return std::rc::Rc::new(map) as std::rc::Rc<dyn Object>;
        }
        loop {
            self.skip_space();
            if self.peek() != Some(b'"') {
                self.fail("Expected string");
            }
            let key = self.string();
            self.skip_space();
            self.expect(":");
            self.skip_space();
            let value = self.value();
            let value = self.revive(
                Some(std::rc::Rc::new(key.clone()) as std::rc::Rc<dyn Object>),
                value,
            );
            map.insert(key, value);
            self.skip_space();
            match self.peek() {
                Some(b',') => self.at += 1,
                Some(b'}') => {
                    self.at += 1;
                    return std::rc::Rc::new(map) as std::rc::Rc<dyn Object>;
                }
                _ => self.fail("Expected ',' or '}'"),
            }
        }
    }

    fn array(&mut self) -> std::rc::Rc<dyn Object> {
        self.at += 1;
        let mut list: Vec<std::rc::Rc<dyn Object>> = Vec::new();
        self.skip_space();
        if self.peek() == Some(b']') {
            self.at += 1;
            return std::rc::Rc::new(list) as std::rc::Rc<dyn Object>;
        }
        loop {
            self.skip_space();
            let value = self.value();
            let index = list.len() as i64;
            let value = self.revive(
                Some(std::rc::Rc::new(index) as std::rc::Rc<dyn Object>),
                value,
            );
            list.push(value);
            self.skip_space();
            match self.peek() {
                Some(b',') => self.at += 1,
                Some(b']') => {
                    self.at += 1;
                    return std::rc::Rc::new(list) as std::rc::Rc<dyn Object>;
                }
                _ => self.fail("Expected ',' or ']'"),
            }
        }
    }

    fn number(&mut self) -> std::rc::Rc<dyn Object> {
        let start = self.at;
        let mut integral = true;
        if self.peek() == Some(b'-') {
            self.at += 1;
        }
        while matches!(self.peek(), Some(b'0'..=b'9')) {
            self.at += 1;
        }
        if self.peek() == Some(b'.') {
            integral = false;
            self.at += 1;
            while matches!(self.peek(), Some(b'0'..=b'9')) {
                self.at += 1;
            }
        }
        if matches!(self.peek(), Some(b'e' | b'E')) {
            integral = false;
            self.at += 1;
            if matches!(self.peek(), Some(b'+' | b'-')) {
                self.at += 1;
            }
            while matches!(self.peek(), Some(b'0'..=b'9')) {
                self.at += 1;
            }
        }
        let text = std::str::from_utf8(&self.text[start..self.at]).unwrap_or("");
        if integral {
            if let Ok(i) = text.parse::<i64>() {
                return std::rc::Rc::new(i) as std::rc::Rc<dyn Object>;
            }
        }
        match text.parse::<f64>() {
            Ok(d) => std::rc::Rc::new(d) as std::rc::Rc<dyn Object>,
            Err(_) => self.fail("Invalid number"),
        }
    }

    fn hex4(&mut self) -> u32 {
        let end = self.at + 4;
        if end > self.text.len() {
            self.fail("Unterminated unicode escape");
        }
        let digits = std::str::from_utf8(&self.text[self.at..end]).unwrap_or("");
        match u32::from_str_radix(digits, 16) {
            Ok(code) => {
                self.at = end;
                code
            }
            Err(_) => self.fail("Invalid unicode escape"),
        }
    }

    fn string(&mut self) -> String {
        self.at += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            let byte = match self.peek() {
                Some(b) => b,
                None => self.fail("Unterminated string"),
            };
            self.at += 1;
            match byte {
                b'"' => break,
                b'\\' => {
                    let escaped = match self.peek() {
                        Some(b) => b,
                        None => self.fail("Unterminated string"),
                    };
                    self.at += 1;
                    match escaped {
                        b'"' => out.push(b'"'),
                        b'\\' => out.push(b'\\'),
                        b'/' => out.push(b'/'),
                        b'b' => out.push(8),
                        b'f' => out.push(12),
                        b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'),
                        b't' => out.push(b'\t'),
                        b'u' => {
                            let mut code = self.hex4();
                            if (0xD800..0xDC00).contains(&code)
                                && self.text[self.at..].starts_with(b"\\u")
                            {
                                self.at += 2;
                                let low = self.hex4();
                                if (0xDC00..0xE000).contains(&low) {
                                    code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                } else {
                                    self.at -= 6;
                                }
                            }
                            let ch = char::from_u32(code).unwrap_or('\u{FFFD}');
                            let mut buffer = [0u8; 4];
                            out.extend_from_slice(ch.encode_utf8(&mut buffer).as_bytes());
                        }
                        _ => self.fail("Invalid escape"),
                    }
                }
                b => out.push(b),
            }
        }
        String::from_utf8(out).unwrap_or_else(|_| self.fail("Invalid UTF-8"))
    }
}

/// What a value out of a `dynamic` becomes in a typed collection: the
/// conversions Dart's runtime does not need, because `Map<String, dynamic>`
/// and `Map<String, Object?>` are one type there and two here (`json.decode`
/// cast `as Map<String, Object?>`, ws473). A translated class's downcast
/// is exact; a handle is asked of the object (`dart_cast_to`).
///
/// On every type a type parameter can be bound to, as `DartNullable` is:
/// Dart's `cast<K, V>` takes any `K`, so a generic body's
/// `result.cast<K, V>()` asks it of a bare `K`, and a bound only where a
/// body asks would have to be repeated by everything naming the generic
/// (`invokeMapMethod<K, V>`, run494). The backend writes the impl for
/// each translated struct and enum; a type that cannot come back out of
/// a `dynamic` answers `None`, which the cast reports.
pub trait FromDynamic: Sized + 'static {
    fn from_dynamic(value: &std::rc::Rc<dyn Object>) -> Option<Self>;

    /// A value of this very type again, from a reference to one: a clone
    /// where the type has one. A collection's exact-typed elements come out
    /// this way, and so ask no `Clone` of the element type in the bound --
    /// a declaration's parameters carry none (`Equality<Iterable<E>>`,
    /// ws495); a type without one (a boxed future) has no value to give.
    fn from_same(value: &Self) -> Option<Self> {
        let _ = value;
        None
    }

    fn from_nullable(value: &Option<std::rc::Rc<dyn Object>>) -> Option<Self> {
        match value {
            Some(v) => Self::from_dynamic(v),
            None => Self::from_dynamic(&(std::rc::Rc::new(Null) as std::rc::Rc<dyn Object>)),
        }
    }
}

/// A handle: the value itself when that is the handle asked for (`T` is
/// `dyn Object`), else the object asked for it -- its own `Rc<Struct>`,
/// or an `Rc<dyn Trait>` it implements (`dart_cast_to`).
impl<T: ?Sized + 'static> FromDynamic for std::rc::Rc<T> {
    fn from_dynamic(value: &std::rc::Rc<dyn Object>) -> Option<Self> {
        let same: Box<dyn std::any::Any> = Box::new(value.clone());
        match same.downcast::<std::rc::Rc<T>>() {
            Ok(handle) => Some(*handle),
            // ..the object as the handle, or a handle boxed as an object,
            // or the typed closure a `Function` object was made from
            // (`dart_function_same`): a listener stored in an
            // `ObserverList<T>` with `T` erased comes back as the
            // `Rc<dyn Fn(AnimationStatus)>` it was added as (run635).
            Err(_) => value
                .dart_cast_to::<T>()
                .or_else(|| value.as_any().downcast_ref::<std::rc::Rc<T>>().cloned())
                .or_else(|| {
                    let object: &dyn Object = value.as_ref();
                    object
                        .as_any()
                        .downcast_ref::<DartFunction>()
                        .and_then(|f| f.original.downcast_ref::<std::rc::Rc<T>>().cloned())
                }),
        }
    }
    fn from_same(value: &Self) -> Option<Self> {
        Some(value.clone())
    }
}

/// `void`: whatever the value, nothing is kept of it.
impl FromDynamic for () {
    fn from_dynamic(_value: &std::rc::Rc<dyn Object>) -> Option<Self> {
        Some(())
    }
    fn from_same(_value: &Self) -> Option<Self> {
        Some(())
    }
}

/// The rest of the types a type parameter can be bound to: none of
/// them comes out of a `dynamic` here (a boxed future, a record, a
/// completer), and the cast reports it.
macro_rules! from_dynamic_never {
    ($(impl<$($p:ident),*> $t:ty;)*) => {
        $(
            impl<$($p: 'static),*> FromDynamic for $t {
                fn from_dynamic(_value: &std::rc::Rc<dyn Object>) -> Option<Self> {
                    None
                }
            }
        )*
    };
}

from_dynamic_never! {
    impl<A, B> (A, B);
    impl<A, B, C> (A, B, C);
    impl<A, B, C, D> (A, B, C, D);
    impl<T> Completer<T>;
    impl<T> Stream<T>;
    impl<T> Point<T>;
    impl<K, V> MapEntry<K, V>;
    impl<T> DartFuture<T>;
    impl<T> FutureOr<T>;
    impl<T, E> Result<T, E>;
    impl<S, T> Converter<S, T>;
}

impl<F: ?Sized + 'static> FromDynamic for std::pin::Pin<Box<F>> {
    fn from_dynamic(_value: &std::rc::Rc<dyn Object>) -> Option<Self> {
        None
    }
}

/// `x as Set<T>` on an object: see `dart_cast_list`.
pub fn dart_cast_set<T: FromDynamic + DartEq>(value: &std::rc::Rc<dyn Object>) -> Option<Set<T>> {
    let object: &dyn Object = value.as_ref();
    let any = object.as_any();
    if let Some(set) = any.downcast_ref::<Set<T>>() {
        let items: Option<Vec<T>> = set.items.iter().map(T::from_same).collect();
        return items.map(|items| Set { items });
    }
    fn convert<T1: Clone + 'static, T: FromDynamic + DartEq>(
        any: &dyn std::any::Any,
        element: fn(&T1) -> Option<T>,
    ) -> Option<Option<Set<T>>> {
        let set = any.downcast_ref::<Set<T1>>()?;
        let mut out: Vec<T> = Vec::new();
        for e in set.items.iter() {
            match element(e) {
                Some(t) => out.push(t),
                None => return Some(None),
            }
        }
        Some(Some(Set::from_converted(out)))
    }
    if let Some(r) = convert::<std::rc::Rc<dyn Object>, T>(any, T::from_dynamic) {
        return r;
    }
    if let Some(r) = convert::<Option<std::rc::Rc<dyn Object>>, T>(any, T::from_nullable) {
        return r;
    }
    None
}

impl<T: FromDynamic + DartEq> FromDynamic for Set<T> {
    fn from_same(value: &Self) -> Option<Self> {
        let items: Option<Vec<T>> = value.items.iter().map(T::from_same).collect();
        items.map(|items| Set { items })
    }
    fn from_dynamic(value: &std::rc::Rc<dyn Object>) -> Option<Self> {
        dart_cast_set::<T>(value)
    }
}

/// A nullable of anything convertible: Dart's null (the `Null` object)
/// is `None`, else the value converted.
impl<T: FromDynamic> FromDynamic for Option<T> {
    fn from_dynamic(value: &std::rc::Rc<dyn Object>) -> Option<Self> {
        let object: &dyn Object = value.as_ref();
        if object.as_any().is::<Null>() {
            return Some(None);
        }
        T::from_dynamic(value).map(Some)
    }
    fn from_same(value: &Self) -> Option<Self> {
        match value {
            None => Some(None),
            Some(v) => T::from_same(v).map(Some),
        }
    }
}

/// A generic method of a trait, called through a trait object: Rust keeps
/// such a method out of the vtable (`where Self: Sized`), so the call goes
/// by the method's *erased twin* (`m__erased`, its type parameters read as
/// `Object`) and the result comes back to what the call site declared
/// through this conversion (`MethodChannel.invokeMethod<String>` on a
/// `MethodChannel` field, 19 stubs at ws479).
pub trait CastErased<To> {
    fn cast_erased(self) -> To;
}

fn erased_cast_failed(value: &std::rc::Rc<dyn Object>) -> ! {
    panic!(
        "uncaught Dart exception: TypeError: a value of type '{}' came back through an erased method where another type was declared",
        value.runtime_type().name
    )
}

impl<T: FromDynamic> CastErased<T> for std::rc::Rc<dyn Object> {
    fn cast_erased(self) -> T {
        match T::from_dynamic(&self) {
            Some(v) => v,
            None => erased_cast_failed(&self),
        }
    }
}

impl<T: FromDynamic> CastErased<Option<T>> for Option<std::rc::Rc<dyn Object>> {
    fn cast_erased(self) -> Option<T> {
        match self {
            None => None,
            // The `Null` object inside a `Some` is null too: an erased
            // `dart_cast_any::<Rc<dyn Object>>()` of an absent value answers
            // with it (the gentrait fixture's `get<Blue>()` on a map without
            // one).
            Some(v) => match dart_nullable(v) {
                None => None,
                Some(v) => match T::from_dynamic(&v) {
                    Some(t) => Some(t),
                    None => erased_cast_failed(&v),
                },
            },
        }
    }
}

/// `invokeMethod<void>`: whatever came back is dropped.
impl CastErased<()> for Option<std::rc::Rc<dyn Object>> {
    fn cast_erased(self) {}
}

impl<A: Clone + 'static, B: Clone + 'static + FromDynamic> CastErased<DartFuture<B>>
    for DartFuture<A>
where
    A: CastErased<B>,
{
    fn cast_erased(self) -> DartFuture<B> {
        self.then(std::rc::Rc::new(|v: A| Ok(v.cast_erased())), None)
    }
}

/// Dart's bare `Function` -- a value with no signature, called dynamically:
/// its arguments arrive as objects and its result leaves as one, converted
/// at both ends by the type rules (`coerce` builds the adapters, so a
/// `void Function(int)` stored as a `Function` reads its `int` out of the
/// object and hands back the `Null` object). Spelled as the object it is
/// (`Rc<dyn Object>`); made by `dart_function_object`, called by
/// `dart_call_function`, and taken back into a typed function slot by an
/// adapter the other way. `then(onError: Function?)` forwarded from a
/// translated `Future` (`TickerFuture.then`, ws513).
pub type DartFunctionCall =
    dyn Fn(Vec<std::rc::Rc<dyn Object>>) -> Result<std::rc::Rc<dyn Object>, DartError>;

pub struct DartFunction {
    pub arity: usize,
    pub call: std::rc::Rc<DartFunctionCall>,
    /// The typed function it was made from, for a slot of that very type
    /// (`dart_function_same`): the same handle back, so `removeListener(f)`
    /// finds what `addListener(f)` stored.
    pub original: std::rc::Rc<dyn std::any::Any>,
    /// The function's identity (the handle's address): Dart's `==` on two
    /// function values (`ObserverList.contains(listener)`).
    pub identity: usize,
}

impl Clone for DartFunction {
    fn clone(&self) -> Self {
        DartFunction {
            arity: self.arity,
            call: self.call.clone(),
            original: self.original.clone(),
            identity: self.identity,
        }
    }
}

impl PartialEq for DartFunction {
    fn eq(&self, other: &Self) -> bool {
        self.identity == other.identity
    }
}

impl DartAny for DartFunction {
    fn dart_runtime_type(&self) -> Type {
        Type::of("Function")
    }
}

pub fn dart_function_object<F: ?Sized + 'static>(
    arity: usize,
    function: std::rc::Rc<F>,
    call: std::rc::Rc<DartFunctionCall>,
) -> std::rc::Rc<dyn Object> {
    let identity = std::rc::Rc::as_ptr(&function) as *const () as usize;
    let original: std::rc::Rc<dyn std::any::Any> = std::rc::Rc::new(function);
    dart_object(DartFunction {
        arity,
        call,
        original,
        identity,
    }) as std::rc::Rc<dyn Object>
}

fn dart_function_of(object: &std::rc::Rc<dyn Object>) -> &DartFunction {
    let any: &dyn Object = object.as_ref();
    match any.as_any().downcast_ref::<DartFunction>() {
        Some(function) => function,
        None => panic!(
            "dart2rust: a {} called as a function",
            object.runtime_type().name
        ),
    }
}

/// The typed function a `Function` was made from, when it is of type `F`.
pub fn dart_function_same<F: ?Sized + 'static>(
    object: std::rc::Rc<dyn Object>,
) -> Option<std::rc::Rc<F>> {
    dart_function_of(&object)
        .original
        .downcast_ref::<std::rc::Rc<F>>()
        .cloned()
}

/// Out of a `dynamic` into a type with a conversion of its own: Dart's
/// cast, failing as one does.
pub fn dart_from_dynamic<T: FromDynamic>(value: std::rc::Rc<dyn Object>) -> T {
    match T::from_dynamic(&value) {
        Some(converted) => converted,
        None => panic!(
            "dart2rust: a {} where a `{}` was wanted",
            value.runtime_type().name,
            std::any::type_name::<T>()
        ),
    }
}

/// How many positional arguments the function takes.
pub fn dart_function_arity(object: &std::rc::Rc<dyn Object>) -> usize {
    dart_function_of(object).arity
}

/// Dart's dynamic call on a `Function`: an error on the wrong number of
/// arguments, as Dart's `NoSuchMethodError` is.
pub fn dart_call_function(
    object: std::rc::Rc<dyn Object>,
    args: Vec<std::rc::Rc<dyn Object>>,
) -> Result<std::rc::Rc<dyn Object>, DartError> {
    let function = dart_function_of(&object);
    if function.arity != args.len() {
        return Err(std::rc::Rc::new(StateError::new(format!(
            "a function of {} argument(s) called with {}",
            function.arity,
            args.len()
        ))) as DartError);
    }
    (function.call)(args)
}

/// What a dynamically called callback handed back, as the `FutureOr<R>` a
/// `then` wants: the `FutureOr` or `Future` it is, else the `R` value.
pub fn dart_future_or_from_dynamic<R: FromDynamic + Clone + 'static>(
    value: std::rc::Rc<dyn Object>,
) -> Result<FutureOr<R>, DartError> {
    let object: &dyn Object = value.as_ref();
    if let Some(future_or) = object.as_any().downcast_ref::<FutureOr<R>>() {
        return Ok(future_or.clone());
    }
    if let Some(future) = object.as_any().downcast_ref::<DartFuture<R>>() {
        return Ok(FutureOr::Future(future.clone()));
    }
    match R::from_dynamic(&value) {
        Some(r) => Ok(FutureOr::Value(Some(r))),
        None => Err(std::rc::Rc::new(StateError::new(format!(
            "a {} where a `{}` was wanted",
            value.runtime_type().name,
            std::any::type_name::<R>()
        ))) as DartError),
    }
}

/// `Future.then`'s and `catchError`'s `onError`, a `Function` of one
/// argument (the error) or two (the error and its stack trace), as Dart
/// dispatches it.
pub fn dart_call_error_handler<R: FromDynamic + Clone + 'static>(
    handler: std::rc::Rc<dyn Object>,
    error: DartError,
) -> Result<FutureOr<R>, DartError> {
    let args: Vec<std::rc::Rc<dyn Object>> = if dart_function_arity(&handler) >= 2 {
        vec![
            error,
            std::rc::Rc::new(StackTrace::current()) as std::rc::Rc<dyn Object>,
        ]
    } else {
        vec![error]
    };
    dart_future_or_from_dynamic::<R>(dart_call_function(handler, args)?)
}

pub fn dart_cast_erased<To, From: CastErased<To>>(value: From) -> To {
    value.cast_erased()
}

impl<T: FromDynamic> FromDynamic for Vec<T> {
    fn from_same(value: &Self) -> Option<Self> {
        value.iter().map(T::from_same).collect()
    }
    fn from_dynamic(value: &std::rc::Rc<dyn Object>) -> Option<Self> {
        dart_cast_list::<T>(value)
    }
}

impl<K: FromDynamic + DartEq, V: FromDynamic> FromDynamic for Map<K, V> {
    fn from_same(value: &Self) -> Option<Self> {
        let entries: Option<Vec<(K, V)>> = value
            .entries
            .iter()
            .map(|(k, v)| Some((K::from_same(k)?, V::from_same(v)?)))
            .collect();
        entries.map(|entries| Map { entries })
    }
    fn from_dynamic(value: &std::rc::Rc<dyn Object>) -> Option<Self> {
        dart_cast_map::<K, V>(value)
    }
}

/// `m.cast<K2, V2>()` / `xs.cast<T2>()`: a copy with each element
/// converted (`FromDynamic`), which is the representation change Dart's
/// `cast` does not need and this one does.
impl<K: DartAny + Clone + 'static, V: DartAny + Clone + 'static> Map<K, V> {
    pub fn cast_to<K2: FromDynamic + DartEq, V2: FromDynamic>(&self) -> Map<K2, V2> {
        let mut out: Vec<(K2, V2)> = Vec::new();
        for (k, v) in self.entries.iter() {
            let key: std::rc::Rc<dyn Object> = dart_boxed(k.clone());
            let value: std::rc::Rc<dyn Object> = dart_boxed(v.clone());
            match (K2::from_dynamic(&key), V2::from_dynamic(&value)) {
                (Some(k2), Some(v2)) => out.push((k2, v2)),
                _ => erased_cast_failed(&value),
            }
        }
        Map::from_converted(out)
    }
}

impl<T: DartAny + Clone + 'static> Set<T> {
    pub fn cast_to<T2: FromDynamic + DartEq>(&self) -> Set<T2> {
        let mut out: Vec<T2> = Vec::new();
        for v in self.iter() {
            let value: std::rc::Rc<dyn Object> = dart_boxed(v.clone());
            match T2::from_dynamic(&value) {
                Some(t) => out.push(t),
                None => erased_cast_failed(&value),
            }
        }
        Set::from_converted(out)
    }
}

pub trait DartListCast {
    fn cast_to<T2: FromDynamic>(&self) -> Vec<T2>;
}

impl<T: DartAny + Clone + 'static> DartListCast for Vec<T> {
    fn cast_to<T2: FromDynamic>(&self) -> Vec<T2> {
        self.iter()
            .map(|v| {
                let value: std::rc::Rc<dyn Object> = dart_boxed(v.clone());
                match T2::from_dynamic(&value) {
                    Some(t) => t,
                    None => erased_cast_failed(&value),
                }
            })
            .collect()
    }
}

/// A `TypedData`'s bytes: what `Uint8List.sublistView(data)` and
/// `ByteData.sublistView(data)` read, from a `Uint8List` (`Vec<u8>`), a
/// `List<int>` or a `ByteData`.
pub trait AsDartBytes {
    fn dart_bytes(&self) -> Vec<u8>;
}

impl AsDartBytes for Vec<u8> {
    fn dart_bytes(&self) -> Vec<u8> {
        self.clone()
    }
}

impl AsDartBytes for Vec<i64> {
    fn dart_bytes(&self) -> Vec<u8> {
        self.iter().map(|b| *b as u8).collect()
    }
}

impl AsDartBytes for ByteData {
    fn dart_bytes(&self) -> Vec<u8> {
        self.bytes.clone()
    }
}

fn dart_byte_range(bytes: Vec<u8>, start: i64, end: Option<i64>) -> Vec<u8> {
    let from = (start.max(0) as usize).min(bytes.len());
    let to = match end {
        Some(e) => (e.max(0) as usize).clamp(from, bytes.len()),
        None => bytes.len(),
    };
    bytes[from..to].to_vec()
}

/// `Uint8List.sublistView(data, [start, end])`: a copy of the byte range
/// (a view is a value here, as every list is).
pub fn uint8_list_sublist_view<T: AsDartBytes>(data: T, start: i64, end: Option<i64>) -> Vec<u8> {
    dart_byte_range(data.dart_bytes(), start, end)
}

/// `ByteData.sublistView(data, [start, end])`.
pub fn byte_data_sublist_view<T: AsDartBytes>(data: T, start: i64, end: Option<i64>) -> ByteData {
    ByteData::view(dart_byte_range(data.dart_bytes(), start, end), 0, None)
}

/// `x as List<T>` on an object: the list as it is when it is one of `T`,
/// else each element of a `List<dynamic>` / `List<Object?>` converted.
pub fn dart_cast_list<T: FromDynamic>(value: &std::rc::Rc<dyn Object>) -> Option<Vec<T>> {
    // The object's `Any`, not the handle's: `Rc<dyn Object>` is `'static`
    // and so an `Object` itself under the blanket impl.
    let object: &dyn Object = value.as_ref();
    let any = object.as_any();
    if let Some(list) = any.downcast_ref::<Vec<T>>() {
        return list.iter().map(T::from_same).collect();
    }
    if let Some(list) = any.downcast_ref::<Vec<std::rc::Rc<dyn Object>>>() {
        return list.iter().map(T::from_dynamic).collect();
    }
    if let Some(list) = any.downcast_ref::<Vec<Option<std::rc::Rc<dyn Object>>>>() {
        return list.iter().map(T::from_nullable).collect();
    }
    // Any other list, through the fully dynamic one it can become (see
    // `Vec`'s `dart_cast`).
    if let Some(dynamic) = value.dart_cast_any::<Vec<std::rc::Rc<dyn Object>>>() {
        return dynamic.iter().map(T::from_dynamic).collect();
    }
    None
}

/// `x as Map<K, V>` on an object: see `dart_cast_list`.
pub fn dart_cast_map<K: FromDynamic + DartEq, V: FromDynamic>(
    value: &std::rc::Rc<dyn Object>,
) -> Option<Map<K, V>> {
    let object: &dyn Object = value.as_ref();
    let any = object.as_any();
    if let Some(map) = any.downcast_ref::<Map<K, V>>() {
        let entries: Option<Vec<(K, V)>> = map
            .entries
            .iter()
            .map(|(k, v)| Some((K::from_same(k)?, V::from_same(v)?)))
            .collect();
        return entries.map(|entries| Map { entries });
    }
    fn convert<
        K1: Clone + 'static,
        V1: Clone + 'static,
        K: FromDynamic + DartEq,
        V: FromDynamic,
    >(
        any: &dyn std::any::Any,
        key: fn(&K1) -> Option<K>,
        value: fn(&V1) -> Option<V>,
    ) -> Option<Option<Map<K, V>>> {
        let map = any.downcast_ref::<Map<K1, V1>>()?;
        let mut out: Vec<(K, V)> = Vec::new();
        for (k, v) in map.entries.iter() {
            match (key(k), value(v)) {
                (Some(k), Some(v)) => out.push((k, v)),
                _ => return Some(None),
            }
        }
        Some(Some(Map::from_converted(out)))
    }
    if let Some(r) = convert::<String, std::rc::Rc<dyn Object>, K, V>(
        any,
        |k| K::from_dynamic(&(std::rc::Rc::new(k.clone()) as std::rc::Rc<dyn Object>)),
        V::from_dynamic,
    ) {
        return r;
    }
    if let Some(r) = convert::<String, Option<std::rc::Rc<dyn Object>>, K, V>(
        any,
        |k| K::from_dynamic(&(std::rc::Rc::new(k.clone()) as std::rc::Rc<dyn Object>)),
        V::from_nullable,
    ) {
        return r;
    }
    if let Some(r) = convert::<std::rc::Rc<dyn Object>, std::rc::Rc<dyn Object>, K, V>(
        any,
        K::from_dynamic,
        V::from_dynamic,
    ) {
        return r;
    }
    if let Some(r) = convert::<std::rc::Rc<dyn Object>, Option<std::rc::Rc<dyn Object>>, K, V>(
        any,
        K::from_dynamic,
        V::from_nullable,
    ) {
        return r;
    }
    if let Some(r) = convert::<Option<std::rc::Rc<dyn Object>>, Option<std::rc::Rc<dyn Object>>, K, V>(
        any,
        K::from_nullable,
        V::from_nullable,
    ) {
        return r;
    }
    // Any other map, through the fully dynamic one it can become (see
    // `Map`'s `dart_cast`).
    if let Some(dynamic) =
        value.dart_cast_any::<Map<std::rc::Rc<dyn Object>, std::rc::Rc<dyn Object>>>()
    {
        let entries: Option<Vec<(K, V)>> = dynamic
            .entries
            .iter()
            .map(|(k, v)| Some((K::from_dynamic(k)?, V::from_dynamic(v)?)))
            .collect();
        return entries.map(Map::from_converted);
    }
    None
}

/// What a JSON value is written from: the scalars, `null`, a list, a map
/// with string keys (Dart's encoder takes `Map<String, dynamic>`; a
/// `dynamic` key that is a string passes too), and a `dynamic`, which is
/// asked what it holds (`json_write`).
pub trait JsonPiece {
    fn json_write(&self, out: &mut String);
}

fn json_write_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
}

impl JsonPiece for String {
    fn json_write(&self, out: &mut String) {
        json_write_string(out, self)
    }
}
impl JsonPiece for i64 {
    fn json_write(&self, out: &mut String) {
        out.push_str(&self.to_string())
    }
}
impl JsonPiece for f64 {
    fn json_write(&self, out: &mut String) {
        out.push_str(&self.to_string())
    }
}
impl JsonPiece for bool {
    fn json_write(&self, out: &mut String) {
        out.push_str(if *self { "true" } else { "false" })
    }
}
impl JsonPiece for Null {
    fn json_write(&self, out: &mut String) {
        out.push_str("null")
    }
}
impl JsonPiece for () {
    fn json_write(&self, out: &mut String) {
        out.push_str("null")
    }
}
impl<T: JsonPiece> JsonPiece for Option<T> {
    fn json_write(&self, out: &mut String) {
        match self {
            Some(v) => v.json_write(out),
            None => out.push_str("null"),
        }
    }
}
impl<T: JsonPiece> JsonPiece for Vec<T> {
    fn json_write(&self, out: &mut String) {
        out.push('[');
        for (i, v) in self.iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            v.json_write(out);
        }
        out.push(']');
    }
}
impl<K: JsonKey, V: JsonPiece> JsonPiece for Map<K, V> {
    fn json_write(&self, out: &mut String) {
        out.push('{');
        let mut first = true;
        for (k, v) in self.entries.iter() {
            if !first {
                out.push(',');
            }
            first = false;
            json_write_string(out, &k.json_key());
            out.push(':');
            v.json_write(out);
        }
        out.push('}');
    }
}
impl JsonPiece for std::rc::Rc<dyn Object> {
    fn json_write(&self, out: &mut String) {
        json_write(out, self)
    }
}

/// A map's key as JSON's string: a `String`, or a `dynamic` holding one
/// (Dart's encoder refuses any other key).
pub trait JsonKey {
    fn json_key(&self) -> String;
}
impl JsonKey for String {
    fn json_key(&self) -> String {
        self.clone()
    }
}
impl JsonKey for std::rc::Rc<dyn Object> {
    fn json_key(&self) -> String {
        match self.as_any().downcast_ref::<String>() {
            Some(s) => s.clone(),
            None => panic!(
                "uncaught Dart exception: JsonUnsupportedObjectError: a map key of type '{}'",
                self.runtime_type().name
            ),
        }
    }
}
impl<K: JsonKey> JsonKey for Option<K> {
    fn json_key(&self) -> String {
        match self {
            Some(k) => k.json_key(),
            None => panic!("uncaught Dart exception: JsonUnsupportedObjectError: a null map key"),
        }
    }
}

/// A `dynamic` written as JSON: asked, by type, for each shape a value
/// can be boxed as -- the scalars, `null`, and the lists and maps of
/// those and of `dynamic`, two levels deep. The table, not a rule: a
/// boxed `Vec<String>` is its own type behind the handle, and nothing
/// but a list of shapes can find it (`JSONMethodCodec.encodeMethodCall`'s
/// `<String, Object?>{'method': .., 'args': ..}`, run496).
macro_rules! json_dynamic_shapes {
    ($out:ident, $any:ident; $($t:ty),* $(,)?) => {
        $(
            if let Some(v) = $any.downcast_ref::<$t>() {
                v.json_write($out);
                return;
            }
        )*
    };
}

macro_rules! json_dynamic_containers {
    ($out:ident, $any:ident; $($e:ty),* $(,)?) => {
        $(
            json_dynamic_shapes!($out, $any; Vec<$e>, Map<String, $e>, Map<std::rc::Rc<dyn Object>, $e>, Map<Option<std::rc::Rc<dyn Object>>, $e>);
        )*
    };
}

fn json_write(out: &mut String, value: &std::rc::Rc<dyn Object>) {
    let any = value.as_any();
    json_dynamic_shapes!(out, any; String, i64, f64, bool, Null, (), Option<std::rc::Rc<dyn Object>>, Option<String>, Option<i64>, Option<f64>, Option<bool>);
    json_dynamic_containers!(out, any; std::rc::Rc<dyn Object>, Option<std::rc::Rc<dyn Object>>, String, Option<String>, i64, Option<i64>, f64, Option<f64>, bool, Option<bool>);
    json_dynamic_containers!(out, any;
        Vec<std::rc::Rc<dyn Object>>, Vec<Option<std::rc::Rc<dyn Object>>>, Vec<String>, Vec<i64>, Vec<f64>, Vec<bool>,
        Map<String, std::rc::Rc<dyn Object>>, Map<String, Option<std::rc::Rc<dyn Object>>>, Map<String, String>, Map<String, i64>, Map<String, f64>, Map<String, bool>,
        Map<std::rc::Rc<dyn Object>, std::rc::Rc<dyn Object>>, Map<std::rc::Rc<dyn Object>, Option<std::rc::Rc<dyn Object>>>,
        Map<Option<std::rc::Rc<dyn Object>>, Option<std::rc::Rc<dyn Object>>>);
    panic!(
        "dart2rust: JsonCodec.encode of a {}",
        value.runtime_type().name
    );
}

/// `dart:convert`'s `utf8`, a `const Utf8Codec()`: a name for now.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Utf8Codec;

impl Utf8Codec {
    /// `utf8.decode(bytes, {allowMalformed})`: lossy when malformed is
    /// allowed, and a panic (Dart's `FormatException`) when it is not.
    pub fn decode(&self, bytes: Vec<i64>, allow_malformed: Option<bool>) -> String {
        let raw: Vec<u8> = bytes.into_iter().map(|b| b as u8).collect();
        match String::from_utf8(raw) {
            Ok(s) => s,
            Err(e) => {
                if allow_malformed.unwrap_or(false) {
                    String::from_utf8_lossy(e.as_bytes()).into_owned()
                } else {
                    panic!("uncaught Dart exception: FormatException: {}", e)
                }
            }
        }
    }

    /// `utf8.encode(string)`.
    /// `utf8.encode(s)`: a `Uint8List`, which is `Vec<u8>` here
    /// (`GetStorage.flush` held one, ws481).
    pub fn encode(&self, string: String) -> Vec<u8> {
        string.into_bytes()
    }

    /// `utf8.decoder`.
    pub fn decoder(&self) -> Utf8Decoder {
        Utf8Decoder
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct Encoding {
    pub name: String,
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct TypedData;

#[derive(Clone, Debug, Default, PartialEq)]
pub struct ByteBuffer {
    pub bytes: Vec<u8>,
}

/// `ArgumentError([message, name])`: its constructor has two parameters,
/// and 14 of 15 calls pass both, so it is not the macro's one-parameter
/// `new`. The message is `dynamic` upstream; here anything that prints.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ArgumentError {
    pub message: String,
    pub name: Option<String>,
}

impl ArgumentError {
    /// `ArgumentError.checkNotNull(value, [name])`: the value, or a panic
    /// where Dart throws.
    pub fn check_not_null<T>(value: Option<T>, name: Option<String>) -> T {
        value.unwrap_or_else(|| {
            panic!(
                "ArgumentError: {} must not be null",
                name.unwrap_or_default()
            )
        })
    }

    /// `ArgumentError([dynamic message, String? name])`.
    pub fn new(message: std::rc::Rc<dyn Object>, name: Option<String>) -> Self {
        ArgumentError {
            message: dart_message(&message),
            name,
        }
    }
}

impl fmt::Display for ArgumentError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match &self.name {
            Some(name) => write!(f, "Invalid argument ({}): {}", name, self.message),
            None if self.message.is_empty() => f.write_str("Invalid argument(s)"),
            None => write!(f, "Invalid argument(s): {}", self.message),
        }
    }
}

impl ArgumentError {
    /// `ArgumentError.value(value, [name, message])`.
    pub fn value(
        value: std::rc::Rc<dyn Object>,
        name: Option<String>,
        message: std::rc::Rc<dyn Object>,
    ) -> Self {
        let text = dart_message(&message);
        ArgumentError {
            message: if text.is_empty() {
                dart_str(&value)
            } else {
                format!("{}: {}", text, dart_str(&value))
            },
            name,
        }
    }
}
dart_error!(UnsupportedError, "Unsupported operation");
/// `UnimplementedError([String? message])`: the message is optional, as
/// Dart declares it, where the other errors' is not.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct UnimplementedError {
    pub message: Option<String>,
}

impl UnimplementedError {
    pub fn new(message: Option<String>) -> Self {
        UnimplementedError { message }
    }
}

impl fmt::Display for UnimplementedError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match &self.message {
            Some(message) if !message.is_empty() => write!(f, "UnimplementedError: {}", message),
            _ => f.write_str("UnimplementedError"),
        }
    }
}
/// `FormatException([message, source, offset])`: three parameters, as
/// intl's date parsing passes them.
#[derive(Clone, Debug)]
pub struct FormatException {
    pub message: String,
    /// `dynamic source`: an `Rc<dyn Object>` as translated code spells
    /// `dynamic`, `Null` when none was given.
    pub source: std::rc::Rc<dyn Object>,
    pub offset: Option<i64>,
}

impl Default for FormatException {
    fn default() -> Self {
        FormatException {
            message: String::new(),
            source: std::rc::Rc::new(Null),
            offset: None,
        }
    }
}

impl FormatException {
    pub fn new(message: String, source: std::rc::Rc<dyn Object>, offset: Option<i64>) -> Self {
        FormatException {
            message,
            source,
            offset,
        }
    }
}

/// The source by identity, as a `dynamic` field of a translated struct
/// compares (`DartEq`).
impl PartialEq for FormatException {
    fn eq(&self, other: &Self) -> bool {
        self.message == other.message
            && std::rc::Rc::ptr_eq(&self.source, &other.source)
            && self.offset == other.offset
    }
}

impl fmt::Display for FormatException {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.message.is_empty() {
            f.write_str("FormatException")
        } else {
            write!(f, "FormatException: {}", self.message)
        }
    }
}
/// `AssertionError([Object? message])`: the message is Dart's `Object?`,
/// read as one (`AssertionError(message: final Object? msg)` in
/// `BindingBase._initListenable`, run451); `new` takes the text the
/// backend's own asserts spell.
#[derive(Clone, Debug)]
pub struct AssertionError {
    /// Dart's `Object?`: a `dynamic` here, whose null is the `Null` object.
    pub message: std::rc::Rc<dyn Object>,
}

impl Default for AssertionError {
    fn default() -> Self {
        AssertionError {
            message: dart_null_object(),
        }
    }
}

impl AssertionError {
    pub fn new(message: String) -> Self {
        AssertionError {
            message: std::rc::Rc::new(message) as std::rc::Rc<dyn Object>,
        }
    }
}

impl PartialEq for AssertionError {
    fn eq(&self, other: &Self) -> bool {
        self.message.dart_eq(&other.message)
    }
}

impl fmt::Display for AssertionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match dart_nullable(self.message.clone()) {
            None => f.write_str("Assertion failed"),
            Some(m) => write!(f, "Assertion failed: {}", dart_message(&m)),
        }
    }
}

impl DartEq for AssertionError {
    fn dart_eq(&self, other: &Self) -> bool {
        self == other
    }
}
dart_error!(ConcurrentModificationError, "Concurrent modification");

/// `IndexError`, with the one constructor upstream uses: `withLength`.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct IndexError {
    pub message: String,
    pub index: i64,
    pub length: i64,
}

impl IndexError {
    /// `IndexError(invalidValue, indexable, [name, message, length])`.
    pub fn new<T>(
        index: i64,
        _indexable: T,
        name: Option<String>,
        message: Option<String>,
        length: Option<i64>,
    ) -> Self {
        IndexError {
            message: message.unwrap_or_else(|| {
                format!(
                    "Index out of range{}: {}",
                    name.map(|n| format!(" ({})", n)).unwrap_or_default(),
                    index
                )
            }),
            index,
            length: length.unwrap_or(0),
        }
    }

    pub fn with_length(
        index: i64,
        length: i64,
        _indexable: Option<std::rc::Rc<dyn Object>>,
        name: Option<String>,
        message: Option<String>,
    ) -> Self {
        let message = message.unwrap_or_else(|| {
            format!(
                "Index out of range: {}: {}",
                name.unwrap_or_default(),
                index
            )
        });
        IndexError {
            message,
            index,
            length,
        }
    }
}

impl fmt::Display for IndexError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "RangeError (index): {}", self.message)
    }
}

/// `dart:math`'s `Random`: `nextInt`, `nextDouble`, `nextBool`.
///
/// A xorshift64*, seeded from the clock when no seed is given. Not Dart's
/// generator, and not meant to reproduce its sequence: upstream uses this for
/// demo data and jitter, where any decent generator will do. A test that
/// pins a sequence would be the first to say otherwise.
#[derive(Clone, Debug)]
pub struct Random {
    state: u64,
}

impl Random {
    pub fn new(seed: Option<i64>) -> Self {
        let seed = seed.map(|s| s as u64).unwrap_or_else(|| {
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_nanos() as u64)
                .unwrap_or(0x9E3779B97F4A7C15)
        });
        Random { state: seed | 1 }
    }

    fn next_u64(&mut self) -> u64 {
        let mut x = self.state;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.state = x;
        x.wrapping_mul(0x2545F4914F6CDD1D)
    }

    pub fn next_int(&mut self, max: i64) -> i64 {
        (self.next_u64() % (max.max(1) as u64)) as i64
    }

    pub fn next_double(&mut self) -> f64 {
        (self.next_u64() >> 11) as f64 / (1u64 << 53) as f64
    }

    pub fn next_bool(&mut self) -> bool {
        self.next_u64() & 1 == 1
    }
}

/// `RangeError`, which carries the bounds it was given.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct RangeError {
    pub message: String,
    pub start: Option<f64>,
    pub end: Option<f64>,
}

impl RangeError {
    pub fn new(message: String) -> Self {
        RangeError {
            message,
            start: None,
            end: None,
        }
    }

    /// `RangeError.checkValidRange(start, end, length, [startName, endName,
    /// message])`: the end, or a panic where Dart throws.
    pub fn check_valid_range(
        start: i64,
        end: Option<i64>,
        length: i64,
        start_name: Option<String>,
        end_name: Option<String>,
        message: Option<String>,
    ) -> i64 {
        let end = end.unwrap_or(length);
        if start < 0 || start > length || end < start || end > length {
            panic!(
                "RangeError: {}",
                message.unwrap_or_else(|| format!(
                    "Invalid range {}..{} ({}, {}) for length {}",
                    start,
                    end,
                    start_name.unwrap_or_default(),
                    end_name.unwrap_or_default(),
                    length
                ))
            );
        }
        end
    }

    /// `RangeError.checkNotNegative(value, [name, message])`: the value, or
    /// a panic where Dart throws -- a static of the prelude's has no
    /// `Result` signature to carry it.
    pub fn check_not_negative(value: i64, name: Option<String>, message: Option<String>) -> i64 {
        if value < 0 {
            panic!(
                "RangeError: {}",
                message.unwrap_or_else(|| format!(
                    "{}: must not be negative: {}",
                    name.unwrap_or_else(|| "index".to_string()),
                    value
                ))
            );
        }
        value
    }

    /// `RangeError.range(value, min, max, [name, message])`.
    pub fn range(
        invalid: i64,
        min: Option<i64>,
        max: Option<i64>,
        name: Option<String>,
        message: Option<String>,
    ) -> Self {
        RangeError {
            message: message.unwrap_or_else(|| {
                format!(
                    "Invalid value{}: not in range {}..{}: {}",
                    name.map(|n| format!(" for {}", n)).unwrap_or_default(),
                    min.map(|m| m.to_string()).unwrap_or_default(),
                    max.map(|m| m.to_string()).unwrap_or_default(),
                    invalid
                )
            }),
            start: min.map(|m| m as f64),
            end: max.map(|m| m as f64),
        }
    }
}

impl fmt::Display for RangeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "RangeError: {}", self.message)
    }
}

/// `dart:typed_data`'s fixed-element lists.
///
/// Aliases rather than wrappers: a Dart typed list *is* a list of that element
/// type as far as everything upstream does with it, and an alias keeps every
/// `List` operation the backend already emits working on it.
pub type Uint8List = Vec<u8>;
pub type Int8List = Vec<i8>;
pub type Uint16List = Vec<u16>;
pub type Int16List = Vec<i16>;
pub type Uint32List = Vec<u32>;
pub type Int32List = Vec<i32>;
pub type Uint64List = Vec<u64>;
pub type Int64List = Vec<i64>;
pub type Float32List = Vec<f32>;
pub type Float64List = Vec<f64>;

/// Dart's `ByteData`: a view over bytes with typed accessors.
///
/// Little-endian by default, which is what `Endian.host` is on every platform
/// Flutter ships to. Dart's accessors take an optional `Endian`; the ones that
/// pass one explicitly are not translated yet and will say so rather than
/// silently reading the other way round.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ByteData {
    bytes: Vec<u8>,
}

impl ByteData {
    /// `asUnmodifiableView()`: a `ByteData` here is already a value.
    pub fn as_unmodifiable_view(&self) -> ByteData {
        self.clone()
    }

    /// `offsetInBytes`: a `ByteData` here owns its bytes, so it starts at 0.
    pub fn offset_in_bytes(&self) -> i64 {
        0
    }

    fn at(&self, offset: i64, width: usize) -> &[u8] {
        let start = offset.max(0) as usize;
        &self.bytes[start.min(self.bytes.len())..(start + width).min(self.bytes.len())]
    }

    fn le(&self, endian: Endian) -> bool {
        endian == Endian::Little
    }

    /// `getUint64`/`setUint64`: Dart's `int` is 64-bit signed, so the bits
    /// are the same and the sign is the reader's problem, as in Dart.
    pub fn get_uint64(&self, offset: i64, endian: Endian) -> i64 {
        self.get_int64(offset, endian)
    }

    pub fn set_uint64(&mut self, offset: i64, value: i64, endian: Endian) {
        self.set_int64(offset, value, endian)
    }

    pub fn get_int64(&self, offset: i64, endian: Endian) -> i64 {
        let mut b = [0u8; 8];
        b.copy_from_slice(self.at(offset, 8));
        if self.le(endian) {
            i64::from_le_bytes(b)
        } else {
            i64::from_be_bytes(b)
        }
    }

    pub fn set_int64(&mut self, offset: i64, value: i64, endian: Endian) {
        let b = if self.le(endian) {
            value.to_le_bytes()
        } else {
            value.to_be_bytes()
        };
        let start = offset.max(0) as usize;
        self.bytes[start..start + 8].copy_from_slice(&b);
    }

    pub fn new(length: i64) -> Self {
        ByteData {
            bytes: vec![0; length.max(0) as usize],
        }
    }

    /// `ByteData.view(buffer, [offsetInBytes, length])`: a copy of that
    /// window, since a buffer here is the bytes themselves.
    pub fn view(bytes: Vec<u8>, offset: i64, length: Option<i64>) -> Self {
        let start = (offset.max(0) as usize).min(bytes.len());
        let end = match length {
            Some(n) => (start + n.max(0) as usize).min(bytes.len()),
            None => bytes.len(),
        };
        ByteData {
            bytes: bytes[start..end].to_vec(),
        }
    }

    pub fn length_in_bytes(&self) -> i64 {
        self.bytes.len() as i64
    }

    pub fn buffer(&self) -> Vec<u8> {
        self.bytes.clone()
    }

    pub fn get_uint8(&self, at: i64) -> i64 {
        self.bytes[at as usize] as i64
    }

    pub fn set_uint8(&mut self, at: i64, value: i64) {
        self.bytes[at as usize] = value as u8;
    }

    pub fn get_int8(&self, at: i64) -> i64 {
        self.bytes[at as usize] as i8 as i64
    }

    pub fn set_int8(&mut self, at: i64, value: i64) {
        self.bytes[at as usize] = value as i8 as u8;
    }

    pub fn get_uint16(&self, at: i64, _endian: Endian) -> i64 {
        u16::from_le_bytes(self.four(at, 2)[..2].try_into().unwrap()) as i64
    }
    pub fn set_uint16(&mut self, at: i64, value: i64, _endian: Endian) {
        let bytes = (value as u16).to_le_bytes();
        let at = at as usize;
        self.bytes[at..at + 2].copy_from_slice(&bytes);
    }
    pub fn get_int16(&self, at: i64, _endian: Endian) -> i64 {
        let at = at as usize;
        i16::from_le_bytes([self.bytes[at], self.bytes[at + 1]]) as i64
    }
    pub fn set_int16(&mut self, at: i64, value: i64, _endian: Endian) {
        let bytes = (value as i16).to_le_bytes();
        let at = at as usize;
        self.bytes[at..at + 2].copy_from_slice(&bytes);
    }

    pub fn get_int32(&self, at: i64, _endian: Endian) -> i64 {
        i32::from_le_bytes(self.four(at, 4)[..4].try_into().unwrap()) as i64
    }

    pub fn set_int32(&mut self, at: i64, value: i64, _endian: Endian) {
        let at = at as usize;
        self.bytes[at..at + 4].copy_from_slice(&(value as i32).to_le_bytes());
    }

    pub fn get_uint32(&self, at: i64, _endian: Endian) -> i64 {
        u32::from_le_bytes(self.four(at, 4)[..4].try_into().unwrap()) as i64
    }

    pub fn set_uint32(&mut self, at: i64, value: i64, _endian: Endian) {
        let at = at as usize;
        self.bytes[at..at + 4].copy_from_slice(&(value as u32).to_le_bytes());
    }

    pub fn get_float32(&self, at: i64, _endian: Endian) -> f64 {
        f32::from_le_bytes(self.four(at, 4)[..4].try_into().unwrap()) as f64
    }

    pub fn set_float32(&mut self, at: i64, value: f64, _endian: Endian) {
        let at = at as usize;
        self.bytes[at..at + 4].copy_from_slice(&(value as f32).to_le_bytes());
    }

    pub fn get_float64(&self, at: i64, _endian: Endian) -> f64 {
        f64::from_le_bytes(self.eight(at)[..8].try_into().unwrap())
    }

    pub fn set_float64(&mut self, at: i64, value: f64, _endian: Endian) {
        let at = at as usize;
        self.bytes[at..at + 8].copy_from_slice(&value.to_le_bytes());
    }

    fn four(&self, at: i64, n: usize) -> [u8; 4] {
        let at = at as usize;
        let mut out = [0u8; 4];
        out[..n].copy_from_slice(&self.bytes[at..at + n]);
        out
    }

    fn eight(&self, at: i64) -> [u8; 8] {
        let at = at as usize;
        let mut out = [0u8; 8];
        out.copy_from_slice(&self.bytes[at..at + 8]);
        out
    }
}
